INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26910, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "倍数", "is_correct": true, "explanation": "正确：“倍数”指能被另一个数整除的数。"}, {"text": "背书", "is_correct": false, "explanation": "声调不同：“背书”（bèi shū）与“倍数”（bèi shù）后一音节声调不同，意思是背诵课文。"}, {"text": "倍速", "is_correct": false, "explanation": "声母不同：“倍速”（bèi sù）与“倍数”后一音节声母不同（s 与 sh），意思是速度的倍率。"}, {"text": "辈出", "is_correct": false, "explanation": "音近：“辈出”（bèi chū）与“倍数”（bèi shù）前一音节相同，后一音节声母和声调不同，意思是人才接连出现。"}], "explanations": {"倍数": "正确：“倍数”指能被另一个数整除的数。", "背书": "声调不同：“背书”（bèi shū）与“倍数”（bèi shù）后一音节声调不同，意思是背诵课文。", "倍速": "声母不同：“倍速”（bèi sù）与“倍数”后一音节声母不同（s 与 sh），意思是速度的倍率。", "辈出": "音近：“辈出”（bèi chū）与“倍数”（bèi shù）前一音节相同，后一音节声母和声调不同，意思是人才接连出现。"}, "sentence_index": null, "correct_answer": "倍数"}, "level_3": {"options": [{"text": "倍数", "is_correct": true, "explanation": "正确：“十八是六的倍数”指十八能被六整除，与“也是九的倍数”的结构一致。"}, {"text": "因数", "is_correct": false, "explanation": "语义：六是十八的因数，说“十八是六的因数”方向颠倒，与事实不符。"}, {"text": "约数", "is_correct": false, "explanation": "语义：“约数”指能整除某数的数，“十八是六的约数”方向颠倒。"}, {"text": "公约数", "is_correct": false, "explanation": "搭配：“公约数”需要两个数作定语，不能只说“六的公约数”。"}], "explanations": {"倍数": "正确：“十八是六的倍数”指十八能被六整除，与“也是九的倍数”的结构一致。", "因数": "语义：六是十八的因数，说“十八是六的因数”方向颠倒，与事实不符。", "约数": "语义：“约数”指能整除某数的数，“十八是六的约数”方向颠倒。", "公约数": "搭配：“公约数”需要两个数作定语，不能只说“六的公约数”。"}, "sentence_index": 0, "correct_answer": "倍数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "十是六十的倍数。", "explanation": "这里应该用〈因数〉。十能整除六十，十是六十的因数；倍数指能被另一个数整除的数。"}, {"text": "六的倍数只有六个。", "explanation": "词义错误：“倍数”有无限个，不限于几个；说“只有六个”是把〈因数〉的有限性误用到倍数上。"}, {"text": "二十一除以四，倍数是五余一。", "explanation": "这里应该用〈商〉。二十一除以四得到的是商和余数；倍数指能被另一个数整除的数，不能表示除法的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倍数", "is_correct": true, "explanation": "正确：“两个偶数的和还是二的倍数”指和仍能被二整除，符合偶数的性质。"}, {"text": "整数", "is_correct": false, "explanation": "搭配：“整数”不与“二的”组合，不说“二的整数”。"}, {"text": "平方", "is_correct": false, "explanation": "语义：“二的平方”是四，与“两个偶数的和还是二的……”的数量关系不符。"}, {"text": "奇数", "is_correct": false, "explanation": "语义：偶数之和仍是偶数，不会是奇数，说“二的奇数”与句意矛盾。"}], "explanations": {"倍数": "正确：“两个偶数的和还是二的倍数”指和仍能被二整除，符合偶数的性质。", "整数": "搭配：“整数”不与“二的”组合，不说“二的整数”。", "平方": "语义：“二的平方”是四，与“两个偶数的和还是二的……”的数量关系不符。", "奇数": "语义：偶数之和仍是偶数，不会是奇数，说“二的奇数”与句意矛盾。"}, "sentence_index": 6, "correct_answer": "倍数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在纸上算出，二十除以三的倍数是二。", "explanation": "这里应该用〈余数〉。二十除以三余下的二是余数；倍数指能被整除的数，不能指没除尽的部分。"}, {"text": "三是十二的倍数。", "explanation": "这里应该用〈因数〉。三能整除十二，三是十二的因数；倍数指能被另一个数整除的数。"}, {"text": "两个班的人数倍数是三比二。", "explanation": "这里应该用〈比率〉。倍数指能被整除的数，不表示两个数的比较关系；说“三比二”要用〈比率〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "二十四是八倍数，也是六的倍数。", "corrected_sentence": "二十四是八的倍数，也是六的倍数。", "error_description": "“的”遗漏：“八的倍数”中间需要“的”，不能说“八倍数”。正确说法是“八的倍数”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这盒糖有十二颗，正好是三的一只倍数。", "corrected_sentence": "这盒糖有十二颗，正好是三的一个倍数。", "error_description": "量词错误：“倍数”是数学概念，应该用“个”，不用“只”。正确说法是“三的一个倍数”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
