INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26916, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "涡轮机是一种机器，它靠气流或水流推动叶轮转动，常用来发电。", "primary_collocate": null, "pronunciation": "wō lún jī", "ipa": "wɔ˥ lu̯ən˧˥ tɕi˥", "syllable_count": 3, "sentences": [{"text": "河水推着涡轮机转动，就能发电。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的风很大，农场装了涡轮机。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那台涡轮机一转，灯就亮了。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水从高处流下来，冲得涡轮机转个不停。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边有一排白色的涡轮机。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了涡轮机发电的视频。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有风，涡轮机就不会转。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇靠涡轮机发电。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台涡轮机是用河水来发电的。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太小的时候，涡轮机转得很慢。", "target_word": "涡轮机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一台涡轮机", "label": "量词"}, {"form": "渦輪機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "靠气流或水流推动叶轮转动的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bc74ad3-fce1-4a1c-a4e5-5f5ab986044a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26916, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "涡轮机", "is_correct": true, "explanation": "涡轮机靠水流推动转动发电，与句中“河水推着……转动，就能发电”一致。"}, {"text": "锅炉", "is_correct": false, "explanation": "语义：锅炉靠烧水产生蒸汽，不是靠水流推动转动发电。"}, {"text": "变压器", "is_correct": false, "explanation": "搭配：变压器没有转动部件，不能说“推着……转动”。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：洗衣机是用来洗衣服的，河水推它不能发电。"}], "explanations": {"涡轮机": "涡轮机靠水流推动转动发电，与句中“河水推着……转动，就能发电”一致。", "锅炉": "语义：锅炉靠烧水产生蒸汽，不是靠水流推动转动发电。", "变压器": "搭配：变压器没有转动部件，不能说“推着……转动”。", "洗衣机": "语义：洗衣机是用来洗衣服的，河水推它不能发电。"}, "sentence_index": 0, "correct_answer": "涡轮机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用涡轮机把衣服洗干净了。", "explanation": "这里应该用〈洗衣机〉。涡轮机是用来发电的机器，洗衣服要用洗衣机。"}, {"text": "他把饭菜放进涡轮机里保鲜。", "explanation": "这里应该用〈冰箱〉。涡轮机用来发电，不能用来保鲜食物。"}, {"text": "我们坐涡轮机到了十楼。", "explanation": "这里应该用〈电梯〉。涡轮机是发电的机器，不能载人上楼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740a8dd6-612a-4984-b445-3f0ac1250d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26916, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "涡轮机", "is_correct": true, "explanation": "涡轮机靠风转动，与句中“没有风”呼应，只有它合适。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：冰箱靠压缩机制冷，不说“转”，也与“没有风”无关。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯靠钢缆升降，不靠风转动。"}, {"text": "水泵", "is_correct": false, "explanation": "语义：水泵由电动机带动，与风无关，“没有风，水泵就不会转”不成立。"}], "explanations": {"涡轮机": "涡轮机靠风转动，与句中“没有风”呼应，只有它合适。", "冰箱": "搭配：冰箱靠压缩机制冷，不说“转”，也与“没有风”无关。", "电梯": "语义：电梯靠钢缆升降，不靠风转动。", "水泵": "语义：水泵由电动机带动，与风无关，“没有风，水泵就不会转”不成立。"}, "sentence_index": 6, "correct_answer": "涡轮机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜里他用涡轮机照路。", "explanation": "这里应该用〈手电筒〉。涡轮机是用来发电的机器，照路要用手电筒。"}, {"text": "夏天的涡轮机一转，屋里就凉快了。", "explanation": "这里应该用〈电风扇〉。涡轮机用来发电，不是用来送风降温的。"}, {"text": "涡轮机一开，水就热了。", "explanation": "这里应该用〈热水器〉。涡轮机用来发电，不用来加热水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740a8dd6-612a-4984-b445-3f0ac1250d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山顶上装了三只涡轮机。", "corrected_sentence": "山顶上装了三台涡轮机。", "error_description": "量词用错：“只”不能用于涡轮机。涡轮机是机器，应说“三台涡轮机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740a8dd6-612a-4984-b445-3f0ac1250d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河边新装了两辆涡轮机。", "corrected_sentence": "河边新装了两台涡轮机。", "error_description": "量词用错：“辆”用于车辆。涡轮机是机器，应说“两台涡轮机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740a8dd6-612a-4984-b445-3f0ac1250d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
