INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26918, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26918, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "激光雷达是一种用激光来测量距离的机器，像眼睛一样帮助汽车看到周围的东西。", "primary_collocate": null, "pronunciation": "jī guāng léi dá", "ipa": "tɕi˥ kwɑŋ˥ lei˧˥ ta˧˥", "syllable_count": 4, "sentences": [{"text": "这辆车的车顶有一个激光雷达。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "激光雷达像眼睛一样，能看见周围的路。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "激光雷达用激光测量汽车和前车的距离。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人靠激光雷达知道墙在哪里。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，激光雷达还能看清路上的东西。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在新闻里看过这种激光雷达。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小机器人身上装着激光雷达。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "激光雷达发出的光，我们的眼睛看不见。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了激光雷达，汽车就不会撞到人。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一台激光雷达的照片。", "target_word": "激光雷达", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "车载激光雷达", "label": "复合"}], "register": "中性", "sense_fingerprint": "用激光测距、像眼睛一样帮汽车看清周围的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe61e7f-e641-46d1-b96e-b3aaed6264ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "激光雷达", "is_correct": true, "explanation": "正确：车顶可以安装激光雷达，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是车辆的装置，车顶不会有冰箱。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象是动物，不可能出现在车顶。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：车顶一般安装传感器等装置，“车顶有一个沙发”不符合常见说法。"}], "explanations": {"激光雷达": "正确：车顶可以安装激光雷达，符合句意。", "冰箱": "语义：冰箱不是车辆的装置，车顶不会有冰箱。", "大象": "语义：大象是动物，不可能出现在车顶。", "沙发": "搭配：车顶一般安装传感器等装置，“车顶有一个沙发”不符合常见说法。"}, "sentence_index": 0, "correct_answer": "激光雷达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门口的激光雷达拍下了小偷的脸。", "explanation": "这里应该用〈摄像头〉。摄像头用来拍摄图像，激光雷达靠激光测距离，不能“拍下”人脸。"}, {"text": "激光雷达能测出房间的温度。", "explanation": "这里应该用〈温度计〉。温度计用来测温度，激光雷达测的是距离，不测温度。"}, {"text": "激光雷达能告诉我们哪边是北。", "explanation": "这里应该用〈指南针〉。指南针用来指示方向，激光雷达测量距离，不指示方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "激光雷达", "is_correct": true, "explanation": "正确：小机器人身上可以装激光雷达，与“小”不冲突，符合句意。"}, {"text": "卡车", "is_correct": false, "explanation": "体貌：卡车体积庞大，装不到小机器人身上，与“小”的体形矛盾。"}, {"text": "摩天大楼", "is_correct": false, "explanation": "体貌：摩天大楼的体积与“小机器人”差距悬殊，无法装在其身上。"}, {"text": "书架", "is_correct": false, "explanation": "语义：书架是放书的家具，不能装在小机器人身上。"}], "explanations": {"激光雷达": "正确：小机器人身上可以装激光雷达，与“小”不冲突，符合句意。", "卡车": "体貌：卡车体积庞大，装不到小机器人身上，与“小”的体形矛盾。", "摩天大楼": "体貌：摩天大楼的体积与“小机器人”差距悬殊，无法装在其身上。", "书架": "语义：书架是放书的家具，不能装在小机器人身上。"}, "sentence_index": 6, "correct_answer": "激光雷达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "激光雷达能称出我的体重。", "explanation": "这里应该用〈体重秤〉。体重秤用来称重，激光雷达用来测距离，不能称体重。"}, {"text": "激光雷达能记录我走了多少步。", "explanation": "这里应该用〈计步器〉。计步器用来记录步数，激光雷达不记录步数。"}, {"text": "激光雷达能测出我的血压高低。", "explanation": "这里应该用〈血压计〉。血压计用来测血压，激光雷达测的是距离和速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们给无人车装上了一棵激光雷达。", "corrected_sentence": "他们给无人车装上了一台激光雷达。", "error_description": "量词错误：“棵”用于树木、植物，不能用于激光雷达，应说“一台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂的工人用一棵激光雷达检查机器人的手臂。", "corrected_sentence": "工厂的工人用一台激光雷达检查机器人的手臂。", "error_description": "量词错误：“棵”用于树木、植物，不能用于激光雷达，应说“一台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
