INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26920, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "风跑得有多快，就是风速。", "primary_collocate": null, "pronunciation": "fēng sù", "ipa": "fɤŋ˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "风速大的时候，我们不骑车了。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天风速太小，风筝飞不起来。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气预报说明天风速会变大。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风速越快，树叶动得越厉害。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的风速比城里大。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道今天的风速是多少吗？", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风速很快的时候，走路都很难。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天风速很小，湖面一点浪也没有。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸知道今天风速很大，决定不去爬山了。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风来的时候，风速特别快。", "target_word": "风速", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平均风速", "label": "复合"}, {"form": "风速计", "label": "复合"}], "register": "中性", "sense_fingerprint": "风有多快，风吹动的快慢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe61e7f-e641-46d1-b96e-b3aaed6264ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风速", "is_correct": true, "explanation": "正确：“风速大的时候，我们不骑车了”说的是风的快慢，符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重与骑车是否方便没有关系，“体重大的时候不骑车”没有合理的因果。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音大小与是否骑车无关，句子的因果关系不成立。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格大”不是常用说法，且与“不骑车”的因果不合。"}], "explanations": {"风速": "正确：“风速大的时候，我们不骑车了”说的是风的快慢，符合句意。", "体重": "语义：体重与骑车是否方便没有关系，“体重大的时候不骑车”没有合理的因果。", "声音": "语义：声音大小与是否骑车无关，句子的因果关系不成立。", "价格": "搭配：“价格大”不是常用说法，且与“不骑车”的因果不合。"}, "sentence_index": 0, "correct_answer": "风速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的风速很香，大家都爱吃。", "explanation": "这里应该用〈风味〉。风速指风的快慢，形容食物的味道要用“风味”。"}, {"text": "风速从东南转向西北了，树叶动得很厉害。", "explanation": "这里应该用〈风向〉。风速只说快慢，不说方向，描述转向要用“风向”。"}, {"text": "这位作家的风速很独特，读的人很多。", "explanation": "这里应该用〈风格〉。风速指风的快慢，描述写作特点要用“风格”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风速", "is_correct": true, "explanation": "正确：“风速很快的时候，走路都很难”说的是风的快慢，符合句意。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试的快慢与走路难不难没有关系，句子无法成立。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业的速度与走路难度无关，句意不通。"}, {"text": "利息", "is_correct": false, "explanation": "搭配：“利息很快”多指利息增长快，与“走路都很难”的语境不搭。"}], "explanations": {"风速": "正确：“风速很快的时候，走路都很难”说的是风的快慢，符合句意。", "考试": "语义：考试的快慢与走路难不难没有关系，句子无法成立。", "作业": "语义：作业的速度与走路难度无关，句意不通。", "利息": "搭配：“利息很快”多指利息增长快，与“走路都很难”的语境不搭。"}, "sentence_index": 6, "correct_answer": "风速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个村子的风速很特别，过年要吃饺子。", "explanation": "这里应该用〈风俗〉。风速指风的快慢，地方习惯要用“风俗”。"}, {"text": "他的风速很潇洒，大家都很佩服。", "explanation": "这里应该用〈风度〉。风速指风的快慢，形容人的举止风采要用“风度”。"}, {"text": "风速来了，屋顶都被掀翻了。", "explanation": "这里应该用〈风暴〉。风速是速度数值，不会“来”，描述风暴到来要用“风暴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天我们测量了湖边的一朵风速。", "corrected_sentence": "今天我们测量了湖边的风速。", "error_description": "量词错误：“朵”用于花、云等，不能用于风速，应直接说“湖边的风速”，不加量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们用仪器测了出今天的风速。", "corrected_sentence": "我们用仪器测出了今天的风速。", "error_description": "补语位置错误：“测出”是复合动词，了应放在补语之后，应说“测出了”，不能说“测了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
