INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26926, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "光照到东西上，又弹回来的光。", "primary_collocate": null, "pronunciation": "fǎn shè guāng", "ipa": "fan˨˩˦ ʂɤ˥˩ kwɑŋ˥", "syllable_count": 3, "sentences": [{"text": "太阳照在玻璃上，反射光很亮。", "target_word": "反射光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地板上有一片反射光。", "target_word": "反射光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拍照时要避开反射光。", "target_word": "反射光", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "反射光从水里跳到了天花板上。", "target_word": "反射光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里车灯的反射光很亮。", "target_word": "反射光", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "月亮本身不发光，我们看到的是反射光。", "target_word": "反射光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手表的反射光照到我脸上。", "target_word": "反射光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子用小镜子玩反射光。", "target_word": "反射光", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "白纸的反射光让屋子更亮。", "target_word": "反射光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗外雪地的反射光照进了屋里。", "target_word": "反射光", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "束", "label": "量词"}, {"form": "道", "label": "量词"}], "register": "中性", "sense_fingerprint": "照到东西上弹回来的光", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '757ee6c7-0919-4ea7-a065-58cc869d02b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26926, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反射光", "is_correct": true, "explanation": "反射光：照到东西上又弹回来的光。「太阳照在玻璃上，反射光很亮」符合语境。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：脚印不会因为太阳照在玻璃上而发亮，与语境不符。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：「很亮」不搭配「味道」，味道不能形容为亮。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜不会因为太阳照射而发亮，与语境不符。"}], "explanations": {"反射光": "反射光：照到东西上又弹回来的光。「太阳照在玻璃上，反射光很亮」符合语境。", "脚印": "语义：脚印不会因为太阳照在玻璃上而发亮，与语境不符。", "味道": "搭配：「很亮」不搭配「味道」，味道不能形容为亮。", "饭菜": "语义：饭菜不会因为太阳照射而发亮，与语境不符。"}, "sentence_index": 0, "correct_answer": "反射光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水中的反射光让鱼看起来变高了。", "explanation": "这里应该用〈折射光〉。光从水中斜射出来会发生折射，使鱼看起来位置变高；反射光只是光照到表面弹回，不能解释这种现象。"}, {"text": "他把屏幕上的反射光装进了口袋。", "explanation": "这里应该用〈硬币〉。反射光是弹回来的光，无法装进口袋；能装进口袋的应说「硬币」。"}, {"text": "他打开冰箱，拿出一瓶反射光。", "explanation": "这里应该用〈牛奶〉。冰箱里能用「瓶」装着拿出来的是牛奶这样的东西；反射光是弹回来的光，不能装在瓶子里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反射光", "is_correct": true, "explanation": "反射光：照到东西上又弹回来的光。「手表的反射光照到我脸上」符合语境。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声不是光，不能照到脸上。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：「照到」不搭配「香味」，香味不能像光一样照射。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步不是光，不能照到脸上。"}], "explanations": {"反射光": "反射光：照到东西上又弹回来的光。「手表的反射光照到我脸上」符合语境。", "歌声": "语义：歌声不是光，不能照到脸上。", "香味": "搭配：「照到」不搭配「香味」，香味不能像光一样照射。", "脚步": "语义：脚步不是光，不能照到脸上。"}, "sentence_index": 6, "correct_answer": "反射光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "反射光能穿过木板，照进屋里。", "explanation": "这里应该用〈X射线〉。X射线能穿透物体；反射光是光照到物体后弹回来的光，不能穿透木板。"}, {"text": "他拧开反射光的开关，屋里立刻亮了。", "explanation": "这里应该用〈电灯〉。电灯自身发光，可以开关；反射光是物体返回的光，没有开关。"}, {"text": "妈妈用反射光给我做了一件衣服。", "explanation": "这里应该用〈布〉。做衣服要用布；反射光是照到东西上弹回来的光，不能用来做衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "玻璃上有一只反射光。", "corrected_sentence": "玻璃上有一束反射光。", "error_description": "量词错误：「反射光」可用量词「束」「道」「片」等，「只」多用于动物，说「一只反射光」是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙上有一把反射光。", "corrected_sentence": "墙上有一道反射光。", "error_description": "量词错误：「反射光」应用量词「道」，「把」用于有柄的东西，不能用来数反射光。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c941484-a894-4f87-99ac-3fcd636edfd1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
