INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26928, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "行星和太阳在天空中的距离，用角度表示。", "primary_collocate": null, "pronunciation": "jù jiǎo", "ipa": "tɕy˥˩ tɕjaʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "距角是行星和太阳的天空距离。", "target_word": "距角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "按度数来说，水星的距角很小。", "target_word": "距角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金星的距角有时大，有时小。", "target_word": "距角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明在书上查到了火星的距角。", "target_word": "距角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "距角是一个用角度表示的数。", "target_word": "距角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个星历表列出了每天的距角。", "target_word": "距角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天文课上，我们学过距角。", "target_word": "距角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "距角小的行星，白天很难看到。", "target_word": "距角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她算出了今天水星的距角。", "target_word": "距角", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这颗行星的距角是三十度。", "target_word": "距角", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "最大距角", "label": "复合"}], "register": "书面", "sense_fingerprint": "距角|名词|行星和太阳在天空中的距离，用角度表示", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45a9c2e1-e793-492c-857c-afaaaa0fdb5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26928, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亮度", "is_correct": false, "explanation": "语义：亮度指光的强弱，不是天空中的距离，“亮度是……天空距离”说不通。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是时长，不能作为天空中两天体之间的距离。"}, {"text": "方向", "is_correct": false, "explanation": "搭配：“方向”指朝向，不能用于“是……的天空距离”这种定义式。"}, {"text": "距角", "is_correct": true, "explanation": "正确。这句是对该术语的定义，主语就是“距角”本身。"}], "explanations": {"亮度": "语义：亮度指光的强弱，不是天空中的距离，“亮度是……天空距离”说不通。", "时间": "语义：时间是时长，不能作为天空中两天体之间的距离。", "方向": "搭配：“方向”指朝向，不能用于“是……的天空距离”这种定义式。", "距角": "正确。这句是对该术语的定义，主语就是“距角”本身。"}, "sentence_index": 0, "correct_answer": "距角"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两条直线的距角是六十度。", "explanation": "这里应该用〈夹角〉。距角是行星与太阳之间的角距离，两条直线相交的角要说夹角。"}, {"text": "月亮与地球的距角约为三十八万公里。", "explanation": "这里应该用〈距离〉。距角用角度表示，不用公里计量；说几十万公里要用距离。"}, {"text": "这个指南针测得当地的距角约为三度。", "explanation": "这里应该用〈磁偏角〉。磁偏角是磁针北极与地理北极之间的夹角；距角指行星与太阳在天空中的角距离，不能用于指南针。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做菜的技术，与天文课的内容无关，句子不通。"}, {"text": "书法", "is_correct": false, "explanation": "语义：书法是写字的艺术，天文课上不学书法，句子与语境矛盾。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“学”的对象是知识或技能，“味道”不能作为“学过”的宾语。"}, {"text": "距角", "is_correct": true, "explanation": "正确。距角是天文课上学习的概念，指行星与太阳的角距离。"}], "explanations": {"烹饪": "语义：烹饪是做菜的技术，与天文课的内容无关，句子不通。", "书法": "语义：书法是写字的艺术，天文课上不学书法，句子与语境矛盾。", "味道": "搭配：“学”的对象是知识或技能，“味道”不能作为“学过”的宾语。", "距角": "正确。距角是天文课上学习的概念，指行星与太阳的角距离。"}, "sentence_index": 6, "correct_answer": "距角"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座塔的距角是五十米。", "explanation": "这里应该用〈高度〉。距角是天文学中行星与太阳的角距离，塔的高低要说高度。"}, {"text": "这幅画的距角很独特。", "explanation": "这里应该用〈视角〉。距角专指天文学中的角距离，观察画面的角度要说视角。"}, {"text": "这两地的距角是八小时。", "explanation": "这里应该用〈时差〉。时差指两地时刻的差别；距角是行星与太阳之间的角距离，不能用来说两地的时间差。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "火星的距角小很。", "corrected_sentence": "火星的距角小得很。", "error_description": "补语错误：程度补语“小得很”中的“得”不能省去，应说“距角小得很”，不能说“距角小很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "距角少的行星，白天很不容易看到。", "corrected_sentence": "距角小的行星，白天很不容易看到。", "error_description": "语义错误：“小”描述距角的大小，“少”用于数量，不能修饰距角，应说“距角小的行星”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
