INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26936, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一台单独的电脑，不跟别的电脑连在一起。", "primary_collocate": null, "pronunciation": "dān jī", "ipa": "tan⁵⁵ tɕi⁵⁵", "syllable_count": 2, "sentences": [{"text": "学校机房里还有几台单机，没有连网。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台单机放在办公室，只用来存资料。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了安全，财务室用的是单机。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把试卷放在单机上，不怕被人偷看。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台旧单机不能上网，也不能收邮件。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "单机和别的电脑没有线连着。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室的单机用来做重要的计算。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一台单机，专门写小说。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种单机不接网线，别人进不来。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家那台单机很旧，但是打字还行。", "target_word": "单机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "單機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一台不与其他电脑相连的电脑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '674055ee-37a4-449c-90de-84e97de325ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26936, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "单机", "is_correct": true, "explanation": "正确：单机指一台不与其他电脑相连的电脑。"}, {"text": "当机", "is_correct": false, "explanation": "dàng（第四声，韵尾 -ng）与 dān（第一声，韵尾 -n）声调和韵尾都不同，意思是电脑突然停止响应。"}, {"text": "班机", "is_correct": false, "explanation": "bān 与 dān 声母不同（b 与 d），意思是定期航班。"}, {"text": "蛋鸡", "is_correct": false, "explanation": "dàn（第四声）与 dān（第一声）声调不同，意思是下蛋的母鸡。"}, {"text": "单集", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，意思是电视剧的一集。"}], "explanations": {"单机": "正确：单机指一台不与其他电脑相连的电脑。", "当机": "dàng（第四声，韵尾 -ng）与 dān（第一声，韵尾 -n）声调和韵尾都不同，意思是电脑突然停止响应。", "班机": "bān 与 dān 声母不同（b 与 d），意思是定期航班。", "蛋鸡": "dàn（第四声）与 dān（第一声）声调不同，意思是下蛋的母鸡。", "单集": "jí（第二声）与 jī（第一声）声调不同，意思是电视剧的一集。"}, "sentence_index": null, "correct_answer": "单机"}, "level_3": {"options": [{"text": "单机", "is_correct": true, "explanation": "正确：单机指不与别的电脑相连的一台电脑，与“没有连网”一致。"}, {"text": "键盘", "is_correct": false, "explanation": "量词：键盘用“个”或“把”，不说“台”。"}, {"text": "鼠标", "is_correct": false, "explanation": "量词：鼠标用“个”或“只”，不说“台”。"}, {"text": "网线", "is_correct": false, "explanation": "搭配：网线用“根”计量，不说“台”；且网线本身用于连网。"}], "explanations": {"单机": "正确：单机指不与别的电脑相连的一台电脑，与“没有连网”一致。", "键盘": "量词：键盘用“个”或“把”，不说“台”。", "鼠标": "量词：鼠标用“个”或“只”，不说“台”。", "网线": "搭配：网线用“根”计量，不说“台”；且网线本身用于连网。"}, "sentence_index": 0, "correct_answer": "单机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只单机，专门写小说。", "explanation": "量词：“只”用于动物，电脑应用“台”，这里不能说“一只单机”。"}, {"text": "我的同事是一台单机，很会说话。", "explanation": "语义：这里把“单机”用成了形容人的〈独来独往〉义，但单机只指一台不与别的电脑相连的电脑，不能形容同事。"}, {"text": "这台单机跟办公室的电脑连在一起，可以共享文件。", "explanation": "语义：这里的“单机”被当成了〈联网〉的电脑。单机指不与别的电脑相连，连在一起应说“联网”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26936, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "单机", "is_correct": true, "explanation": "正确：单机指独立的电脑，可以用来做计算。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不用来做重要的计算。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯用于照明，不能用来做计算。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“做计算”需要能计算的工具，“小说”不能用来做计算。"}], "explanations": {"单机": "正确：单机指独立的电脑，可以用来做计算。", "玩具": "语义：玩具不用来做重要的计算。", "台灯": "语义：台灯用于照明，不能用来做计算。", "小说": "搭配：“做计算”需要能计算的工具，“小说”不能用来做计算。"}, "sentence_index": 6, "correct_answer": "单机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天用单机做饭，很方便。", "explanation": "语义：这里把“单机”当成了〈炉子〉用。单机是一台不与别的电脑相连的电脑，不能用来做饭。"}, {"text": "我用单机给妈妈发短信。", "explanation": "语义：这里把“单机”当成了〈手机〉用。单机是一台不与别的电脑相连的电脑，不能用来发短信。"}, {"text": "我每天都给这台单机喂水。", "explanation": "语义：这里把“单机”当成了〈宠物〉一类的活物来喂。单机是电脑，不能喂水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "财务室里有两本单机，专门用来算工资。", "corrected_sentence": "财务室里有两台单机，专门用来算工资。", "error_description": "量词错误：电脑应用“台”，“本”用于书，应改为“两台单机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张旧单机是学校发的，不能上网。", "corrected_sentence": "这台旧单机是学校发的，不能上网。", "error_description": "量词错误：“张”用于纸张等平面物件，电脑应用“台”，应改为“这台旧单机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
