INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26940, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "能装多少东西。", "primary_collocate": null, "pronunciation": "róng liàng", "ipa": "ɻʊŋ˧˥ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个书包容量很大，能装下三本书。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我这个行李箱的容量。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小盒子容量太小，放不下这么多糖。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个水桶的容量是二十升。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一个容量大的杯子。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱容量不够，牛奶放不进去了。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子容量大，我把衣服都放进去了。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一个容量更大的锅。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了看瓶子的容量，才倒水。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个饭盒容量不小，一顿饭够装了。", "target_word": "容量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大容量", "label": "复合"}, {"form": "小容量", "label": "复合"}], "register": "中性", "sense_fingerprint": "容量：东西里面能装多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '674055ee-37a4-449c-90de-84e97de325ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26940, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "容量", "is_correct": true, "explanation": "正确：容量指能装多少东西，与“能装下三本书”一致。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色不用“大”来形容，“书包颜色很大”不成立。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格高低与能否装下三本书无关。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能用来说能装多少，与“能装下三本书”矛盾。"}], "explanations": {"容量": "正确：容量指能装多少东西，与“能装下三本书”一致。", "颜色": "搭配：颜色不用“大”来形容，“书包颜色很大”不成立。", "价格": "语义：价格高低与能否装下三本书无关。", "味道": "语义：味道不能用来说能装多少，与“能装下三本书”矛盾。"}, "sentence_index": 0, "correct_answer": "容量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块木头的容量很大，搬起来很费力。", "explanation": "这里应该用〈体积〉。容量指能装多少，实心木头的大小用〈体积〉。"}, {"text": "这块饼干的容量很甜，我一口气吃完了。", "explanation": "这里应该用〈味道〉。容量指能装多少，不能用来形容甜味。"}, {"text": "这场电影的容量很长，我看了两个小时。", "explanation": "这里应该用〈时长〉。容量是能装多少，不能用来说时间长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "容量", "is_correct": true, "explanation": "正确：容量指能装多少东西，与“把衣服都放进去了”一致。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度与装衣服的多少无关，“速度大”不能说明能放进衣服。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：亮度指光的强弱，与能不能把衣服放进去无关。"}, {"text": "硬度", "is_correct": false, "explanation": "语义：硬度与能否把衣服放进去无关。"}], "explanations": {"容量": "正确：容量指能装多少东西，与“把衣服都放进去了”一致。", "速度": "语义：速度与装衣服的多少无关，“速度大”不能说明能放进衣服。", "亮度": "语义：亮度指光的强弱，与能不能把衣服放进去无关。", "硬度": "语义：硬度与能否把衣服放进去无关。"}, "sentence_index": 6, "correct_answer": "容量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台收音机的容量很大，楼下都能听见。", "explanation": "这里应该用〈音量〉。音量指声音大小，容量指能装多少东西。"}, {"text": "我把水倒进容量里，装满了再喝。", "explanation": "容量是名词，指能装多少，不能指装东西的容器，这里不成立。"}, {"text": "这杯咖啡的容量很苦，我喝不下去。", "explanation": "容量只能形容能装多少，不能用来形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个水壶的容量是两米。", "corrected_sentence": "这个水壶的容量是两升。", "error_description": "单位错误：容量用“升”计量，“米”是长度单位，应说“容量是两升”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们想办法增高了饮水机的容量。", "corrected_sentence": "我们想办法提高了饮水机的容量。", "error_description": "动词搭配：容量用“提高”或“增加”，“增高”用于高度，不说“增高容量”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
