INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26942, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变聪明，比如机器可以自己学习做事。", "primary_collocate": null, "pronunciation": "zhì néng huà", "ipa": "ʈʂɻ̩˥˩ nɤŋ˧˥ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "他想让家里的灯智能化。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手表智能化以后，能记录睡觉的时间。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂智能化了，机器自己就能做事。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司正在把汽车智能化。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人智能化后，可以自己学习。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的教室也智能化了。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱智能化以后，会提醒你买牛奶。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "给房子装上电脑，就能让它智能化。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老电视智能化后，可以上网看电影。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场智能化以后，机器会自己浇水。", "target_word": "智能化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "智能化了", "label": "体标"}, {"form": "智能化改造", "label": "复合"}], "register": "中性", "sense_fingerprint": "智能化：让东西变聪明，能自己学习做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '674055ee-37a4-449c-90de-84e97de325ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26942, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "智能化", "is_correct": true, "explanation": "正确。“让家里的灯智能化”指使灯具备自动控制能力，符合句意。"}, {"text": "发胖", "is_correct": false, "explanation": "语义：“发胖”只用于人或动物的身形，灯不会发胖。"}, {"text": "哭泣", "is_correct": false, "explanation": "配价：“哭泣”通常以人或动物为主体，不能让灯作施事。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”指身体不适，灯不会生病，此处语义不通。"}], "explanations": {"智能化": "正确。“让家里的灯智能化”指使灯具备自动控制能力，符合句意。", "发胖": "语义：“发胖”只用于人或动物的身形，灯不会发胖。", "哭泣": "配价：“哭泣”通常以人或动物为主体，不能让灯作施事。", "生病": "语义：“生病”指身体不适，灯不会生病，此处语义不通。"}, "sentence_index": 0, "correct_answer": "智能化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想让孩子智能化，每天多读书。", "explanation": "这里应该用〈变聪明〉。让人变得聪明要说“变聪明”；智能化只指让机器、物品具备判断和学习能力，不能用于孩子。"}, {"text": "这家洗衣店把衣服智能化得很干净。", "explanation": "这里应该用〈清洗〉。衣服洗干净要说清洗；智能化指让机器具备判断能力。"}, {"text": "这栋楼的墙已经智能化了，很结实。", "explanation": "这里应该用〈加固〉。墙变结实要说加固；智能化指使东西具备判断和学习能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26942, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "智能化", "is_correct": true, "explanation": "正确。“冰箱智能化以后”指冰箱具备判断、提醒功能，符合句意。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”指金属被氧化，与“提醒你买牛奶”的功能无关。"}, {"text": "漏水", "is_correct": false, "explanation": "语义：“冰箱漏水”之后不能接“会提醒你买牛奶”，语义冲突。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是人或动物的动作，冰箱不能作施事。"}], "explanations": {"智能化": "正确。“冰箱智能化以后”指冰箱具备判断、提醒功能，符合句意。", "生锈": "语义：“生锈”指金属被氧化，与“提醒你买牛奶”的功能无关。", "漏水": "语义：“冰箱漏水”之后不能接“会提醒你买牛奶”，语义冲突。", "咳嗽": "配价：“咳嗽”是人或动物的动作，冰箱不能作施事。"}, "sentence_index": 6, "correct_answer": "智能化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台空调能智能化温度，每天都很舒服。", "explanation": "这里应该用〈调节〉。温度要说调节；智能化是让机器具备判断能力，不能直接带温度作宾语。"}, {"text": "这篇文章已经智能化成英文了，大家都能看懂。", "explanation": "这里应该用〈翻译〉。文章换成另一种语言要说翻译；智能化不表示语言转换。"}, {"text": "农民每年都智能化很多蔬菜，卖给超市。", "explanation": "这里应该用〈种植〉。蔬菜的生长要说种植；智能化不能用于植物的种植。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想让这台旧空调智能化了，能自动调温。", "corrected_sentence": "我想让这台旧空调智能化，能自动调温。", "error_description": "“想”表示意愿，“让……智能化”尚未发生，不能在“智能化”后加“了”；应说“我想让这台旧空调智能化”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经把这间老仓库智能化了了，不用人看管。", "corrected_sentence": "我们已经把这间老仓库智能化了，不用人看管。", "error_description": "“了”重复：“智能化”后只用一个“了”表示完成，应说“把这间老仓库智能化了”，多出的那个“了”要去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '661bd332-4b88-4576-b577-20324bb1f995') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
