INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26944, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一下子跳得很高，升得很快。", "primary_collocate": null, "pronunciation": "yuè shēng", "ipa": "ɥe˥˩ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "飞机突然跃升，冲向高空。", "target_word": "跃升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "飞机拉起机头，跃升到三千米高空。", "target_word": "跃升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火箭点火后，一下子跃升到云层上面。", "target_word": "跃升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗机向上跃升，躲开了山峰。", "target_word": "跃升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烟花从地面跃升到半空。", "target_word": "跃升", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "直升机离开地面后，迅速跃升。", "target_word": "跃升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "无人机起飞后迅速跃升了二十米。", "target_word": "跃升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战斗机猛地跃升到敌机上方。", "target_word": "跃升", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "滑翔机借着上升气流跃升了一百米。", "target_word": "跃升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员拉起操纵杆，飞机跃升了五百米。", "target_word": "跃升", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跃升了", "label": "体标"}, {"form": "跃升过", "label": "体标"}], "register": "书面", "sense_fingerprint": "跃升|动词|物体猛地向上跳起、迅速升高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45a9c2e1-e793-492c-857c-afaaaa0fdb5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26944, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下降", "is_correct": false, "explanation": "语义：下降是向下运动，与“冲向高空”的方向矛盾。"}, {"text": "降落", "is_correct": false, "explanation": "语义：降落指着陆，与“冲向高空”的动作相反。"}, {"text": "沉没", "is_correct": false, "explanation": "搭配：“沉没”指船只或物体没入水中，飞机不说沉没。"}, {"text": "跃升", "is_correct": true, "explanation": "正确。跃升指猛地向上跳起、迅速升高，此处指飞机突然猛然上升。"}], "explanations": {"下降": "语义：下降是向下运动，与“冲向高空”的方向矛盾。", "降落": "语义：降落指着陆，与“冲向高空”的动作相反。", "沉没": "搭配：“沉没”指船只或物体没入水中，飞机不说沉没。", "跃升": "正确。跃升指猛地向上跳起、迅速升高，此处指飞机突然猛然上升。"}, "sentence_index": 0, "correct_answer": "跃升"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳缓缓跃升，照亮了大地。", "explanation": "这里应该用〈升起〉。跃升指猛然跳起、迅速升高，太阳慢慢升起不能用跃升。"}, {"text": "运动员沿着山路跃升，终于到达了山顶。", "explanation": "这里应该用〈攀登〉。跃升是猛然跳起、迅速上升，沿山路一步步走上去要说攀登。"}, {"text": "直升机慢慢跃升到了山顶上空。", "explanation": "这里应该用〈爬升〉。跃升指一下子跳得很高、升得很快，直升机缓缓上升到山顶要说爬升。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沉没", "is_correct": false, "explanation": "搭配：“沉没”用于船只等沉入水中，无人机不说沉没。"}, {"text": "复印", "is_correct": false, "explanation": "语义：复印是复制文件，与无人机上升的动作无关，句子不通。"}, {"text": "书写", "is_correct": false, "explanation": "语义：书写指写字，无人机不能书写，句子不通。"}, {"text": "跃升", "is_correct": true, "explanation": "正确。句中指无人机起飞后迅速上升了二十米。"}], "explanations": {"沉没": "搭配：“沉没”用于船只等沉入水中，无人机不说沉没。", "复印": "语义：复印是复制文件，与无人机上升的动作无关，句子不通。", "书写": "语义：书写指写字，无人机不能书写，句子不通。", "跃升": "正确。句中指无人机起飞后迅速上升了二十米。"}, "sentence_index": 6, "correct_answer": "跃升"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老鹰跃升向地面，抓住了一只老鼠。", "explanation": "这里应该用〈俯冲〉。跃升是猛然向上升，朝地面扑下去要说俯冲，方向相反。"}, {"text": "石头从悬崖上跃升，砸进了湖里。", "explanation": "这里应该用〈下落〉。跃升是向上升，石头砸进湖里是向下落，句中方向相反。"}, {"text": "花瓶从桌上跃升，摔碎在地上。", "explanation": "这里应该用〈跌落〉。跃升是向上升，花瓶摔碎在地上是向下跌落，方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "飞机跃升很高，冲向云层。", "corrected_sentence": "飞机跃升得很高，冲向云层。", "error_description": "补语错误：程度补语前须有“得”，应说“跃升得很高”，不能省去“得”直接接“很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "无人机起飞后很快就跃升了二十个。", "corrected_sentence": "无人机起飞后很快就跃升了二十米。", "error_description": "量词错误：距离用“米”计量，不能说“二十个”，正确说法是“跃升了二十米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd58b4158-fc4d-43e1-a537-f329b4639f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26946, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自下而上", "is_correct": true, "explanation": "正确：“自下而上”与“自上而下”表示相反的方向，是词典列出的反义词。"}, {"text": "慢慢", "is_correct": false, "explanation": "“慢慢”表示速度缓慢，与方向无关。"}, {"text": "突然", "is_correct": false, "explanation": "“突然”表示发生得很快，与方向无关。"}, {"text": "偶尔", "is_correct": false, "explanation": "“偶尔”表示次数少，与方向无关。"}], "correct_answer": "自下而上", "explanations": {"自下而上": "正确：“自下而上”与“自上而下”表示相反的方向，是词典列出的反义词。", "慢慢": "“慢慢”表示速度缓慢，与方向无关。", "突然": "“突然”表示发生得很快，与方向无关。", "偶尔": "“偶尔”表示次数少，与方向无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26946, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自下而上", "is_correct": true, "explanation": "正确：“自下而上”与“自上而下”表示相反的方向，是词典列出的反义词。"}, {"text": "渐渐", "is_correct": false, "explanation": "“渐渐”表示逐步变化，与方向无关。"}, {"text": "忽然", "is_correct": false, "explanation": "“忽然”表示出乎意料地发生，与方向无关。"}, {"text": "猛然", "is_correct": false, "explanation": "“猛然”表示突然而有力，与方向无关。"}], "correct_answer": "自下而上", "explanations": {"自下而上": "正确：“自下而上”与“自上而下”表示相反的方向，是词典列出的反义词。", "渐渐": "“渐渐”表示逐步变化，与方向无关。", "忽然": "“忽然”表示出乎意料地发生，与方向无关。", "猛然": "“猛然”表示突然而有力，与方向无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26946, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "从上往下。", "primary_collocate": null, "pronunciation": "zì shàng ér xià", "ipa": "tsɨ˥˩ ʂaŋ˥˩ ɚ˧˥ ɕja˥˩", "syllable_count": 4, "sentences": [{"text": "水自上而下流过石头。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你自上而下擦这面玻璃。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自上而下看了一遍这张表。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水自上而下，流进了小河。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油漆要自上而下刷，才不会滴到地上。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光自上而下照在她身上。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架要自上而下一层一层地整理。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瀑布自上而下，声音很大。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自上而下读了一遍这篇短文。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师自上而下检查每一行字。", "target_word": "自上而下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自下而上", "label": "反义"}], "register": "书面", "sense_fingerprint": "副词：动作或物体从上往下的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bc6cb3f-8b0d-40c9-96c0-695a89fc73a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自上而下", "is_correct": true, "explanation": "正确：“自上而下”作状语，说明水从上往下流，符合物理情境。"}, {"text": "呆呆地", "is_correct": false, "explanation": "语义：“呆呆地”形容人的神情或状态，不能用来描述水的流动。"}, {"text": "高兴地", "is_correct": false, "explanation": "搭配：“高兴”描述人的情绪，不能用来修饰水的流动。"}, {"text": "愤怒地", "is_correct": false, "explanation": "语义：“愤怒地”描述人的情绪反应，与水流过石头的情境不符。"}], "explanations": {"自上而下": "正确：“自上而下”作状语，说明水从上往下流，符合物理情境。", "呆呆地": "语义：“呆呆地”形容人的神情或状态，不能用来描述水的流动。", "高兴地": "搭配：“高兴”描述人的情绪，不能用来修饰水的流动。", "愤怒地": "语义：“愤怒地”描述人的情绪反应，与水流过石头的情境不符。"}, "sentence_index": 0, "correct_answer": "自上而下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蚂蚁自上而下爬上了树。", "explanation": "这里应该用〈自下而上〉。“爬上”是从下往上，而“自上而下”指从上往下，方向相反。"}, {"text": "他自上而下笑了一下。", "explanation": "这里应该用〈微微〉之类的词。这句把“自上而下”用来修饰“笑”，而“笑”没有空间位移，不存在从上往下的方向。"}, {"text": "灯自上而下放在桌上。", "explanation": "错用：“自上而下”描述的是动作从上往下移动的方式，不能用来说明“放在桌上”这种静止的摆放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自上而下", "is_correct": true, "explanation": "正确：“自上而下”作状语，修饰“整理”，表示按从上到下逐层进行。"}, {"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示一起进行，与“一层一层地”的逐层过程矛盾。"}, {"text": "胡乱地", "is_correct": false, "explanation": "语义：“胡乱地”表示没有条理，与“一层一层地”的有序整理相反。"}, {"text": "一下子", "is_correct": false, "explanation": "搭配：“一下子”表示一次完成，与“一层一层地”的逐层过程不搭配。"}], "explanations": {"自上而下": "正确：“自上而下”作状语，修饰“整理”，表示按从上到下逐层进行。", "同时": "语义：“同时”表示一起进行，与“一层一层地”的逐层过程矛盾。", "胡乱地": "语义：“胡乱地”表示没有条理，与“一层一层地”的有序整理相反。", "一下子": "搭配：“一下子”表示一次完成，与“一层一层地”的逐层过程不搭配。"}, "sentence_index": 6, "correct_answer": "自上而下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师自上而下，一下子就把每一行字都写完了。", "explanation": "这里应该用〈一行一行〉。这句把“自上而下”当成了“整体同时完成”的意思，它只表示按顺序从上往下。"}, {"text": "这把伞是自上而下撑开的。", "explanation": "错用：“自上而下”只表示从上往下的方向，不能用来描述撑伞的动作，伞是向四周撑开的。"}, {"text": "这碗汤自上而下很好喝。", "explanation": "这里应该用〈鲜美〉之类的词。这句把“自上而下”当成了评价味道的词，它只能表示方向或层级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗户要自上而下的擦干净。", "corrected_sentence": "窗户要自上而下地擦干净。", "error_description": "“自上而下”修饰动词“擦”时要用“地”，不能用“的”，应说“自上而下地擦干净”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要自上而下了清理仓库。", "corrected_sentence": "我们要自上而下地清理仓库。", "error_description": "“自上而下”修饰动词“清理”时要用“地”，不能用“了”；“了”表示完成，不能放在状语后面。正确形式是“我们要自上而下地清理仓库”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
