INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26954, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有多的，用不完。", "primary_collocate": null, "pronunciation": "fù yu", "ipa": "fu˥˩ y", "syllable_count": 2, "sentences": [{"text": "这些纸很富余，怎么用都用不完。", "target_word": "富余", "complexity_tier": "T3", "furigana": "zhè xiē zhǐ hěn fù yu, zěn me yòng dōu yòng bu wán.", "sentence_source": "generated"}, {"text": "今年的米很富余，吃不完。", "target_word": "富余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我带的水很富余，你也喝一点。", "target_word": "富余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家的房子很富余，一间空着。", "target_word": "富余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在我们的座位很富余，不用抢。", "target_word": "富余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末时间富余，我去公园跑步。", "target_word": "富余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些钱很富余，你不用再带了。", "target_word": "富余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房里的盘子富余，可以送你几个。", "target_word": "富余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路不远，时间富余，别着急。", "target_word": "富余", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她买的布很富余，做完衣服还有。", "target_word": "富余", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "东西有多的，用不完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ddeb1c-b8b8-41b2-8444-7e2ddcd9f1b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26954, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "富余", "is_correct": true, "explanation": "正确。富余：有多的，用不完。"}, {"text": "腹语", "is_correct": false, "explanation": "yǔ（第三声）与轻声 yu 声调不同，腹语指不动口而发出声音的技艺，意思不同。"}, {"text": "赋予", "is_correct": false, "explanation": "yǔ（第三声）与轻声 yu 声调不同，赋予指给予，意思不同。"}, {"text": "富于", "is_correct": false, "explanation": "yú（第二声）与轻声 yu 声调不同，富于指具有某种特点，意思不同。"}, {"text": "负于", "is_correct": false, "explanation": "yú（第二声）与轻声 yu 声调不同，负于指输给、不如，意思不同。"}], "explanations": {"富余": "正确。富余：有多的，用不完。", "腹语": "yǔ（第三声）与轻声 yu 声调不同，腹语指不动口而发出声音的技艺，意思不同。", "赋予": "yǔ（第三声）与轻声 yu 声调不同，赋予指给予，意思不同。", "富于": "yú（第二声）与轻声 yu 声调不同，富于指具有某种特点，意思不同。", "负于": "yú（第二声）与轻声 yu 声调不同，负于指输给、不如，意思不同。"}, "sentence_index": null, "correct_answer": "富余"}, "level_3": {"options": [{"text": "富余", "is_correct": true, "explanation": "正确。「这些纸很富余」说纸有多的，怎么用都用不完，符合句意。"}, {"text": "活泼", "is_correct": false, "explanation": "语义：纸不能「活泼」，这个形容词不能用来形容纸。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：「狭窄」形容空间，不用来修饰纸。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：纸不会「吵闹」，与「怎么用都用不完」的语境不合。"}], "explanations": {"富余": "正确。「这些纸很富余」说纸有多的，怎么用都用不完，符合句意。", "活泼": "语义：纸不能「活泼」，这个形容词不能用来形容纸。", "狭窄": "搭配：「狭窄」形容空间，不用来修饰纸。", "吵闹": "语义：纸不会「吵闹」，与「怎么用都用不完」的语境不合。"}, "sentence_index": 0, "correct_answer": "富余"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的经验很富余，讲起来很有道理。", "explanation": "这里应该用〈丰富〉。经验要说「丰富」，「富余」指有多的、用不完，不用于经验。"}, {"text": "他请假的理由很富余，老师都相信了。", "explanation": "这里应该用〈充足〉。理由要说「充足」，「富余」不用于理由。"}, {"text": "这位老人的心胸很富余，对谁都很和气。", "explanation": "这里应该用〈宽广〉。心胸要说「宽广」，「富余」不用来形容心胸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "富余", "is_correct": true, "explanation": "正确。「这些钱很富余」说钱有多的，你不用再带，符合句意。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：钱不能「无聊」，这个形容词不能用来形容钱。"}, {"text": "温暖", "is_correct": false, "explanation": "语义：钱不会「温暖」，与「你不用再带了」的语境不合。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：「干燥」形容空气、土地，不用来形容钱。"}], "explanations": {"富余": "正确。「这些钱很富余」说钱有多的，你不用再带，符合句意。", "无聊": "语义：钱不能「无聊」，这个形容词不能用来形容钱。", "温暖": "语义：钱不会「温暖」，与「你不用再带了」的语境不合。", "干燥": "搭配：「干燥」形容空气、土地，不用来形容钱。"}, "sentence_index": 6, "correct_answer": "富余"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的精力很富余，跑步一小时也不觉得累。", "explanation": "这里应该用〈充沛〉。精力要说「充沛」，「富余」不用于精力。"}, {"text": "这首歌的情绪很富余，听了很让人感动。", "explanation": "这里应该用〈饱满〉。情绪要说「饱满」，「富余」不用于情绪。"}, {"text": "这位老师为人很富余，对学生很耐心。", "explanation": "这里应该用〈宽厚〉。形容为人要说「宽厚」，「富余」指数量超过需要，不形容人的品性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们带的饭很富余着，大家都吃饱了。", "corrected_sentence": "我们带的饭很富余，大家都吃饱了。", "error_description": "错误：「很富余着」；正确：「很富余」。「很」修饰形容词「富余」时不能再加「着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些布很还富余，可以再送人。", "corrected_sentence": "这些布还很富余，可以再送人。", "error_description": "错误：「很还富余」；正确：「还很富余」。副词「还」要放在「很」前面，应说「还很富余」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
