INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26956, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "abstract", "definition": "一个地方直接连到另一个地方。", "primary_collocate": null, "pronunciation": "diǎn duì diǎn", "ipa": "tjɛn˨˩˦ twei˥˩ tjɛn˨˩˦", "syllable_count": 3, "sentences": [{"text": "这趟车是点对点的，中途不停。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司提供点对点的接送服务。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点对点飞行，不用在别的城市转机。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从家到学校，有一条点对点的巴士。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点对点的路线最省时间。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种快递是点对点送货，很快就到。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点对点的班车，早上八点出发。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢点对点的旅行，不想中间换车。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点对点的服务让老人出门更方便。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条地铁线是点对点的，只有两站。", "target_word": "点对点", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "點對點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "点对点：从一个地方直接到另一个地方，中间不停不转", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ddeb1c-b8b8-41b2-8444-7e2ddcd9f1b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26956, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "点对点", "is_correct": true, "explanation": "「点对点」指直达，从起点直接到终点，与「中途不停」相符。"}, {"text": "中转", "is_correct": false, "explanation": "语义：「中转」需要换车或停留，与「中途不停」相抵。"}, {"text": "慢车", "is_correct": false, "explanation": "语义：「慢车」每站都停，与「中途不停」矛盾。"}, {"text": "站站停", "is_correct": false, "explanation": "语义：「站站停」每站都停，与「中途不停」直接矛盾。"}], "explanations": {"点对点": "「点对点」指直达，从起点直接到终点，与「中途不停」相符。", "中转": "语义：「中转」需要换车或停留，与「中途不停」相抵。", "慢车": "语义：「慢车」每站都停，与「中途不停」矛盾。", "站站停": "语义：「站站停」每站都停，与「中途不停」直接矛盾。"}, "sentence_index": 0, "correct_answer": "点对点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家餐厅的菜是点对点的，每道都不一样。", "explanation": "这里应该用〈多样〉。「点对点」描述一个地方直接连到另一个地方，不能用来形容菜式的变化。"}, {"text": "他的心情点对点地好起来了。", "explanation": "这里应该用〈逐渐〉。「点对点」指地点之间的直接连通，不能形容心情转好这种变化。"}, {"text": "他们在街上点对点地遇见了老同学。", "explanation": "这里应该用〈碰见〉。「点对点」指地点间的直接连通，不能用来描述偶然相遇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点对点", "is_correct": true, "explanation": "「点对点」班车直达，中间不停，与「早上八点出发」的班车相符。"}, {"text": "午夜", "is_correct": false, "explanation": "语义：「午夜」与「早上八点出发」的时间矛盾。"}, {"text": "夜间", "is_correct": false, "explanation": "语义：「夜间」的班车与「早上八点出发」冲突。"}, {"text": "慢车", "is_correct": false, "explanation": "搭配：「慢车」多指停靠每站的列车，「慢车的班车」搭配不当。"}], "explanations": {"点对点": "「点对点」班车直达，中间不停，与「早上八点出发」的班车相符。", "午夜": "语义：「午夜」与「早上八点出发」的时间矛盾。", "夜间": "语义：「夜间」的班车与「早上八点出发」冲突。", "慢车": "搭配：「慢车」多指停靠每站的列车，「慢车的班车」搭配不当。"}, "sentence_index": 6, "correct_answer": "点对点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条地铁线是点对点的，途中要换好几次车。", "explanation": "这里应该用〈中转〉。「点对点」指中间不换车，途中要换好几次车应说〈中转〉，不能用「点对点」。"}, {"text": "这家店的点对点很好吃，我买了两份。", "explanation": "这里应该用〈点心〉。「点对点」指一个地方直接到另一个地方，不是食物，不能说「好吃」。"}, {"text": "这条地铁线是点对点的，每站都停，很慢。", "explanation": "这里应该用〈慢车〉。「点对点」指中间不停站，每站都停与词义矛盾，应说〈慢车〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一条点对点地专线。", "corrected_sentence": "这是一条点对点的专线。", "error_description": "的地误用：「点对点」作定语修饰「专线」，应用结构助词「的」，不能用「地」。应改为「点对点的专线」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这趟班车是点对点地，中途不停。", "corrected_sentence": "这趟班车是点对点的，中途不停。", "error_description": "的地误用：「是点对点的」是「是……的」结构，句末应用「的」，不能用「地」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26958, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "购买", "is_correct": true, "explanation": "反义：购买是卖的对面，指买方取得东西，与售予相对。"}, {"text": "收藏", "is_correct": false, "explanation": "收藏：指保存珍贵的东西，与售予没有对立关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：指用声音表演曲调，与售予无关。"}, {"text": "清洗", "is_correct": false, "explanation": "清洗：指把脏东西弄干净，与售予无关。"}], "correct_answer": "购买", "explanations": {"购买": "反义：购买是卖的对面，指买方取得东西，与售予相对。", "收藏": "收藏：指保存珍贵的东西，与售予没有对立关系。", "唱歌": "唱歌：指用声音表演曲调，与售予无关。", "清洗": "清洗：指把脏东西弄干净，与售予无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26958, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "购买", "is_correct": true, "explanation": "反义：购买是卖的对面，指买方取得东西，与售予相对。"}, {"text": "修理", "is_correct": false, "explanation": "修理：指把坏了的东西弄好，与售予无关。"}, {"text": "种植", "is_correct": false, "explanation": "种植：指栽培植物，与售予无关。"}, {"text": "翻译", "is_correct": false, "explanation": "翻译：指转换语言的表达，与售予无关。"}], "correct_answer": "购买", "explanations": {"购买": "反义：购买是卖的对面，指买方取得东西，与售予相对。", "修理": "修理：指把坏了的东西弄好，与售予无关。", "种植": "种植：指栽培植物，与售予无关。", "翻译": "翻译：指转换语言的表达，与售予无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26958, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西卖给另一个人。", "primary_collocate": null, "pronunciation": "shòu yǔ", "ipa": "ʂoʊ˥˩ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "他把自行车售予同学了。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家把这幅画售予一位老板。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把旧车售予你。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店不会把酒售予小孩。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把新产品售予各地商店。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把花店售予了表姐。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店只售予会员。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷把果园售予村里人。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把旧书售予图书馆。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员不能把药售予没有处方的人。", "target_word": "售予", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "售予了", "label": "体标"}, {"form": "售予过", "label": "体标"}], "register": "书面", "sense_fingerprint": "把东西卖给另一个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bc6cb3f-8b0d-40c9-96c0-695a89fc73a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26958, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "售予", "is_correct": true, "explanation": "售予：把东西卖给另一个人，正是这里的意思。"}, {"text": "手语", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，意思是手语。"}, {"text": "咒语", "is_correct": false, "explanation": "zhòu 与 shòu 声母不同（zh 与 sh），意思是咒语。"}, {"text": "术语", "is_correct": false, "explanation": "shù 与 shòu 韵母不同（shòu 多一个 o），意思是术语。"}, {"text": "熟语", "is_correct": false, "explanation": "shú（第二声）与 shòu（第四声）声调不同，韵母也不同，意思是熟语。"}], "explanations": {"售予": "售予：把东西卖给另一个人，正是这里的意思。", "手语": "shǒu（第三声）与 shòu（第四声）声调不同，意思是手语。", "咒语": "zhòu 与 shòu 声母不同（zh 与 sh），意思是咒语。", "术语": "shù 与 shòu 韵母不同（shòu 多一个 o），意思是术语。", "熟语": "shú（第二声）与 shòu（第四声）声调不同，韵母也不同，意思是熟语。"}, "sentence_index": null, "correct_answer": "售予"}, "level_3": {"options": [{"text": "售予", "is_correct": true, "explanation": "语义：“售予”正是把自行车卖给同学，与句子一致。"}, {"text": "修理", "is_correct": false, "explanation": "配价：修理的宾语是东西，不能说修理同学，“修理同学了”说不通。"}, {"text": "偷", "is_correct": false, "explanation": "语义：偷是暗中拿走，与“把自行车……同学”的交付语境不合，“偷同学了”说不通。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：骑的对象是车，“骑同学”不是正常搭配。"}], "explanations": {"售予": "语义：“售予”正是把自行车卖给同学，与句子一致。", "修理": "配价：修理的宾语是东西，不能说修理同学，“修理同学了”说不通。", "偷": "语义：偷是暗中拿走，与“把自行车……同学”的交付语境不合，“偷同学了”说不通。", "骑": "搭配：骑的对象是车，“骑同学”不是正常搭配。"}, "sentence_index": 0, "correct_answer": "售予"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从同学那里售予了那辆自行车。", "explanation": "这里应该用〈购买〉。售予是卖方把东西卖给买方，“从同学那里”表示来源，句子却说卖方从对方那里卖出，方向搞反了。"}, {"text": "我从邻居那里售予了那台旧电脑。", "explanation": "这里应该用〈买下〉。买下是买方取得东西，“从邻居那里”是来源；用售予就把买卖方向弄反了。"}, {"text": "公司从农民那里售予了那批水果。", "explanation": "这里应该用〈收购〉。收购是从别人那里买进，“从农民那里”是来源；售予的方向是卖方交给买方，二者相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26958, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "售予", "is_correct": true, "explanation": "语义：“售予”正是卖给会员，与“这家店只……会员”的经营语境一致。"}, {"text": "翻译", "is_correct": false, "explanation": "配价：翻译的对象是语言或文字，不能说翻译会员，“这家店只翻译会员”说不通。"}, {"text": "种植", "is_correct": false, "explanation": "配价：种植的对象是植物，不能说种植会员，“这家店只种植会员”说不通。"}, {"text": "熬煮", "is_correct": false, "explanation": "配价：熬煮的对象是食物，不能说熬煮会员，“这家店只熬煮会员”说不通。"}], "explanations": {"售予": "语义：“售予”正是卖给会员，与“这家店只……会员”的经营语境一致。", "翻译": "配价：翻译的对象是语言或文字，不能说翻译会员，“这家店只翻译会员”说不通。", "种植": "配价：种植的对象是植物，不能说种植会员，“这家店只种植会员”说不通。", "熬煮": "配价：熬煮的对象是食物，不能说熬煮会员，“这家店只熬煮会员”说不通。"}, "sentence_index": 6, "correct_answer": "售予"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市政府向农民售予了一笔补助金。", "explanation": "这里应该用〈发放〉。售予是把东西卖给买方；补助金是政府发给农民的款项，不是买卖的商品，应说发放。"}, {"text": "房东把这间店面售予了商户，每月收取租金。", "explanation": "这里应该用〈出租〉。售予是一次性卖断，后面“每月收取租金”说明是按月收钱的租赁，应说出租。"}, {"text": "奶奶把老照片无偿售予了侄子。", "explanation": "这里应该用〈赠送〉。售予是有偿卖给买方，“无偿”说明没有买卖，应说赠送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把旧车售予给一个朋友。", "corrected_sentence": "我把旧车售予一个朋友。", "error_description": "错误形式：“售予给”。正确形式：“售予”。“予”已含“给”的意思，后面不能再加“给”，应说“售予一个朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店主把旧货售予着一位顾客。", "corrected_sentence": "店主把旧货售予了一位顾客。", "error_description": "错误形式：“售予着”。正确形式：“售予了”。“售予”是一次性完成的交付，不能用“着”表示持续状态，应说“售予了一位顾客”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
