INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26960, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "使用电脑、手机等的人。", "primary_collocate": null, "pronunciation": "yòng hù", "ipa": "jʊŋ˥˩ xu˥˩", "syllable_count": 2, "sentences": [{"text": "这个软件有一亿多用户。", "target_word": "用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司很重视用户的意见。", "target_word": "用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新用户可以免费试用一个月。", "target_word": "用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用户要先注册才能进入网站。", "target_word": "用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款手机的用户越来越多。", "target_word": "用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用户输入自己的名字和密码。", "target_word": "用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老用户用这个应用买东西可以便宜一点。", "target_word": "用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用户觉得这个应用太难用了。", "target_word": "用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的电脑是给普通用户用的。", "target_word": "用户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家软件公司为用户提供免费的技术帮助。", "target_word": "用户", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "新用户", "label": "复合词"}, {"form": "用户名", "label": "复合词"}], "register": "中性", "sense_fingerprint": "使用电脑、手机等产品或软件的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af672a29-e1eb-4780-8f57-35ac2a0384e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26960, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用户", "is_correct": true, "explanation": "正确：“用户”指使用软件的人，“一亿多用户”语境相符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”指乘坐交通工具的人，不能用来指软件的使用者。"}, {"text": "游客", "is_correct": false, "explanation": "语义：“游客”指旅游的人，与使用软件无关。"}, {"text": "作者", "is_correct": false, "explanation": "搭配：“作者”指写作的人，不与“软件”搭配来计数使用者。"}], "explanations": {"用户": "正确：“用户”指使用软件的人，“一亿多用户”语境相符。", "乘客": "语义：“乘客”指乘坐交通工具的人，不能用来指软件的使用者。", "游客": "语义：“游客”指旅游的人，与使用软件无关。", "作者": "搭配：“作者”指写作的人，不与“软件”搭配来计数使用者。"}, "sentence_index": 0, "correct_answer": "用户"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店每天都有很多用户。", "explanation": "这里应该用〈客人〉。“用户”指使用产品或服务的人，到饭店吃饭的人叫“客人”。"}, {"text": "公园里的用户正在看花。", "explanation": "这里应该用〈游客〉。在公园游玩的人叫“游客”，“用户”指使用电脑、手机等产品的人。"}, {"text": "这家饭店有很多用户在洗碗。", "explanation": "这里应该用〈员工〉。在饭店洗碗的人是“员工”，“用户”指使用电脑、手机等的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用户", "is_correct": true, "explanation": "正确：“老用户”指长期使用的人，买东西可以便宜一点，语境相符。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：“老虎”是动物，不能买东西。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：“老鼠”是动物，与购物无关。"}, {"text": "老牛", "is_correct": false, "explanation": "配价：“买东西”要求人作主语，“老牛”不能满足这一要求。"}], "explanations": {"用户": "正确：“老用户”指长期使用的人，买东西可以便宜一点，语境相符。", "老虎": "语义：“老虎”是动物，不能买东西。", "老鼠": "语义：“老鼠”是动物，与购物无关。", "老牛": "配价：“买东西”要求人作主语，“老牛”不能满足这一要求。"}, "sentence_index": 6, "correct_answer": "用户"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医院里有很多用户。", "explanation": "这里应该用〈病人〉。医院里的人是“病人”，“用户”指使用产品或服务的人。"}, {"text": "学校里的用户都很努力学习。", "explanation": "这里应该用〈学生〉。在学校学习的人叫“学生”，“用户”不能指他们。"}, {"text": "这本书的用户是李明。", "explanation": "这里应该用〈作者〉。写书的人是“作者”，“用户”指使用产品或服务的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款软件有一条新用户。", "corrected_sentence": "这款软件有一位新用户。", "error_description": "「一条新用户」错误。“条”用于细长的东西，指人应用“位”或“个”，正确为「一位新用户」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个用户们在网上留言，说这个功能很好用。", "corrected_sentence": "一个用户在网上留言，说这个功能很好用。", "error_description": "「一个用户们」错误。“们”表示复数，不能与数量词“一个”同用，正确为「一个用户」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
