INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26962, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26962, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "两个人互相给东西，比如我用钱换你的玩具。", "primary_collocate": null, "pronunciation": "jiāo yì", "ipa": "tɕjɑʊ˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "我和哥哥做了一次交易。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个交易很公平：我给你糖，你给我书。", "target_word": "交易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你同意这个交易吗？", "target_word": "交易", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是我们两个人的小交易。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的交易是：你的笔换我的橡皮。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔交易我不亏。", "target_word": "交易", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟觉得这次交易很划算。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，交易要公平，不能骗人。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课间，我和同桌又做了一笔交易。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的交易成功了，我拿到了新玩具。", "target_word": "交易", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "交易所", "label": "复合"}, {"form": "交易员", "label": "复合"}], "register": "中性", "sense_fingerprint": "交易：两个人互相给对方东西，彼此交换", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ddeb1c-b8b8-41b2-8444-7e2ddcd9f1b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26962, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交易", "is_correct": true, "explanation": "正确。「做了一次交易」指两人之间的一次互换，符合句意。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然现象，不是人能「做」的行为。"}, {"text": "雷雨", "is_correct": false, "explanation": "搭配：「做」不搭配「雷雨」，雷雨多说「下」。"}, {"text": "大雪", "is_correct": false, "explanation": "语义：大雪是天气现象，不能说「做了一次大雪」。"}], "explanations": {"交易": "正确。「做了一次交易」指两人之间的一次互换，符合句意。", "地震": "语义：地震是自然现象，不是人能「做」的行为。", "雷雨": "搭配：「做」不搭配「雷雨」，雷雨多说「下」。", "大雪": "语义：大雪是天气现象，不能说「做了一次大雪」。"}, "sentence_index": 0, "correct_answer": "交易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和弟弟交易了一个微笑。", "explanation": "这里应该用〈交换〉。「交换微笑」是互相回应，不是买卖，「交易」只指以货币或实物交换商品。"}, {"text": "老师交易了我一个问题。", "explanation": "这里应该用〈回答〉。老师对学生是回答问题，不是互相给东西；「交易」不能用于问题。"}, {"text": "我向他交易了一句对不起。", "explanation": "这里应该用〈道歉〉。说「对不起」是表达歉意，不是互相给东西，「交易」不能用于言语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交易", "is_correct": true, "explanation": "正确。「这次交易很划算」说的是这次互换的结果，符合句意。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：「感冒」是疾病，不能用「划算」来评价。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测验，不能说「这次考试很划算」。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「划算」用于价钱和买卖，不用来形容天气。"}], "explanations": {"交易": "正确。「这次交易很划算」说的是这次互换的结果，符合句意。", "感冒": "语义：「感冒」是疾病，不能用「划算」来评价。", "考试": "语义：考试是测验，不能说「这次考试很划算」。", "天气": "搭配：「划算」用于价钱和买卖，不用来形容天气。"}, "sentence_index": 6, "correct_answer": "交易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和同桌交易了一次想法。", "explanation": "这里应该用〈交流〉。交流想法是互相讨论，「交易」指买卖或以实物交换，想法不能交易。"}, {"text": "他向我交易了一声问好。", "explanation": "这里应该用〈问候〉。向人问好是表达善意，「交易」指买卖或互换实物，不能用于问候。"}, {"text": "我用交易打开了家门。", "explanation": "这里应该用〈钥匙〉。「交易」指两个人互相给东西，不是能开门的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和弟弟做了一本交易。", "corrected_sentence": "我和弟弟做了一笔交易。", "error_description": "量词错误：「一本交易」；正确：「一笔交易」。“交易”用“笔”计量，“本”用于书册，不能修饰“交易”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这本交易做完了。", "corrected_sentence": "我把这笔交易做完了。", "error_description": "量词错误：「这本交易」；正确：「这笔交易」。“交易”用“笔”计量，“本”用于书册，不能修饰“交易”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
