INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26966, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "猜一猜以后会发生什么事。", "primary_collocate": null, "pronunciation": "yù cè", "ipa": "y˥˩ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "你能预测明天会发生什么吗？", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他预测今晚会下雪。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生预测病人很快会好起来。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我预测我们队会赢。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济学家预测了明年的增长。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件能预测天气。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她预测过这次比赛的结果。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很难预测孩子以后想做什么。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民看着云预测明天的天气。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都预测他会成功。", "target_word": "预测", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预测了", "label": "体标"}, {"form": "预测过", "label": "体标"}], "register": "中性", "sense_fingerprint": "猜测以后会发生什么事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bc6cb3f-8b0d-40c9-96c0-695a89fc73a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26966, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "预测", "is_correct": true, "explanation": "语义：预测是猜测以后会发生的事，与“明天会发生什么”吻合。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：回忆的是已经发生的事，明天的事还没发生，不能回忆。"}, {"text": "经历", "is_correct": false, "explanation": "语义：经历的是已经发生或正在经过的事，明天的事还没有发生，无法经历。"}, {"text": "记住", "is_correct": false, "explanation": "语义：记住的是已经知道或发生的事，明天的事无法记住。"}], "explanations": {"预测": "语义：预测是猜测以后会发生的事，与“明天会发生什么”吻合。", "回忆": "语义：回忆的是已经发生的事，明天的事还没发生，不能回忆。", "经历": "语义：经历的是已经发生或正在经过的事，明天的事还没有发生，无法经历。", "记住": "语义：记住的是已经知道或发生的事，明天的事无法记住。"}, "sentence_index": 0, "correct_answer": "预测"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老人预测了年轻时的那段经历。", "explanation": "这里应该用〈回忆〉。年轻时的经历已经发生，预测只能用于以后会发生的事。"}, {"text": "消防员预测了火灾的起因。", "explanation": "这里应该用〈查明〉。火灾已经发生，起因要查明，不能预测。"}, {"text": "侦探预测凶手昨晚来过这里。", "explanation": "这里应该用〈推断〉。昨晚已经发生的事只能推断，预测只用于以后会发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预测", "is_correct": true, "explanation": "语义：预测是事先猜测结果，与“比赛的结果”相合。"}, {"text": "举办", "is_correct": false, "explanation": "搭配：举办的对象是活动，不能说举办比赛的结果。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是演唱歌曲，比赛的结果不能用来演唱。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫针对地面、房间等，比赛的结果无法打扫。"}], "explanations": {"预测": "语义：预测是事先猜测结果，与“比赛的结果”相合。", "举办": "搭配：举办的对象是活动，不能说举办比赛的结果。", "唱": "语义：唱是演唱歌曲，比赛的结果不能用来演唱。", "打扫": "语义：打扫针对地面、房间等，比赛的结果无法打扫。"}, "sentence_index": 6, "correct_answer": "预测"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人预测了这台机器此刻的温度。", "explanation": "这里应该用〈测量〉。预测是推断将来的情况，此刻的温度已经可以测出，应该用测量。"}, {"text": "老师预测了班上此刻的人数。", "explanation": "这里应该用〈统计〉。此刻班上的人数是已知的事实，要用统计，预测只用于将来的情况。"}, {"text": "医生预测了病人的牙齿。", "explanation": "这里应该用〈检查〉。病人的牙齿就在眼前，应该检查，不能用预测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这次预测地很准。", "corrected_sentence": "他这次预测得很准。", "error_description": "错误形式：“地”。正确形式：“得”。“地”用在动词前作状语，动词后引出补语要用“得”，所以应说“预测得很准”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她预测着明天会下雨。", "corrected_sentence": "她预测明天会下雨。", "error_description": "错误形式：“预测着”。正确形式：“预测”。“预测”后面直接带要猜测的内容，不能加“着”表示持续，应说“她预测明天会下雨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1cfefa4b-113e-42b5-a138-9b8d03182658') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
