INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26968, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "用电就是用电器工作。", "primary_collocate": null, "pronunciation": "yòng diàn", "ipa": "jʊŋ˥˩ tjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "手机充电也是用电。", "target_word": "用电", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "开灯、开电视都要用电。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱一直在工作，所以要用电。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电风扇一转，就在用电。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗衣机洗衣服时也用电。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电器工作，就是在用电。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不在家，但冰箱还在用电。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑开着，就一直在用电。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用电的东西不要放在水边。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了省钱，白天我们少用电。", "target_word": "用电", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "用电量", "label": "复合"}], "register": "中性", "sense_fingerprint": "电器工作时消耗电，就是用电", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7ddeb1c-b8b8-41b2-8444-7e2ddcd9f1b8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26968, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用电", "is_correct": true, "explanation": "正确。手机充电也是消耗电能的用电行为。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是行为，不能说“充电也是冰箱”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指身体的重量，和充电没有关系。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌是文学作品，与充电不属于同类。"}], "explanations": {"用电": "正确。手机充电也是消耗电能的用电行为。", "冰箱": "语义：冰箱是家电，不是行为，不能说“充电也是冰箱”。", "体重": "语义：体重指身体的重量，和充电没有关系。", "诗歌": "语义：诗歌是文学作品，与充电不属于同类。"}, "sentence_index": 0, "correct_answer": "用电"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电风扇是一种用电。", "explanation": "这里应该用〈用电器〉。电风扇是用电工作的器具；“用电”指消耗电能的行为，不能指物品。"}, {"text": "前天突然用电了，全楼的人都很着急。", "explanation": "这里应该用〈停电〉。停电指供电中断，全楼的人着急是因为没有电；“用电”是使用电能的行为，不能表示电被切断。"}, {"text": "用电是一种能量。", "explanation": "这里应该用〈电能〉。电能是一种能量；“用电”是消耗电能的行为，不能说“是一种能量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用电", "is_correct": true, "explanation": "正确。“还在用电”指冰箱仍在消耗电能。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：冰箱不会睡觉，“还在睡觉”不符合常理。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”的主语通常是人，冰箱不能唱歌。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞是人的动作，冰箱不会跳舞。"}], "explanations": {"用电": "正确。“还在用电”指冰箱仍在消耗电能。", "睡觉": "语义：冰箱不会睡觉，“还在睡觉”不符合常理。", "唱歌": "搭配：“唱歌”的主语通常是人，冰箱不能唱歌。", "跳舞": "语义：跳舞是人的动作，冰箱不会跳舞。"}, "sentence_index": 6, "correct_answer": "用电"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台冰箱昨晚用电了，食物都坏了。", "explanation": "这里应该用〈断电〉。断电指供电中断，冰箱停止制冷，食物才会坏；“用电”是使用电能的行为，不能表示供电被切断。"}, {"text": "这根用电很粗。", "explanation": "这里应该用〈电线〉。电线是可以粗细的物体；“用电”是行为，不能用来形容粗细。"}, {"text": "这盏用电很亮。", "explanation": "这里应该用〈电灯〉。电灯是可以发光的物体；“用电”是行为，不能用来形容明亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冰箱一直用电着。", "corrected_sentence": "冰箱一直用着电。", "error_description": "离合词错误：“着”应放在“用”之后，说“用着电”，不能放在“电”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台空调昨天用着很多电。", "corrected_sentence": "这台空调昨天用了很多电。", "error_description": "体标误用：「昨天」已经完成，又有数量「很多」，应说「用了很多电」，不能用表示持续的「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e958589-186c-4546-ac0b-bcb764b933c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
