INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26974, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "不是，表示否定。", "primary_collocate": null, "pronunciation": "fēi", "ipa": "fei˥", "syllable_count": 1, "sentences": [{"text": "这本书非我所有。", "target_word": "非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他非中国人，是日本人。", "target_word": "非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这非小事，我们要认真对待。", "target_word": "非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天非休息日，我要去上班。", "target_word": "非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那非我的错，是别人弄坏的。", "target_word": "非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里非停车的地方，请把车开走。", "target_word": "非", "complexity_tier": "T3", "furigana": "zhè lǐ fēi tíng chē de dì fang, qǐng bǎ chē kāi zǒu.", "sentence_source": "generated"}, {"text": "他说的非真话，你别信。", "target_word": "非", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你看到的非全部，还有很多事你不知道。", "target_word": "非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学外语非难事，只要每天练习。", "target_word": "非", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路非大路，车不多。", "target_word": "非", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "表示“不是”的否定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65bf7ffb-9382-49a3-a249-55e085870a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26974, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "非", "is_correct": true, "explanation": "正确答案：非，fēi（第一声），动词，表示“不是”。"}, {"text": "肥", "is_correct": false, "explanation": "肥 féi（第二声）与 fēi（第一声）声调不同，意思是胖。"}, {"text": "分", "is_correct": false, "explanation": "分 fēn 韵母不同（en 与 ei），意思是分开、分数。"}, {"text": "风", "is_correct": false, "explanation": "风 fēng 韵母不同（eng 与 ei），意思是风。"}, {"text": "肺", "is_correct": false, "explanation": "肺 fèi（第四声）与 fēi（第一声）声调不同，意思是肺脏。"}], "explanations": {"非": "正确答案：非，fēi（第一声），动词，表示“不是”。", "肥": "肥 féi（第二声）与 fēi（第一声）声调不同，意思是胖。", "分": "分 fēn 韵母不同（en 与 ei），意思是分开、分数。", "风": "风 fēng 韵母不同（eng 与 ei），意思是风。", "肺": "肺 fèi（第四声）与 fēi（第一声）声调不同，意思是肺脏。"}, "sentence_index": null, "correct_answer": "非"}, "level_3": {"options": [{"text": "非", "is_correct": true, "explanation": "正确：“非”表示“不是”，“非我所有”即“不是我的”。"}, {"text": "都", "is_correct": false, "explanation": "搭配：“都”要与复数对象和“是”连用，“这本书都我所有”不成立。"}, {"text": "正", "is_correct": false, "explanation": "体貌：“正”表示动作正在进行，而“所有”表示稳定的归属状态，两者不能搭配。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词，不能放在“我所有”这样的结构前。"}], "explanations": {"非": "正确：“非”表示“不是”，“非我所有”即“不是我的”。", "都": "搭配：“都”要与复数对象和“是”连用，“这本书都我所有”不成立。", "正": "体貌：“正”表示动作正在进行，而“所有”表示稳定的归属状态，两者不能搭配。", "很": "搭配：“很”修饰形容词，不能放在“我所有”这样的结构前。"}, "sentence_index": 0, "correct_answer": "非"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书非我所有，那是我今天早上刚买的。", "explanation": "这里应该用〈是〉。非表示否定，说“这本书不是我的”，与“我今天早上刚买的”矛盾；肯定判断要用“是”。"}, {"text": "这件礼物非我送的，是我亲手送给你的。", "explanation": "这里应该用〈是〉。非表示否定，说“这件礼物不是我送的”，与“是我亲手送给你的”矛盾；肯定判断要用“是”。"}, {"text": "这把钥匙非我的，它一直挂在我的脖子上。", "explanation": "这里应该用〈是〉。非表示否定，说“这把钥匙不是我的”，与“一直挂在我的脖子上”矛盾；肯定判断要用“是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26974, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "非", "is_correct": true, "explanation": "正确答案：非，fēi（第一声），动词，表示“不是”。"}, {"text": "废", "is_correct": false, "explanation": "废 fèi（第四声）与 fēi（第一声）声调不同，意思是废弃。"}, {"text": "肥", "is_correct": false, "explanation": "肥 féi（第二声）与 fēi（第一声）声调不同，意思是胖。"}, {"text": "悲", "is_correct": false, "explanation": "悲 bēi 声母不同（b 与 f），意思是悲伤。"}, {"text": "黑", "is_correct": false, "explanation": "黑 hēi 声母不同（h 与 f），意思是黑色。"}], "explanations": {"非": "正确答案：非，fēi（第一声），动词，表示“不是”。", "废": "废 fèi（第四声）与 fēi（第一声）声调不同，意思是废弃。", "肥": "肥 féi（第二声）与 fēi（第一声）声调不同，意思是胖。", "悲": "悲 bēi 声母不同（b 与 f），意思是悲伤。", "黑": "黑 hēi 声母不同（h 与 f），意思是黑色。"}, "sentence_index": null, "correct_answer": "非"}, "level_3": {"options": [{"text": "非", "is_correct": true, "explanation": "正确：“非真话”即“不是真话”，与后句“你别信”的劝告相合。"}, {"text": "都", "is_correct": false, "explanation": "搭配：“都”要与“是”或谓语连用，“他说的都真话”不成立。"}, {"text": "确", "is_correct": false, "explanation": "语义：“确”表示确实，“确真话”与后句“你别信”的劝告矛盾。"}, {"text": "竟", "is_correct": false, "explanation": "语义：“竟”表示出乎意料，与后句“你别信”的判断不协调，且“竟真话”不成立。"}], "explanations": {"非": "正确：“非真话”即“不是真话”，与后句“你别信”的劝告相合。", "都": "搭配：“都”要与“是”或谓语连用，“他说的都真话”不成立。", "确": "语义：“确”表示确实，“确真话”与后句“你别信”的劝告矛盾。", "竟": "语义：“竟”表示出乎意料，与后句“你别信”的判断不协调，且“竟真话”不成立。"}, "sentence_index": 6, "correct_answer": "非"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他非我的亲弟弟，我们俩从小就是同一个妈妈生的。", "explanation": "这里应该用〈是〉。非表示否定，说“他不是我的亲弟弟”，与“同一个妈妈生的”矛盾；肯定判断要用“是”。"}, {"text": "这顿饭非我做的，全是我一个人亲手做的。", "explanation": "这里应该用〈是〉。非表示否定，说“这顿饭不是我做的”，与“全是我一个人亲手做的”矛盾；肯定判断要用“是”。"}, {"text": "这台电脑非我的，它一直是我每天在用的那台。", "explanation": "这里应该用〈是〉。非表示否定，说“这台电脑不是我的”，与“一直是我每天在用的那台”矛盾；肯定判断要用“是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不非我们班的人，是隔壁班的。", "corrected_sentence": "他非我们班的人，是隔壁班的。", "error_description": "否定词误用：“非”本身已表示“不是”，其前不能再加“不”；应说“他非我们班的人”，不说“他不非我们班的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件衣服不非我的。", "corrected_sentence": "这件衣服非我的。", "error_description": "否定词误用：“非”本身已表示“不是”，其前不能再加“不”；应说“这件衣服非我的”，不说“这件衣服不非我的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
