INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26976, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "非常非常小的，小到看不见。", "primary_collocate": null, "pronunciation": "nà mǐ jí", "ipa": "na˥˩ mi˨˩˦ tɕi˧˥", "syllable_count": 3, "sentences": [{"text": "空气里有很多纳米级的小颗粒。", "target_word": "纳米级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "纳米级的机器人比细菌还小。", "target_word": "纳米级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这层膜的孔是纳米级的，只有水能通过。", "target_word": "纳米级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种纳米级的线比头发细得多。", "target_word": "纳米级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些纳米级的东西，眼睛根本看不见。", "target_word": "纳米级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，纳米级的东西要用电子显微镜才能看见。", "target_word": "纳米级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种纳米级粉末摸起来很细，像面粉一样。", "target_word": "纳米级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种纳米级颗粒连放大镜都看不见。", "target_word": "纳米级", "complexity_tier": "T3", "furigana": "zhè zhǒng nà mǐ jí kē lì lián fàng dà jìng dōu kàn bú jiàn", "sentence_source": "generated"}, {"text": "妈妈买的面膜里有纳米级的成分。", "target_word": "纳米级", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验用的纳米级粒子，一滴水里就有很多。", "target_word": "纳米级", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "納米級", "label": "繁体"}], "register": "书面", "sense_fingerprint": "纳米级：小到肉眼看不见的极微小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65bf7ffb-9382-49a3-a249-55e085870a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纳米级", "is_correct": true, "explanation": "正确。“纳米级”修饰“小颗粒”，指小到肉眼看不见的尺度，与句意相合。"}, {"text": "巨大", "is_correct": false, "explanation": "语义：“巨大”指体积大，与“小颗粒”自相矛盾。"}, {"text": "千米级", "is_correct": false, "explanation": "语义：“千米级”指公里量级的大尺度，与“小颗粒”正好相反。"}, {"text": "厚实", "is_correct": false, "explanation": "搭配：“厚实”多形容墙、被子这类有厚度的物体，不用来形容空气中的小颗粒。"}], "explanations": {"纳米级": "正确。“纳米级”修饰“小颗粒”，指小到肉眼看不见的尺度，与句意相合。", "巨大": "语义：“巨大”指体积大，与“小颗粒”自相矛盾。", "千米级": "语义：“千米级”指公里量级的大尺度，与“小颗粒”正好相反。", "厚实": "搭配：“厚实”多形容墙、被子这类有厚度的物体，不用来形容空气中的小颗粒。"}, "sentence_index": 0, "correct_answer": "纳米级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事对大局的影响是纳米级的。", "explanation": "这里应该用〈微小〉。纳米级只形容物体的尺寸，影响的大小不能用它来说明，应说“影响很微小”。"}, {"text": "这件衣服的价格是纳米级的，很便宜。", "explanation": "这里应该用〈低廉〉。纳米级只形容物体的尺寸，价格高低不能用它说明，应说“价格低廉”。"}, {"text": "他的脾气是纳米级的，一生气就大吼大叫。", "explanation": "这里应该用〈暴躁〉。纳米级只形容尺寸，性情不能用它来描述，应说“脾气很暴躁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纳米级", "is_correct": true, "explanation": "正确。“纳米级”修饰“粉末”，指极细的粒子，与摸起来细腻的描述相合。"}, {"text": "液态", "is_correct": false, "explanation": "语义：“液态”指液体状，与“粉末”这种固体形态矛盾。"}, {"text": "块状", "is_correct": false, "explanation": "语义：“块状”描述外形成块，与摸起来很细的粉末不符。"}, {"text": "宇宙级", "is_correct": false, "explanation": "语义：“宇宙级”夸张地表示极大，与极细的粉末正好相反。"}], "explanations": {"纳米级": "正确。“纳米级”修饰“粉末”，指极细的粒子，与摸起来细腻的描述相合。", "液态": "语义：“液态”指液体状，与“粉末”这种固体形态矛盾。", "块状": "语义：“块状”描述外形成块，与摸起来很细的粉末不符。", "宇宙级": "语义：“宇宙级”夸张地表示极大，与极细的粉末正好相反。"}, "sentence_index": 6, "correct_answer": "纳米级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说话的速度是纳米级的，大家都听懂了。", "explanation": "这里应该用〈缓慢〉。纳米级只说明物体尺寸，说话的快慢不能用它形容，应说“说话速度很缓慢”。"}, {"text": "他的力气是纳米级的，一下子就举起了箱子。", "explanation": "这里应该用〈强壮〉。纳米级只形容尺寸，力量的大小不能用它形容，应说“他很强壮”。"}, {"text": "他的年纪是纳米级的，还不会走路。", "explanation": "这里应该用〈年幼〉。纳米级只形容物体的尺寸，年龄不能用它说明，应说“他年幼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种过滤器的孔径是很纳米级的。", "corrected_sentence": "这种过滤器的孔径是纳米级的。", "error_description": "程度副词误用：“纳米级”表示尺寸所属的量级，属于分类性词语，不能受“很”修饰；正确说法是“是纳米级的”，不说“是很纳米级的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些粉末的粒径是纳米级地。", "corrected_sentence": "这些粉末的粒径是纳米级的。", "error_description": "助词误用：“纳米级”作谓语时接“的”，不接“地”（“地”用于修饰动词）；应说“是纳米级的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
