INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26980, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自然规律是太阳每天升起、树叶秋天落下这样不会改变的事情。", "primary_collocate": null, "pronunciation": "zì rán guī lǜ", "ipa": "tsɻ̩˥˩ ʐan˧˥ kweɪ˥ ly˥˩", "syllable_count": 4, "sentences": [{"text": "太阳每天升起来，这是自然规律。", "target_word": "自然规律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树叶秋天落下，是一种自然规律。", "target_word": "自然规律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人老了会生病，这也是自然规律。", "target_word": "自然规律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我告诉孩子，四季变化是自然规律。", "target_word": "自然规律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花开了又谢，这是自然规律，别难过。", "target_word": "自然规律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水总是往低处流，这是自然规律。", "target_word": "自然规律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白天过去就是黑夜，这是自然规律。", "target_word": "自然规律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷说，人有生老病死，也是自然规律。", "target_word": "自然规律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟儿到了冬天飞去南方，是自然规律。", "target_word": "自然规律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮有圆有缺，这是自然规律。", "target_word": "自然规律", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "日升叶落等日常里一直不变的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbdf5e2f-210f-4716-b9b6-47323c31ed04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26980, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "电影", "is_correct": false, "explanation": "语义：句中说的是太阳每天升起，电影与之无关，“这是电影”说不通。"}, {"text": "自然规律", "is_correct": true, "explanation": "正确：太阳每天升起是不会改变的自然法则，与句意吻合。"}, {"text": "作业", "is_correct": false, "explanation": "语义：太阳每天升起不是作业，“这是作业”与句意不符。"}, {"text": "饭碗", "is_correct": false, "explanation": "语域：“饭碗”是口语词，与这句说明性的语体不协调，且意思不符。"}], "explanations": {"电影": "语义：句中说的是太阳每天升起，电影与之无关，“这是电影”说不通。", "自然规律": "正确：太阳每天升起是不会改变的自然法则，与句意吻合。", "作业": "语义：太阳每天升起不是作业，“这是作业”与句意不符。", "饭碗": "语域：“饭碗”是口语词，与这句说明性的语体不协调，且意思不符。"}, "sentence_index": 0, "correct_answer": "自然规律"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我告诉孩子，做人要诚实，这是自然规律。", "explanation": "这里应该用〈道理〉。自然规律指自然界不变的法则，不能用来说人为的道理。"}, {"text": "他每天早上跑步，已经成了自然规律。", "explanation": "这里应该用〈习惯〉。自然规律不指个人的习惯，习惯是人养成的。"}, {"text": "这个国家的自然规律很丰富，有很多名山大川。", "explanation": "这里应该用〈自然资源〉。自然规律是客观法则，不是矿产、水源这类资源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26980, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "礼物", "is_correct": false, "explanation": "语义：白天过去就是黑夜是自然现象，“这是礼物”说不通。"}, {"text": "自然规律", "is_correct": true, "explanation": "正确：白天过去就是黑夜是不会改变的自然法则，与句意吻合。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语词，与这句说明性的语体不协调。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：白天变黑夜不是玩具，“这是玩具”与句意不符。"}], "explanations": {"礼物": "语义：白天过去就是黑夜是自然现象，“这是礼物”说不通。", "自然规律": "正确：白天过去就是黑夜是不会改变的自然法则，与句意吻合。", "八卦": "语域：“八卦”是口语词，与这句说明性的语体不协调。", "玩具": "语义：白天变黑夜不是玩具，“这是玩具”与句意不符。"}, "sentence_index": 6, "correct_answer": "自然规律"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他总是迟到，这是他的自然规律。", "explanation": "这里应该用〈缺点〉。自然规律指自然界的法则，不能用来指一个人的缺点。"}, {"text": "她唱歌很好听，这是她的自然规律。", "explanation": "这里应该用〈天赋〉。自然规律指自然界的法则，不能用来指人的天赋。"}, {"text": "这学期班里的自然规律是每周五大扫除。", "explanation": "这里应该用〈班规〉。自然规律指自然界不变的法则，不能指班里的规定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只自然规律，大家都要遵守。", "corrected_sentence": "这是一条自然规律，大家都要遵守。", "error_description": "量词错误：“自然规律”常用量词“条”（或“个”）计量，“只”多用于动物或单件器物，不用于此类抽象事物。应说“一条自然规律”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该遵守把自然规律。", "corrected_sentence": "我们应该遵守自然规律。", "error_description": "把字句误用：“遵守”后直接接宾语，前面不能加“把”，应说“遵守自然规律”，不说“遵守把自然规律”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
