INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26982, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能源技术是让电、光、热等力量能被我们使用的方法。", "primary_collocate": null, "pronunciation": "néng yuán jì shù", "ipa": "nɤŋ˧˥ ɥɛn˧˥ tɕi˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "能源技术能把阳光变成电。", "target_word": "能源技术", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学好能源技术，就能让家里更省电。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，能源技术可以让风变成电。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们用新的能源技术给村子供热。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项能源技术让路灯晚上也能亮。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸在工厂工作，他懂能源技术。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的能源技术能把热量存起来。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校开了一门能源技术课。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了能源技术，山里的人也用上了电。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种能源技术很安全，也不太贵。", "target_word": "能源技术", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "新能源技术", "label": "复合"}, {"form": "能源技術", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让电、光、热等力量能被使用的方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65bf7ffb-9382-49a3-a249-55e085870a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "能源技术", "is_correct": true, "explanation": "正确。“能源技术”作主语，指把阳光等能量转化为电的方法，与句意相合。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：“眼睛”不能把阳光转化为电，与句意冲突。"}, {"text": "面包", "is_correct": false, "explanation": "语义：“面包”是食物，与阳光变成电毫无关系。"}, {"text": "阁下", "is_correct": false, "explanation": "语域：“阁下”是敬称、书面或古语用法，与这句科普说明的语域不合。"}], "explanations": {"能源技术": "正确。“能源技术”作主语，指把阳光等能量转化为电的方法，与句意相合。", "眼睛": "语义：“眼睛”不能把阳光转化为电，与句意冲突。", "面包": "语义：“面包”是食物，与阳光变成电毫无关系。", "阁下": "语域：“阁下”是敬称、书面或古语用法，与这句科普说明的语域不合。"}, "sentence_index": 0, "correct_answer": "能源技术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们每天烧很多能源技术。", "explanation": "这里应该用〈燃料〉。能源技术是开发利用能源的方法，不是可以烧的东西，应说“烧很多燃料”。"}, {"text": "他的职业是能源技术。", "explanation": "这里应该用〈工程师〉。能源技术是方法，不能指人的职业，应说“他的职业是工程师”。"}, {"text": "能源技术很烫，别碰。", "explanation": "这里应该用〈暖气片〉。能源技术是方法，没有温度，不能说“很烫”，应说“暖气片很烫，别碰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "能源技术", "is_correct": true, "explanation": "正确。“能源技术”作主语，指能储存热量的方法，与句意相合。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：“闹钟”用于定时响铃，与储存热量无关。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”是艺术作品，不能把热量存起来。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：“墨水”用于书写，不能把热量存起来，与句意冲突。"}], "explanations": {"能源技术": "正确。“能源技术”作主语，指能储存热量的方法，与句意相合。", "闹钟": "语义：“闹钟”用于定时响铃，与储存热量无关。", "歌曲": "语义：“歌曲”是艺术作品，不能把热量存起来。", "墨水": "语义：“墨水”用于书写，不能把热量存起来，与句意冲突。"}, "sentence_index": 6, "correct_answer": "能源技术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "能源技术很刺耳，吵得我头疼。", "explanation": "这里应该用〈声音〉。能源技术是方法，不是声音，不能用“刺耳”形容，应说“声音很刺耳”。"}, {"text": "能源技术很认真，每天都按时上课。", "explanation": "这里应该用〈老师〉。能源技术是方法，不能指人，也不能说“认真”，应说“老师很认真”。"}, {"text": "这种能源技术很香。", "explanation": "这里应该用〈花〉。能源技术没有气味，不能说“很香”，应说“这种花很香”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把能源技术很省钱。", "corrected_sentence": "这项能源技术很省钱。", "error_description": "量词误用：“能源技术”应搭配量词“项”或“种”；“把”用于有柄的器具，不能用于技术，应说“这项能源技术”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条能源技术很省电，也很干净。", "corrected_sentence": "这种能源技术很省电，也很干净。", "error_description": "量词误用：“条”用于细长的东西或新闻、建议等，“能源技术”应搭配“种”或“项”，应说“这种能源技术”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26984, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26984, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26984, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一个人在集体里没有人接近、得不到别人帮助的处境。", "primary_collocate": null, "pronunciation": "gū lì", "ipa": "ku˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "新同学刚来，觉得很孤立。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有朋友，在学校很孤立。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬到新城市以后，她感到孤立。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人一个人住，常常觉得孤立。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别这样，会让自己更孤立的。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不爱说话，在班里有点孤立。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人和他玩，他一个人很孤立。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个孩子总是一个人，显得孤立。", "target_word": "孤立", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在国外工作的头几年，我觉得很孤立。", "target_word": "孤立", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她性格太冷淡，朋友越来越少，变得孤立了。", "target_word": "孤立", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "孤立地", "label": "副词形式"}], "register": "中性", "sense_fingerprint": "人在集体中被隔开，没有朋友和支持", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbdf5e2f-210f-4716-b9b6-47323c31ed04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26984, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "孤立", "is_correct": true, "explanation": "正确。新同学刚来，还没有朋友，感到孤单，符合“孤立”的意思。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”形容物体或事情的公开程度，不能说“觉得很透明”。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”形容光线或眼神，不用于描述“觉得”的感受。"}, {"text": "坚硬", "is_correct": false, "explanation": "搭配：“坚硬”形容物体的质地，不能说“觉得很坚硬”。"}], "explanations": {"孤立": "正确。新同学刚来，还没有朋友，感到孤单，符合“孤立”的意思。", "透明": "搭配：“透明”形容物体或事情的公开程度，不能说“觉得很透明”。", "明亮": "搭配：“明亮”形容光线或眼神，不用于描述“觉得”的感受。", "坚硬": "搭配：“坚硬”形容物体的质地，不能说“觉得很坚硬”。"}, "sentence_index": 0, "correct_answer": "孤立"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他性格孤立，从不主动跟别人说话。", "explanation": "这里应该用〈孤僻〉。孤僻形容性格不合群，孤立指处境或状态，不能用来形容性格。"}, {"text": "他做事很孤立，从来不找别人帮忙。", "explanation": "这里应该用〈独立〉。独立指自己做事、不依赖别人，孤立指缺少朋友或支持，不适合形容做事的方式。"}, {"text": "这道菜很孤立，一点儿也不好吃。", "explanation": "这里应该用〈难吃〉。孤立形容人没有朋友、感到孤单，不用来形容菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "孤立", "is_correct": true, "explanation": "正确。没有人陪他玩，他一个人很孤单，符合“孤立”的意思。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：前句“没有人和他玩”说明他独处，与“热闹”的场景相矛盾。"}, {"text": "好客", "is_correct": false, "explanation": "语义：“好客”指热情待客，一个人没有客人可接待，读来不通。"}, {"text": "辽阔", "is_correct": false, "explanation": "搭配：“辽阔”形容空间范围，不能用来描述一个人的状态。"}], "explanations": {"孤立": "正确。没有人陪他玩，他一个人很孤单，符合“孤立”的意思。", "热闹": "语义：前句“没有人和他玩”说明他独处，与“热闹”的场景相矛盾。", "好客": "语义：“好客”指热情待客，一个人没有客人可接待，读来不通。", "辽阔": "搭配：“辽阔”形容空间范围，不能用来描述一个人的状态。"}, "sentence_index": 6, "correct_answer": "孤立"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌很孤立，好听极了。", "explanation": "这里应该用〈优美〉。孤立形容人没有朋友、感到孤单，不用来评价歌曲。"}, {"text": "他的成绩很孤立，每次都是班里第一。", "explanation": "这里应该用〈优秀〉。孤立形容人没有朋友、感到孤单，不用来形容成绩。"}, {"text": "他的笑容很孤立，让人很舒服。", "explanation": "这里应该用〈温和〉。孤立形容人没有朋友、感到孤单，不用来形容笑容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在班里很孤立着，没有人跟他说话。", "corrected_sentence": "他在班里很孤立，没有人跟他说话。", "error_description": "体标误用：“很孤立”是形容词谓语，表示状态，后面不能加“着”，应说“他在班里很孤立”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他孤立的坐在角落里，没人理他。", "corrected_sentence": "他孤立地坐在角落里，没人理他。", "error_description": "状语标记错误：副词性状语后应用“地”，不能写成“的”，应为“孤立地坐在角落里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e98ee5d-27a7-4a7a-841a-afebe2286d71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
