INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26986, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "基础科学是研究世界为什么这样的科学。", "primary_collocate": null, "pronunciation": "jī chǔ kē xué", "ipa": "tɕi˥ ʈʂʰu˨˩˦ kʰɤ˥ ɕɥe˧˥", "syllable_count": 4, "sentences": [{"text": "基础科学问的是：世界为什么这样？", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问天为什么是蓝的，这就是基础科学的问题。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学基础科学，要多问“为什么”。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学、物理都是基础科学。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基础科学帮我们明白世界是怎么回事。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她读大学时选了基础科学。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道星星为什么亮，所以学基础科学。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做基础科学要有耐心，因为答案来得慢。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，基础科学是所有技术的根。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对基础科学很感兴趣，常常看这方面的书。", "target_word": "基础科学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "基础科学研究", "label": "复合"}], "register": "中性", "sense_fingerprint": "通俗说法：探究世界为什么这样的科学", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33b2cc55-a89d-45a8-b3eb-d0c547cd39fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26986, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房不会提出“世界为什么这样”的问题，不能作主语。"}, {"text": "基础科学", "is_correct": true, "explanation": "基础科学作主语，问的是世界为什么这样，句意成立。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语义：“玩意儿”指东西，不能提出问题，“问的是”说不通。"}, {"text": "股票", "is_correct": false, "explanation": "语义：股票不能发问，也不指探究世界的学科。"}], "explanations": {"厨房": "语义：厨房不会提出“世界为什么这样”的问题，不能作主语。", "基础科学": "基础科学作主语，问的是世界为什么这样，句意成立。", "玩意儿": "语义：“玩意儿”指东西，不能提出问题，“问的是”说不通。", "股票": "语义：股票不能发问，也不指探究世界的学科。"}, "sentence_index": 0, "correct_answer": "基础科学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "基础科学问的是人生的意义。", "explanation": "这里应该用〈哲学〉。基础科学探究自然规律，不讨论人生的意义。"}, {"text": "基础科学的工作是造桥。", "explanation": "这里应该用〈工程师〉。基础科学是学科，不是从事造桥工作的人。"}, {"text": "基础科学研究怎样把手机做得更便宜。", "explanation": "这里应该用〈应用技术〉。基础科学探究世界为什么这样，不研究怎样降低产品成本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝与“知道星星为什么亮”无关，不能作为学习的对象。"}, {"text": "基础科学", "is_correct": true, "explanation": "基础科学作“学”的宾语，表示所学的学科，与“想知道星星为什么亮”的目的吻合。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯不能用来解释星星为什么亮，前后逻辑不通。"}, {"text": "二手货", "is_correct": false, "explanation": "语义：“二手货”指用过的旧东西，不是学科，不能解释星星为什么亮。"}], "explanations": {"螺丝": "语义：螺丝与“知道星星为什么亮”无关，不能作为学习的对象。", "基础科学": "基础科学作“学”的宾语，表示所学的学科，与“想知道星星为什么亮”的目的吻合。", "地毯": "语义：地毯不能用来解释星星为什么亮，前后逻辑不通。", "二手货": "语义：“二手货”指用过的旧东西，不是学科，不能解释星星为什么亮。"}, "sentence_index": 6, "correct_answer": "基础科学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "基础科学每天给病人看病，很辛苦。", "explanation": "这里应该用〈医生〉。基础科学是学科，不是做事的人，不能给病人看病。"}, {"text": "基础科学在画室里画画。", "explanation": "这里应该用〈画家〉。基础科学指学科，不是能在画室里作画的人。"}, {"text": "他每天弹基础科学。", "explanation": "这里应该用〈钢琴〉。“弹”搭配乐器，基础科学是学科，不能用“弹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只基础科学很难。", "corrected_sentence": "这门基础科学很难。", "error_description": "量词错误：学科“基础科学”用“门”计量，“这只”错误，应说“这门基础科学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他想学了基础科学。", "corrected_sentence": "他想学基础科学。", "error_description": "体标错误：“想”表示意愿，后面不能带“了”，应说“想学基础科学”，不说“想学了基础科学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
