INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26988, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用来加一些东西让事情更完整。", "primary_collocate": null, "pronunciation": "bǔ chōng xìng", "ipa": "pu˨˩˦ ʈʂʰʊŋ˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这页笔记的补充性很强，让课本的内容更完整。", "target_word": "补充性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的回答很有补充性，让我们听懂了全部内容。", "target_word": "补充性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些图片的补充性很强，能帮助大家理解文章。", "target_word": "补充性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小游戏只起补充性作用，主要学习还是上课。", "target_word": "补充性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇短文是补充性阅读，不用全部做完。", "target_word": "补充性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "补充性材料放在书后面，需要时再看。", "target_word": "补充性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们一份补充性资料，帮助复习。", "target_word": "补充性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条建议的补充性不大，所以不用改计划。", "target_word": "补充性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把补充性内容放在最后一页。", "target_word": "补充性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了补充性的练习本，想多练一练。", "target_word": "补充性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "補充性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "补充性：用来增加内容、让事情更完整的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65bf7ffb-9382-49a3-a249-55e085870a35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26988, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "补充性", "is_correct": true, "explanation": "正确：“有补充性”指笔记起增加内容的作用，能让课本内容更完整。"}, {"text": "局限性", "is_correct": false, "explanation": "语义：“局限性”指受限制、不完整，与“让课本的内容更完整”的意思相反。"}, {"text": "随意性", "is_correct": false, "explanation": "语义：“随意性”指随便、不规范，无法使内容更完整。"}, {"text": "偶然性", "is_correct": false, "explanation": "语义：“偶然性”指事情偶然发生，与“让课本的内容更完整”无关。"}], "explanations": {"补充性": "正确：“有补充性”指笔记起增加内容的作用，能让课本内容更完整。", "局限性": "语义：“局限性”指受限制、不完整，与“让课本的内容更完整”的意思相反。", "随意性": "语义：“随意性”指随便、不规范，无法使内容更完整。", "偶然性": "语义：“偶然性”指事情偶然发生，与“让课本的内容更完整”无关。"}, "sentence_index": 0, "correct_answer": "补充性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份资料的补充性很强，正式考试时会全部考到。", "explanation": "这里应该用〈重要性〉。补充性指额外增加的内容，不是主要部分；说“正式考试时会全部考到”要用〈重要性〉。"}, {"text": "删掉这些内容以后，课本的补充性更强了。", "explanation": "词义错误：这里说的是删去内容，应该用〈删减〉。补充性指增加内容使事情完整，不能表示减少。"}, {"text": "妈妈的补充性很强，家里的事情全靠她。", "explanation": "用法错误：补充性不用来形容人。形容人能干应说〈能干〉，形容人帮忙应说〈热心〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "补充性", "is_correct": true, "explanation": "正确：“一份补充性资料”指用来补充课本、帮助复习的资料。"}, {"text": "机密性", "is_correct": false, "explanation": "语义：机密资料不会发给全班复习，与“老师给我们”“帮助复习”的语境相冲突。"}, {"text": "随机性", "is_correct": false, "explanation": "语义：“随机性”指随意、不确定，不能用来描述用于复习的资料。"}, {"text": "对抗性", "is_correct": false, "explanation": "语义：“对抗性”指相互抵触，与“帮助复习”的资料意思相反。"}], "explanations": {"补充性": "正确：“一份补充性资料”指用来补充课本、帮助复习的资料。", "机密性": "语义：机密资料不会发给全班复习，与“老师给我们”“帮助复习”的语境相冲突。", "随机性": "语义：“随机性”指随意、不确定，不能用来描述用于复习的资料。", "对抗性": "语义：“对抗性”指相互抵触，与“帮助复习”的资料意思相反。"}, "sentence_index": 6, "correct_answer": "补充性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门课有补充性，所有学生都必须上。", "explanation": "这里应该用〈必修〉。补充性指额外增加的内容，不表示必须；说“所有学生都要上”要用〈必修〉。"}, {"text": "这份报告的补充性很强，数据完全经得起检验。", "explanation": "这里应该用〈可靠性〉。补充性指增加内容使事情更完整，不表示可以信赖；说“经得起检验”要用〈可靠性〉。"}, {"text": "这个方案的补充性很强，它完全取代了原来的计划。", "explanation": "词义错误：这里说的是取代，应该用〈替代性〉。补充性指增加内容，不是替换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份笔记的补充性强很，能让课本内容更完整。", "corrected_sentence": "这份笔记的补充性很强，能让课本内容更完整。", "error_description": "语序错误：程度副词“很”应放在形容词“强”之前，“补充性很强”是正确说法，不说“补充性强很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份资料的补充性很强很，能让复习更轻松。", "corrected_sentence": "这份资料的补充性很强，能让复习更轻松。", "error_description": "程度副词重复：“很”只需放在“强”之前一次，句末多余的“很”不合语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '450d132b-4bd7-4a84-8933-49fea60b7584') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
