INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26990, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来收集并盛放物品的器具。", "primary_collocate": null, "pronunciation": "shōu jí qì", "ipa": "ʂou̯˥ tɕi˧˥ tɕʰi˥˩", "syllable_count": 3, "sentences": [{"text": "学校在门口放了一个旧电池收集器。", "target_word": "收集器", "complexity_tier": "T3", "furigana": "xué xiào zài mén kǒu fàng le yí gè jiù diàn chí shōu jí qì.", "sentence_source": "generated"}, {"text": "他把空瓶子扔进了收集器里。", "target_word": "收集器", "complexity_tier": "T3", "furigana": "tā bǎ kōng píng zi rēng jìn le shōu jí qì lǐ.", "sentence_source": "generated"}, {"text": "收集器里装满了雨水，要及时倒掉。", "target_word": "收集器", "complexity_tier": "T3", "furigana": "shōu jí qì lǐ zhuāng mǎn le yǔ shuǐ, yào jí shí dào diào.", "sentence_source": "generated"}, {"text": "这个收集器太小，装不下这么多垃圾。", "target_word": "收集器", "complexity_tier": "T3", "furigana": "zhè gè shōu jí qì tài xiǎo, zhuāng bu xià zhè me duō lājī.", "sentence_source": "generated"}, {"text": "海边放着一个收集器，专门收集垃圾。", "target_word": "收集器", "complexity_tier": "T3", "furigana": "hǎi biān fàng zhe yí gè shōu jí qì, zhuān mén shōu jí lājī.", "sentence_source": "generated"}, {"text": "请把用过的纸放进收集器。", "target_word": "收集器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里的收集器已经生锈了。", "target_word": "收集器", "complexity_tier": "T3", "furigana": "yuàn zi lǐ de shōu jí qì yǐ jīng shēng xiù le.", "sentence_source": "generated"}, {"text": "妈妈买了一个新的收集器，用来装旧报纸。", "target_word": "收集器", "complexity_tier": "T3", "furigana": "mā ma mǎi le yí gè xīn de shōu jí qì, yòng lái zhuāng jiù bào zhǐ.", "sentence_source": "generated"}, {"text": "学校的收集器里放满了落叶。", "target_word": "收集器", "complexity_tier": "T3", "furigana": "xué xiào de shōu jí qì lǐ fàng mǎn le luò yè.", "sentence_source": "generated"}, {"text": "收集器满了，就倒到大桶里。", "target_word": "收集器", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "收集器：日常用来装东西的容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33b2cc55-a89d-45a8-b3eb-d0c547cd39fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26990, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收集器", "is_correct": true, "explanation": "“旧电池收集器”是用来存放旧电池的装置，与句意相合。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：洗衣机用来洗衣服，不用来存放旧电池。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟用于定时响铃，与放在门口存放旧电池的用途不符。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：“花瓶”用来插花，不与“旧电池”组合。"}], "explanations": {"收集器": "“旧电池收集器”是用来存放旧电池的装置，与句意相合。", "洗衣机": "语义：洗衣机用来洗衣服，不用来存放旧电池。", "闹钟": "语义：闹钟用于定时响铃，与放在门口存放旧电池的用途不符。", "花瓶": "搭配：“花瓶”用来插花，不与“旧电池”组合。"}, "sentence_index": 0, "correct_answer": "收集器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用收集器写字。", "explanation": "这里应该用〈钢笔〉。收集器是用来装东西的器具，写字要用钢笔，不能用收集器。"}, {"text": "他是一位知名的收集器。", "explanation": "这里应该用〈收藏家〉。“收集器”指装置或容器，指收藏东西的人要用〈收藏家〉。"}, {"text": "他用收集器喝水。", "explanation": "这里应该用〈杯子〉。收集器用来收集或存放物品，喝水要用杯子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26990, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收集器", "is_correct": true, "explanation": "“收集器”已经生锈，是金属制成的装置，与“生锈”相合。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不会生锈，与“已经生锈了”矛盾。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不会生锈，与“已经生锈了”矛盾。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“生锈”只与金属搭配，不与“花园”搭配。"}], "explanations": {"收集器": "“收集器”已经生锈，是金属制成的装置，与“生锈”相合。", "玻璃": "语义：玻璃不会生锈，与“已经生锈了”矛盾。", "木头": "语义：木头不会生锈，与“已经生锈了”矛盾。", "花园": "搭配：“生锈”只与金属搭配，不与“花园”搭配。"}, "sentence_index": 6, "correct_answer": "收集器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "收集器正在洗衣服。", "explanation": "这里应该用〈洗衣机〉。收集器是用来装东西的器具，不能洗衣服，洗衣服要用洗衣机。"}, {"text": "收集器响了，把我吵醒了。", "explanation": "这里应该用〈闹钟〉。收集器是用来装东西的器具，不会定时响铃，把人吵醒的要用闹钟。"}, {"text": "他用收集器切菜。", "explanation": "这里应该用〈菜刀〉。收集器是用来装东西的器具，切菜要用菜刀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口放着一条雨水收集器。", "corrected_sentence": "门口放着一个雨水收集器。", "error_description": "量词错误：“收集器”是装置，应用“个”，不用“条”（“条”多用于细长之物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把旧报纸放进收集器上。", "corrected_sentence": "请把旧报纸放进收集器里。", "error_description": "方位词错误：“放进”表示进入容器内部，收集器是盛放东西的器具，应说“收集器里”，不能说“收集器上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dff0ae95-8d23-42c5-a1f9-dc49589f7ea6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
