INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26992, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26992, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "涂层就是涂在东西外面的一层东西，比如墙上的油漆。", "primary_collocate": null, "pronunciation": "tú céng", "ipa": "tʰu˧˥ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "墙上的涂层已经旧了。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人在木门上刷了一层新涂层。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的墙有一层防油涂层。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不粘锅里面有一层黑色的涂层。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水把外墙的涂层冲掉了。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种涂层摸起来很光滑。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船底的涂层可以防止生锈。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小心地擦着桌子，怕弄坏涂层。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "涂层干了以后，才可以搬家具。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地板上的涂层有点儿滑。", "target_word": "涂层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "层", "label": "量词"}, {"form": "防油涂层", "label": "复合"}, {"form": "塗層", "label": "繁体"}], "register": "中性", "sense_fingerprint": "涂在东西外面的一层，如墙上的油漆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851baa46-0c4d-405d-9c2e-d5933994bbc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "涂层", "is_correct": true, "explanation": "正确：墙面外侧涂的一层东西，用久了会旧，与句意相符。"}, {"text": "地板", "is_correct": false, "explanation": "语义：地板铺在地面，不会出现在墙上，与“墙上的”矛盾。"}, {"text": "天花板", "is_correct": false, "explanation": "语义：天花板在屋顶，不是墙上的东西，与“墙上的”矛盾。"}, {"text": "脚印", "is_correct": false, "explanation": "搭配：“脚印”不会“旧”，“已经旧了”不能用来说脚印。"}], "explanations": {"涂层": "正确：墙面外侧涂的一层东西，用久了会旧，与句意相符。", "地板": "语义：地板铺在地面，不会出现在墙上，与“墙上的”矛盾。", "天花板": "语义：天花板在屋顶，不是墙上的东西，与“墙上的”矛盾。", "脚印": "搭配：“脚印”不会“旧”，“已经旧了”不能用来说脚印。"}, "sentence_index": 0, "correct_answer": "涂层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她脸上涂了一层涂层。", "explanation": "这里应该用〈粉底〉。粉底是涂在脸上的化妆品；涂层指涂在物体表面的一层，不用于人的脸。"}, {"text": "手机贴了一层涂层。", "explanation": "这里应该用〈保护膜〉。保护膜是贴上去的，涂层是涂上去的，不说“贴”涂层。"}, {"text": "妈妈在面包上抹了一层涂层。", "explanation": "这里应该用〈黄油〉。抹在面包上吃的是黄油；涂层是涂在物体表面起保护或装饰作用的一层，不用于食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "涂层", "is_correct": true, "explanation": "正确：船底涂的防护层可以防止生锈，与句意相符。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝本身不能防止生锈，句子说的是防护作用，与之矛盾。"}, {"text": "木板", "is_correct": false, "explanation": "搭配：木板不会生锈，“防止生锈”不能用来说木板。"}, {"text": "船帆", "is_correct": false, "explanation": "语义：船帆是帆布，不能防止生锈，与句中的防护作用不符。"}], "explanations": {"涂层": "正确：船底涂的防护层可以防止生锈，与句意相符。", "螺丝": "语义：螺丝本身不能防止生锈，句子说的是防护作用，与之矛盾。", "木板": "搭配：木板不会生锈，“防止生锈”不能用来说木板。", "船帆": "语义：船帆是帆布，不能防止生锈，与句中的防护作用不符。"}, "sentence_index": 6, "correct_answer": "涂层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "铁栏杆上长了一层涂层。", "explanation": "这里应该用〈锈〉。锈是金属自然长出来的，涂层是人工涂上去的，不能说“长”出来。"}, {"text": "窗户上结了一层涂层。", "explanation": "这里应该用〈霜〉。霜是气温降低后结出来的，涂层不会自己结成。"}, {"text": "水壶里积了一层涂层。", "explanation": "这里应该用〈水垢〉。水垢是水中矿物质沉积形成的，不是人工涂上的，不说涂层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "师傅在铁门上喷了一条红色的涂层。", "corrected_sentence": "师傅在铁门上喷了一层红色的涂层。", "error_description": "量词错误：“涂层”是薄薄的一层，应搭配量词“层”，“条”用于细长的东西，不能修饰“涂层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人在卫生间的地面上刷了一只涂层。", "corrected_sentence": "工人在卫生间的地面上刷了一层涂层。", "error_description": "量词错误：“涂层”是薄薄的一层，应搭配量词“层”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26994, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "天然", "is_correct": true, "explanation": "“天然”与“人工”构成反义：一个是自然形成的，一个是人做的。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”表示明白或明显，与“人工”没有反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”形容速度快，与“人工”没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”形容事物构成繁多，与“人工”没有反义关系。"}], "correct_answer": "天然", "explanations": {"天然": "“天然”与“人工”构成反义：一个是自然形成的，一个是人做的。", "清楚": "“清楚”表示明白或明显，与“人工”没有反义关系。", "迅速": "“迅速”形容速度快，与“人工”没有反义关系。", "复杂": "“复杂”形容事物构成繁多，与“人工”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26994, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "天然", "is_correct": true, "explanation": "“天然”与“人工”构成反义：一个是自然形成的，一个是人做的。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容没有声音或吵闹的状态，与“人工”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容好看，与“人工”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”形容人多声响大，与“人工”没有反义关系。"}], "correct_answer": "天然", "explanations": {"天然": "“天然”与“人工”构成反义：一个是自然形成的，一个是人做的。", "安静": "“安静”形容没有声音或吵闹的状态，与“人工”没有反义关系。", "漂亮": "“漂亮”形容好看，与“人工”没有反义关系。", "热闹": "“热闹”形容人多声响大，与“人工”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26994, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不是天然的，是人做的。", "primary_collocate": null, "pronunciation": "rén gōng", "ipa": "ʐən³⁵ kʊŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "这个池塘是人工的，不是天然的。", "target_word": "人工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些草是人工种的，不是自己长的。", "target_word": "人工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草地上的小山是人工堆起来的。", "target_word": "人工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种味道是人工加的，不是天然的。", "target_word": "人工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片海滩是人工建的。", "target_word": "人工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山顶的亭子是人工修的，路也是。", "target_word": "人工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的湖是人工的，水从河里引来。", "target_word": "人工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人工养的鱼，没有野生的鱼好吃。", "target_word": "人工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢天然的花，不喜欢人工的花。", "target_word": "人工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的瀑布是人工做的。", "target_word": "人工", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "人工湖", "label": "复合"}, {"form": "人工智能", "label": "复合"}], "register": "中性", "sense_fingerprint": "不是天然的，是人做出来的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '346c9218-cb43-4e91-8a90-710077c45e12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26994, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人工", "is_correct": true, "explanation": "人工：不是天然形成，由人做的，符合“这个池塘是……的，不是天然的”的语境。"}, {"text": "天然", "is_correct": false, "explanation": "语义：后半句已说“不是天然的”，填入“天然”会与句意矛盾。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”形容明白或明显，不能用来说池塘是怎样形成的。"}, {"text": "迅速", "is_correct": false, "explanation": "搭配：“迅速”形容速度快，不能用来说明池塘的形成方式。"}], "explanations": {"人工": "人工：不是天然形成，由人做的，符合“这个池塘是……的，不是天然的”的语境。", "天然": "语义：后半句已说“不是天然的”，填入“天然”会与句意矛盾。", "清楚": "搭配：“清楚”形容明白或明显，不能用来说池塘是怎样形成的。", "迅速": "搭配：“迅速”形容速度快，不能用来说明池塘的形成方式。"}, "sentence_index": 0, "correct_answer": "人工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是人工的，不是天然的。", "explanation": "这里误用了对象：“人工”指人造的物品或事物，不能用来形容人；若指人造的人形，应说〈机器人〉。"}, {"text": "这块石头是人工的，是河水冲出来的。", "explanation": "这里应该用〈天然〉。“河水冲出来”说明不是人做的，与“人工”矛盾。"}, {"text": "这片森林是人工的，几千年前就自己长起来了。", "explanation": "这里应该用〈天然〉。“自己长起来”说明不是人做的，与“人工”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人工", "is_correct": true, "explanation": "人工：由人做的，符合“山上的湖是……的，水从河里引来”的语境。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”形容味道，不能用来说湖是怎样形成的。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人的智力，不能用来形容湖。"}, {"text": "温柔", "is_correct": false, "explanation": "搭配：“温柔”形容人的性情，不能用来说湖的形成方式。"}], "explanations": {"人工": "人工：由人做的，符合“山上的湖是……的，水从河里引来”的语境。", "辣": "搭配：“辣”形容味道，不能用来说湖是怎样形成的。", "聪明": "搭配：“聪明”形容人的智力，不能用来形容湖。", "温柔": "搭配：“温柔”形容人的性情，不能用来说湖的形成方式。"}, "sentence_index": 6, "correct_answer": "人工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盆花是人工的，是从野外挖来的。", "explanation": "这里应该用〈天然〉。“从野外挖来”说明它是天然的，与“人工”自相矛盾。"}, {"text": "公司最缺的是人工资源。", "explanation": "这里应该用〈人力〉。“人力资源”是固定说法，“人工资源”不能这样说。"}, {"text": "这家店卖的都是人工艺品。", "explanation": "这里应该用〈手工〉。“手工艺品”是固定说法，“人工艺品”不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河是人工挖。", "corrected_sentence": "这条河是人工挖的。", "error_description": "“是……的”句式的结尾要用“的”，“人工挖”后漏了“的”。应说“这条河是人工挖的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城堡是人工建了。", "corrected_sentence": "这座城堡是人工建的。", "error_description": "错误：句尾用错。“是……的”句式要用“的”，不能用“了”，应说“这座城堡是人工建的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '004127e3-e087-4eef-b3a0-2697a32aa1c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
