INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27002, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "建好了一个东西。", "primary_collocate": null, "pronunciation": "jiàn chéng", "ipa": "tɕjɛn˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这座房子三个月就建成了。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们建成了一个小花园。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新桥建成以后，过河方便多了。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这栋大楼是什么时候建成的？", "target_word": "建成", "complexity_tier": "T3", "furigana": "jiàn chéng", "sentence_source": "generated"}, {"text": "学校旁边建成了一座新食堂。", "target_word": "建成", "complexity_tier": "T3", "furigana": "jiàn chéng", "sentence_source": "generated"}, {"text": "这条路快要建成了。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明用积木建成了一座城堡。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机场建成后，来的人更多了。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们一年就建成了这座楼。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桥还没建成，我们只能坐船。", "target_word": "建成", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "建成了", "label": "完成体"}], "register": "书面", "sense_fingerprint": "建成·动词·把东西建好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bc74ad3-fce1-4a1c-a4e5-5f5ab986044a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27002, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "建成", "is_correct": true, "explanation": "建成 jiàn chéng：把东西建好，是正确答案。"}, {"text": "坚称", "is_correct": false, "explanation": "坚称 jiānchēng 与 建成 jiànchéng 两个字的声调都不同（jiān/jiàn，chēng/chéng），意思是坚决地说。"}, {"text": "简称", "is_correct": false, "explanation": "简称 jiǎnchēng 与 建成 jiànchéng 两个字的声调都不同（jiǎn/jiàn，chēng/chéng），意思是简略的名称。"}, {"text": "现成", "is_correct": false, "explanation": "xiànchéng 与 jiànchéng 的声母不同（x 与 j），意思是现成（现有的、不用加工的）。"}], "explanations": {"建成": "建成 jiàn chéng：把东西建好，是正确答案。", "坚称": "坚称 jiānchēng 与 建成 jiànchéng 两个字的声调都不同（jiān/jiàn，chēng/chéng），意思是坚决地说。", "简称": "简称 jiǎnchēng 与 建成 jiànchéng 两个字的声调都不同（jiǎn/jiàn，chēng/chéng），意思是简略的名称。", "现成": "xiànchéng 与 jiànchéng 的声母不同（x 与 j），意思是现成（现有的、不用加工的）。"}, "sentence_index": null, "correct_answer": "建成"}, "level_3": {"options": [{"text": "建成", "is_correct": true, "explanation": "建成：指房子建好，与“三个月就”的时间状语相符。"}, {"text": "住进", "is_correct": false, "explanation": "配价：“住进”的施事须是人，房子不能作“住进”的主语。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：房子不能被“吃掉”，与句中建造的语境不符。"}, {"text": "写完", "is_correct": false, "explanation": "搭配：“写完”的对象是文字，不能用于房子。"}], "explanations": {"建成": "建成：指房子建好，与“三个月就”的时间状语相符。", "住进": "配价：“住进”的施事须是人，房子不能作“住进”的主语。", "吃掉": "语义：房子不能被“吃掉”，与句中建造的语境不符。", "写完": "搭配：“写完”的对象是文字，不能用于房子。"}, "sentence_index": 0, "correct_answer": "建成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份午饭是什么时候建成的？", "explanation": "这里应该用〈做好〉。建成指把较大的东西建好，午饭是做好的，不说建成。"}, {"text": "这封信是什么时候建成的？", "explanation": "这里应该用〈写好〉。建成不用于信件，信件是写好的。"}, {"text": "这件毛衣是什么时候建成的？", "explanation": "这里应该用〈织好〉。建成不用于织物，毛衣是织好的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740a8dd6-612a-4984-b445-3f0ac1250d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建成", "is_correct": true, "explanation": "建成：指把城堡建好，与“用积木”的语境相符。"}, {"text": "烧成", "is_correct": false, "explanation": "语义：“烧成”指烧制成型，与“用积木”的拼搭语境不符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象不是城堡，用积木也不能“洗”城堡。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”用于食物，不能用于拼搭城堡。"}], "explanations": {"建成": "建成：指把城堡建好，与“用积木”的语境相符。", "烧成": "语义：“烧成”指烧制成型，与“用积木”的拼搭语境不符。", "洗": "搭配：“洗”的对象不是城堡，用积木也不能“洗”城堡。", "煮": "搭配：“煮”用于食物，不能用于拼搭城堡。"}, "sentence_index": 6, "correct_answer": "建成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "饺子还没建成，我们只能等一等。", "explanation": "这里应该用〈包好〉。建成不用于饺子，饺子是包好的。"}, {"text": "衣服还没建成，我们只能穿旧的。", "explanation": "这里应该用〈缝好〉。建成不用于衣物，衣服是缝好的。"}, {"text": "这幅画还没建成，我们只能看草稿。", "explanation": "这里应该用〈画好〉。建成不用于绘画，画是画好的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740a8dd6-612a-4984-b445-3f0ac1250d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个仓库明年就能建成过。", "corrected_sentence": "这个仓库明年就能建成。", "error_description": "错误在于“过”：“过”表示已经发生过的经历，与“明年”这样的未来时间不能搭配。应去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740a8dd6-612a-4984-b445-3f0ac1250d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座商场年底会才建成。", "corrected_sentence": "这座商场年底才会建成。", "error_description": "错误在于语序：“才”和“会”颠倒。“才会”是固定次序，应说“这座商场年底才会建成”，“会才”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '740a8dd6-612a-4984-b445-3f0ac1250d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
