INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27006, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有感觉。", "primary_collocate": null, "pronunciation": "wú gǎn", "ipa": "u˧˥ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "打了麻药以后，他的腿完全无感。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手冻僵了，我对冷热几乎无感。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天天吃同样的菜，我对它已经无感了。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打完针以后，这块皮肤就无感了。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人对疼痛无感，医生觉得很奇怪。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手冻得完全无感，拿不住杯子。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了太多冰的东西，我的舌头有点儿无感。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在冰水里泡了很久，我的手指已经无感了。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打了麻药，嘴唇到现在还是无感。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐太久了，我的脚已经无感了。", "target_word": "无感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "身体或心理上没有感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '851baa46-0c4d-405d-9c2e-d5933994bbc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27006, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无感", "is_correct": true, "explanation": "正确：wú gǎn，意思是身体没有感觉。"}, {"text": "五感", "is_correct": false, "explanation": "wǔ gǎn（第三声）与 wú gǎn（第二声）声调不同，意思是五种感觉。"}, {"text": "无根", "is_correct": false, "explanation": "gēn（第一声）与 gǎn（第三声）韵母和声调都不同，意思是没有根。"}, {"text": "无干", "is_correct": false, "explanation": "gān（第一声）与 gǎn（第三声）声调不同，意思是没有关系。"}], "explanations": {"无感": "正确：wú gǎn，意思是身体没有感觉。", "五感": "wǔ gǎn（第三声）与 wú gǎn（第二声）声调不同，意思是五种感觉。", "无根": "gēn（第一声）与 gǎn（第三声）韵母和声调都不同，意思是没有根。", "无干": "gān（第一声）与 gǎn（第三声）声调不同，意思是没有关系。"}, "sentence_index": null, "correct_answer": "无感"}, "level_3": {"options": [{"text": "无感", "is_correct": true, "explanation": "正确：麻药使腿失去知觉，“完全无感”即没有感觉。"}, {"text": "灵敏", "is_correct": false, "explanation": "语义：“灵敏”指感觉敏锐，与打了麻药后腿失去知觉的情形相反。"}, {"text": "灵活", "is_correct": false, "explanation": "语义：“灵活”指动作自如，打了麻药的腿不会灵活。"}, {"text": "清醒", "is_correct": false, "explanation": "搭配：“清醒”形容头脑，不用来形容腿。"}], "explanations": {"无感": "正确：麻药使腿失去知觉，“完全无感”即没有感觉。", "灵敏": "语义：“灵敏”指感觉敏锐，与打了麻药后腿失去知觉的情形相反。", "灵活": "语义：“灵活”指动作自如，打了麻药的腿不会灵活。", "清醒": "搭配：“清醒”形容头脑，不用来形容腿。"}, "sentence_index": 0, "correct_answer": "无感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一听到好消息，我的心一下子就无感了，高兴得跳了起来。", "explanation": "这里应该用〈激动〉。无感表示没有感觉，与“高兴得跳了起来”的强烈反应矛盾，应该用“激动”。"}, {"text": "这首歌好听极了，我听得入迷，耳朵却完全无感。", "explanation": "这里应该用〈敏锐〉。无感表示没有感觉，与“听得入迷”需要灵敏的听觉矛盾，应该用“敏锐”。"}, {"text": "吃了一块冰，我的舌头很无感，却能清楚地尝出每一种味道。", "explanation": "这里应该用〈灵敏〉。无感表示没有感觉，与“能清楚地尝出每一种味道”矛盾，应该用“灵敏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无感", "is_correct": true, "explanation": "正确：吃了太多冰，舌头感觉变弱，“有点儿无感”即失去知觉。"}, {"text": "敏锐", "is_correct": false, "explanation": "语义：“敏锐”指感觉灵敏，与吃了太多冰后舌头变得迟钝相反。"}, {"text": "机灵", "is_correct": false, "explanation": "搭配：“机灵”形容人的反应，不用来形容舌头。"}, {"text": "尖锐", "is_correct": false, "explanation": "语义：“尖锐”指刺痛，与舌头失去知觉的情形正相反。"}], "explanations": {"无感": "正确：吃了太多冰，舌头感觉变弱，“有点儿无感”即失去知觉。", "敏锐": "语义：“敏锐”指感觉灵敏，与吃了太多冰后舌头变得迟钝相反。", "机灵": "搭配：“机灵”形容人的反应，不用来形容舌头。", "尖锐": "语义：“尖锐”指刺痛，与舌头失去知觉的情形正相反。"}, "sentence_index": 6, "correct_answer": "无感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的手被烫伤后很无感，一碰到东西就疼得直叫。", "explanation": "这里应该用〈敏感〉。无感表示没有感觉，与“一碰到东西就疼得直叫”矛盾，应该用“敏感”。"}, {"text": "老师的表扬让我很无感，我开心得一整天都在笑。", "explanation": "这里应该用〈感动〉。无感表示没有反应，与“开心得一整天都在笑”的情绪矛盾，应该用“感动”。"}, {"text": "听到噩耗，她的心一下子无感了，哭得撕心裂肺。", "explanation": "这里应该用〈悲痛〉。无感表示没有感觉，与“哭得撕心裂肺”的强烈情绪矛盾，应该用“悲痛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吹了一晚上风，我的脸冻完全无感了。", "corrected_sentence": "吹了一晚上风，我的脸冻得完全无感了。", "error_description": "补语标记错误：“冻”后的程度补语要用“得”引出，应说“我的脸冻得完全无感了”，不能省略“得”说“我的脸冻完全无感了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "打完麻药后，我的嘴唇一直无感过。", "corrected_sentence": "打完麻药后，我的嘴唇一直无感。", "error_description": "“无感”这里表示持续的状态，后面不能加“过”，应去掉“过”，说“一直无感”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b8024f-b22b-4953-93e5-eab38a007145') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
