INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27012, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蜜蜂是一种会飞的小虫子，它们住在蜂巢里，会采花蜜。", "primary_collocate": null, "pronunciation": "mì fēng", "ipa": "mi˥˩ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "花园里有很多蜜蜂。", "target_word": "蜜蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂在花上采蜜。", "target_word": "蜜蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂住在蜂巢里。", "target_word": "蜜蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心，那只蜜蜂会蜇人。", "target_word": "蜜蜂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，蜜蜂开始忙起来。", "target_word": "蜜蜂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家养了几箱蜜蜂。", "target_word": "蜜蜂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂飞来飞去，一直在找花。", "target_word": "蜜蜂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们吃的蜂蜜是蜜蜂做的。", "target_word": "蜜蜂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂的工作很辛苦。", "target_word": "蜜蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们看着蜜蜂，不敢走近。", "target_word": "蜜蜂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "群", "label": "量词"}], "register": "中性", "sense_fingerprint": "会采花蜜、住在蜂巢里的小昆虫", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0457a638-19e5-4662-9085-4b0c62c030be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜜蜂", "is_correct": true, "explanation": "正确：蜜蜂是会飞的小昆虫，花园里有很多蜜蜂，这句话说得通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是厨房里的电器，花园里不会有很多冰箱。"}, {"text": "书籍", "is_correct": false, "explanation": "语义：书籍一般放在室内，花园里不会有很多书籍。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“花园里有很多”后面接钢琴不合常理，钢琴不会成群地出现在花园里。"}], "explanations": {"蜜蜂": "正确：蜜蜂是会飞的小昆虫，花园里有很多蜜蜂，这句话说得通。", "冰箱": "语义：冰箱是厨房里的电器，花园里不会有很多冰箱。", "书籍": "语义：书籍一般放在室内，花园里不会有很多书籍。", "钢琴": "搭配：“花园里有很多”后面接钢琴不合常理，钢琴不会成群地出现在花园里。"}, "sentence_index": 0, "correct_answer": "蜜蜂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上在牛奶里加一勺蜜蜂。", "explanation": "这里应该用〈蜂蜜〉。蜜蜂是昆虫，加进牛奶里的是它们酿的蜂蜜。"}, {"text": "树上的蜜蜂每天早上都在唱歌。", "explanation": "这里应该用〈小鸟〉。唱歌的是鸟，蜜蜂只会嗡嗡地飞。"}, {"text": "蜜蜂是蜂群的母亲，负责产卵。", "explanation": "这里应该用〈蜂王〉。蜜蜂是这一类昆虫的统称，负责产卵、作为蜂群母亲的是蜂王。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜜蜂", "is_correct": true, "explanation": "正确：蜜蜂会采花蜜，“飞来飞去，一直在找花”说的正是它们。"}, {"text": "飞机", "is_correct": false, "explanation": "语义：飞机不会自己去找花，这句话说的是会采花的小虫。"}, {"text": "风筝", "is_correct": false, "explanation": "语义：风筝靠风和线飞，不会自己找花。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“找”要求有意识的主语，石头不能“找花”。"}], "explanations": {"蜜蜂": "正确：蜜蜂会采花蜜，“飞来飞去，一直在找花”说的正是它们。", "飞机": "语义：飞机不会自己去找花，这句话说的是会采花的小虫。", "风筝": "语义：风筝靠风和线飞，不会自己找花。", "石头": "配价：“找”要求有意识的主语，石头不能“找花”。"}, "sentence_index": 6, "correct_answer": "蜜蜂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里有一只蜜蜂，围着主人摇尾巴。", "explanation": "这里应该用〈小狗〉。摇尾巴、围着主人转的是狗，蜜蜂是会飞的昆虫。"}, {"text": "这支蜡烛是用蜜蜂做的。", "explanation": "这里应该用〈蜂蜡〉。做蜡烛的原料是蜂蜡，蜜蜂本身不是做蜡烛的材料。"}, {"text": "池塘里，蜜蜂在水面上游来游去。", "explanation": "这里应该用〈鸭子〉。蜜蜂会飞，不会在水里游。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个蜜蜂停在我的手上。", "corrected_sentence": "一只蜜蜂停在我的手上。", "error_description": "量词错误：蜜蜂这类小昆虫应该用量词“只”，不能用“个”。“一个蜜蜂”不自然，应说“一只蜜蜂”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个蜜蜂飞得很快。", "corrected_sentence": "那只蜜蜂飞得很快。", "error_description": "量词错误：蜜蜂这类小昆虫应该用量词“只”，不能用“个”。“那个蜜蜂”不自然，应说“那只蜜蜂”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
