INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27018, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27018, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "昆虫是很小的动物，比如蚂蚁和蝴蝶。", "primary_collocate": null, "pronunciation": "kūn chóng", "ipa": "kʰuən˥ ʈʂʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "花园里有很多昆虫，有蝴蝶，也有蚂蚁。", "target_word": "昆虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂是一种会采蜜的昆虫。", "target_word": "昆虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昆虫的身体很小，有六条腿。", "target_word": "昆虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天晚上，树下有很多昆虫在叫。", "target_word": "昆虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青蛙喜欢吃草地上的昆虫。", "target_word": "昆虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对昆虫很感兴趣，常常去公园找它们。", "target_word": "昆虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了各种各样的昆虫。", "target_word": "昆虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的窗户上停着一只昆虫。", "target_word": "昆虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天天气冷，昆虫都躲起来了。", "target_word": "昆虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用网抓昆虫，然后放回树林里。", "target_word": "昆虫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一只昆虫", "label": "量词"}, {"form": "一种昆虫", "label": "量词"}, {"form": "昆虫学", "label": "复合"}, {"form": "昆蟲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体很小、有六条腿的小动物，如蚂蚁、蝴蝶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172f7e52-d98b-43ac-869e-8829631459cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家具", "is_correct": false, "explanation": "语义：花园里的“家具”不会与蝴蝶、蚂蚁并列，此处语义不通。"}, {"text": "昆虫", "is_correct": true, "explanation": "“昆虫”是蝴蝶、蚂蚁所属的类别，与后文的列举相合。"}, {"text": "理想", "is_correct": false, "explanation": "搭配：“花园里有很多理想”不能成立，“理想”不是可以在花园里存在的事物。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”不属于生物，不能与蝴蝶、蚂蚁并列作为花园里的动物。"}], "explanations": {"家具": "语义：花园里的“家具”不会与蝴蝶、蚂蚁并列，此处语义不通。", "昆虫": "“昆虫”是蝴蝶、蚂蚁所属的类别，与后文的列举相合。", "理想": "搭配：“花园里有很多理想”不能成立，“理想”不是可以在花园里存在的事物。", "电脑": "语义：“电脑”不属于生物，不能与蝴蝶、蚂蚁并列作为花园里的动物。"}, "sentence_index": 0, "correct_answer": "昆虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天用昆虫洗脸。", "explanation": "这里应该用〈水〉。洗脸要用水，昆虫是动物，不能用来洗脸。"}, {"text": "他是一位很有名的昆虫，大家都认识他。", "explanation": "这里应该用〈人〉。“昆虫”是动物，不能用来指“他”这样的人。"}, {"text": "他每天骑昆虫上班。", "explanation": "这里应该用〈自行车〉。上班要骑的是自行车，昆虫是动物，不能当作交通工具来骑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心跳", "is_correct": false, "explanation": "搭配：“心跳”是身体的活动，不是可以被“介绍”的事物，“介绍各种各样的心跳”不通。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是时间单位，“各种各样的星期”在这本书的语境中语义不通。"}, {"text": "昆虫", "is_correct": true, "explanation": "“昆虫”是书中可以介绍的各类生物，与“各种各样的”搭配自然。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”是动作，不能与“各种各样的”一起被“介绍”。"}], "explanations": {"心跳": "搭配：“心跳”是身体的活动，不是可以被“介绍”的事物，“介绍各种各样的心跳”不通。", "星期": "语义：“星期”是时间单位，“各种各样的星期”在这本书的语境中语义不通。", "昆虫": "“昆虫”是书中可以介绍的各类生物，与“各种各样的”搭配自然。", "脚步": "搭配：“脚步”是动作，不能与“各种各样的”一起被“介绍”。"}, "sentence_index": 6, "correct_answer": "昆虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蝴蝶在叶子上产下了昆虫。", "explanation": "这里应该用〈卵〉。蝴蝶产下的是卵，不能说“产下昆虫”。"}, {"text": "他用昆虫打电话。", "explanation": "这里应该用〈手机〉。打电话要用手机，昆虫是动物，不能用来打电话。"}, {"text": "我们在昆虫里上课。", "explanation": "这里应该用〈教室〉。上课要在教室里，昆虫是动物，不能当作上课的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草丛里飞出了一颗昆虫。", "corrected_sentence": "草丛里飞出了一只昆虫。", "error_description": "错误：量词用了“颗”。正确：“一只昆虫”。“颗”用于小而圆的东西，如“一颗珠子”；昆虫应用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在树下捉了到一只昆虫。", "corrected_sentence": "我在树下捉到了一只昆虫。", "error_description": "错误：动态助词“了”放在了动词“捉”和结果补语“到”之间。正确：“捉到了”，“了”应放在补语“到”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
