INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27030, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "蜜蜂找花里的甜汁。", "primary_collocate": null, "pronunciation": "cǎi mì", "ipa": "tsʰai˨˩˦ mi˥˩", "syllable_count": 2, "sentences": [{"text": "小蜜蜂在花上采蜜。", "target_word": "采蜜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "花园里有很多蜜蜂在采蜜。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气好，蜜蜂都出来采蜜。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂喜欢去红色的花里采蜜。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看，那只蜜蜂正在采蜜。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂采蜜很辛苦，每天要飞很远。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天花多，蜜蜂有很多地方可以采蜜。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上天黑了，蜜蜂就不去采蜜了。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜜蜂采蜜是为了做蜂蜜。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们站在花旁，看蜜蜂采蜜。", "target_word": "采蜜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "采蜜了", "label": "体标（了）"}, {"form": "采蜜过", "label": "体标（过）"}, {"form": "採蜜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "蜜蜂到花里找甜汁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '703d6979-3962-4484-92d2-882f13f16783') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喂", "is_correct": false, "explanation": "配价：「喂」需要带被喂对象的宾语，「小蜜蜂在花上喂」缺少宾语。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：「修剪」指修整花枝，与蜜蜂找花里甜汁的语境不符。"}, {"text": "挖", "is_correct": false, "explanation": "搭配：「挖」用于挖掘土、洞等，不说在花上挖。"}, {"text": "采蜜", "is_correct": true, "explanation": "正确：「采蜜」指蜜蜂到花里找甜汁，与「在花上」相符。"}], "explanations": {"喂": "配价：「喂」需要带被喂对象的宾语，「小蜜蜂在花上喂」缺少宾语。", "修剪": "语义：「修剪」指修整花枝，与蜜蜂找花里甜汁的语境不符。", "挖": "搭配：「挖」用于挖掘土、洞等，不说在花上挖。", "采蜜": "正确：「采蜜」指蜜蜂到花里找甜汁，与「在花上」相符。"}, "sentence_index": 0, "correct_answer": "采蜜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蜜蜂整天待在蜂巢里采蜜，不去花上。", "explanation": "这里应该用〈酿蜜〉。采蜜要到花上去找甜汁，在蜂巢里加工花蜜要说〈酿蜜〉。"}, {"text": "蜜蜂在水坑边采蜜，只是为了喝水。", "explanation": "这里应该用〈喝水〉。采蜜要到花里找甜汁，水坑边没有花，蜜蜂只是去找水。"}, {"text": "蜜蜂在沙子上采蜜。", "explanation": "这里不该用采蜜。沙子上没有花，也没有甜汁，蜜蜂不能在那里采蜜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缝", "is_correct": false, "explanation": "语义：「缝」指用针线缝合，与蜜蜂活动的地方不相关。"}, {"text": "扔", "is_correct": false, "explanation": "配价：「扔」需要带被扔的对象，「可以扔」缺少宾语。"}, {"text": "洗", "is_correct": false, "explanation": "语义：「洗」指清洗，与蜜蜂在花间找甜汁的语境不符。"}, {"text": "采蜜", "is_correct": true, "explanation": "正确：「可以采蜜」说明蜜蜂能在许多地方找花蜜，与「花多」相符。"}], "explanations": {"缝": "语义：「缝」指用针线缝合，与蜜蜂活动的地方不相关。", "扔": "配价：「扔」需要带被扔的对象，「可以扔」缺少宾语。", "洗": "语义：「洗」指清洗，与蜜蜂在花间找甜汁的语境不符。", "采蜜": "正确：「可以采蜜」说明蜜蜂能在许多地方找花蜜，与「花多」相符。"}, "sentence_index": 6, "correct_answer": "采蜜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蜜蜂在石板上采蜜，很快就飞走了。", "explanation": "这里不该用采蜜。石板上没有花，蜜蜂找不到甜汁，应说〈找〉。"}, {"text": "蜜蜂整天在河里采蜜。", "explanation": "这里应该用〈取水〉。采蜜指蜜蜂找花里的甜汁，蜜蜂到河边取水要说〈取水〉。"}, {"text": "蜜蜂每天在窗台上采蜜，窗台上一朵花也没有。", "explanation": "这里不该用采蜜。窗台上没有花，蜜蜂找不到甜汁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "快看，这只小蜜蜂正在花里采蜜了。", "corrected_sentence": "快看，这只小蜜蜂正在花里采蜜。", "error_description": "体标错误：「正在」表示动作在进行中，不能再加表示完成的「了」，应说「正在花里采蜜」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蜜蜂下周就去采蜜过。", "corrected_sentence": "蜜蜂下周就去采蜜。", "error_description": "体标错误：「过」表示已经发生过的经历，不能与将来的「下周」搭配，应说「下周就去采蜜」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '500d3285-fe4e-4f39-81a9-59a8a9272a13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
