INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27032, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "扮作或充当某种角色，承担某个身份的职责或作用。", "primary_collocate": null, "pronunciation": "bàn yǎn zhe", "ipa": "pan˥˩ jɛn˨˩ ʈʂɤ", "syllable_count": 3, "sentences": [{"text": "妈妈在家里扮演着很重要的角色。", "target_word": "扮演着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这部电影里扮演着一位老师。", "target_word": "扮演着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在这个故事里扮演着一位母亲。", "target_word": "扮演着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在班里扮演着班长的角色。", "target_word": "扮演着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司里扮演着经理的角色。", "target_word": "扮演着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在这个家里扮演着保护者的角色。", "target_word": "扮演着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在小组里扮演着翻译的角色。", "target_word": "扮演着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在这次活动中扮演着主持人的角色。", "target_word": "扮演着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在学生的成长中扮演着重要的角色。", "target_word": "扮演着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在朋友中一直扮演着听众的角色。", "target_word": "扮演着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扮演", "label": "原形"}, {"form": "扮演过", "label": "体标"}], "register": "中性", "sense_fingerprint": "扮演着：某人正承担某个角色、工作或任务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f82c8ae-82ab-4595-b449-235c22ee33c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27032, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扮演着", "is_correct": true, "explanation": "正确：“扮演着”表示妈妈正承担“很重要的角色”，与句意相符。"}, {"text": "玩耍着", "is_correct": false, "explanation": "搭配：“玩耍”指游戏嬉戏，不能与“很重要的角色”搭配。"}, {"text": "修理着", "is_correct": false, "explanation": "语义：“修理”的对象是器物，与“角色”这种抽象身份无关。"}, {"text": "种植着", "is_correct": false, "explanation": "语义：“种植”的对象是植物，不能用于“角色”。"}], "explanations": {"扮演着": "正确：“扮演着”表示妈妈正承担“很重要的角色”，与句意相符。", "玩耍着": "搭配：“玩耍”指游戏嬉戏，不能与“很重要的角色”搭配。", "修理着": "语义：“修理”的对象是器物，与“角色”这种抽象身份无关。", "种植着": "语义：“种植”的对象是植物，不能用于“角色”。"}, "sentence_index": 0, "correct_answer": "扮演着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中扮演着第一名。", "explanation": "这里应该用〈获得〉。扮演的宾语是角色，“第一名”是比赛结果，要说获得第一名。"}, {"text": "他扮演着照顾父母的责任。", "explanation": "这里应该用〈承担〉。扮演的宾语是角色，“责任”要用承担。"}, {"text": "他们在晚会上扮演着精彩的节目。", "explanation": "这里应该用〈表演〉。扮演的对象是人物角色，“节目”要用表演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27032, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扮演着", "is_correct": true, "explanation": "正确：“扮演着”表示“我”正承担“翻译的角色”，与句意相符。"}, {"text": "驾驶着", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆，不能与“翻译的角色”搭配。"}, {"text": "烹饪着", "is_correct": false, "explanation": "语义：“烹饪”针对食物，与“翻译的角色”无关。"}, {"text": "缝补着", "is_correct": false, "explanation": "搭配：“缝补”针对衣物，不能带“角色”作宾语。"}], "explanations": {"扮演着": "正确：“扮演着”表示“我”正承担“翻译的角色”，与句意相符。", "驾驶着": "搭配：“驾驶”的对象是车辆，不能与“翻译的角色”搭配。", "烹饪着": "语义：“烹饪”针对食物，与“翻译的角色”无关。", "缝补着": "搭配：“缝补”针对衣物，不能带“角色”作宾语。"}, "sentence_index": 6, "correct_answer": "扮演着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他积极扮演着学校的活动。", "explanation": "这里应该用〈参与〉。扮演的宾语是角色，参加活动要用参与。"}, {"text": "她的脸上扮演着一种高兴的心情。", "explanation": "这里应该用〈表露〉。扮演的宾语是角色，“心情”要用表露。"}, {"text": "他在音乐会上扮演着钢琴曲。", "explanation": "这里应该用〈演奏〉。扮演的对象是人物角色，乐曲要用演奏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在话剧里扮演着一只警察。", "corrected_sentence": "他在话剧里扮演着一个警察。", "error_description": "量词错误：“警察”指人，量词应用“个”或“位”，“只”用于动物等，不能用于人。错误形式为“一只警察”，正确形式为“一个警察”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在电影里扮演了着一个角色。", "corrected_sentence": "她在电影里扮演着一个角色。", "error_description": "体标错误：“了”与“着”不能同时用在同一动词后，“扮演了着”应去掉“了”，写作“扮演着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '509b35c6-840c-42b7-b052-f857cb5ec106') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
