INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27034, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "花蜜是花里甜甜的水，小蜜蜂会用它做蜂蜜。", "primary_collocate": null, "pronunciation": "huā mì", "ipa": "xua˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "小蜜蜂飞到花里找花蜜。", "target_word": "花蜜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "花蜜是甜的，小蜜蜂最爱喝。", "target_word": "花蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，蜂蜜是用花蜜做的。", "target_word": "花蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我看见一只蝴蝶在喝花蜜。", "target_word": "花蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这朵红花里有很多花蜜。", "target_word": "花蜜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小蜜蜂把花蜜带回了家。", "target_word": "花蜜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂采了一天，带回来一点花蜜。", "target_word": "花蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们看了蜜蜂吸花蜜的视频。", "target_word": "花蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花蜜甜甜的，闻起来很香。", "target_word": "花蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有花，就没有花蜜，蜜蜂也没有吃的。", "target_word": "花蜜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "滴", "label": "量词"}, {"form": "点", "label": "量词"}], "register": "中性", "sense_fingerprint": "花蜜：花里甜甜的水，蜜蜂用来做蜂蜜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '020655ba-9334-42e1-8d99-bb5d113bb481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27034, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面包", "is_correct": false, "explanation": "语义：小蜜蜂吃的是花里的甜液，花里不会有面包可找。"}, {"text": "花蜜", "is_correct": true, "explanation": "正确：花蜜是花里甜甜的水，是小蜜蜂要找的东西。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是一个日子，不是花里能找到的东西，与语境不符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是小蜜蜂会在花里找的东西，与语境不符。"}], "explanations": {"面包": "语义：小蜜蜂吃的是花里的甜液，花里不会有面包可找。", "花蜜": "正确：花蜜是花里甜甜的水，是小蜜蜂要找的东西。", "生日": "语义：“生日”是一个日子，不是花里能找到的东西，与语境不符。", "手机": "语义：手机不是小蜜蜂会在花里找的东西，与语境不符。"}, "sentence_index": 0, "correct_answer": "花蜜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头上长满了花蜜。", "explanation": "这里应该用〈青苔〉。花蜜是液体，不能长满石头，长满石头的是青苔。"}, {"text": "院子里弥漫着淡淡的花蜜。", "explanation": "这里应该用〈花香〉。花蜜是液体，不会弥漫在空气中，弥漫的是花香。"}, {"text": "这片山坡上，花蜜一片片盛开。", "explanation": "这里应该用〈花朵〉。盛开的是花朵，花蜜是液体，不能说盛开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27034, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：蜜蜂不会带回石头，与“采了一天”的语境不符。"}, {"text": "花蜜", "is_correct": true, "explanation": "正确：蜜蜂采了一天带回来的是花里的甜液。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：蜜蜂采集的是花里的甜液，不会把整朵花带回来。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：蜜蜂采集的是花蜜，不是树叶，与语境不符。"}], "explanations": {"石头": "语义：蜜蜂不会带回石头，与“采了一天”的语境不符。", "花蜜": "正确：蜜蜂采了一天带回来的是花里的甜液。", "花朵": "语义：蜜蜂采集的是花里的甜液，不会把整朵花带回来。", "树叶": "语义：蜜蜂采集的是花蜜，不是树叶，与语境不符。"}, "sentence_index": 6, "correct_answer": "花蜜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花蜜还没开，过几天才会绽放。", "explanation": "这里应该用〈花蕾〉。花蜜是液体，不会开放或绽放，尚未开放的是花蕾。"}, {"text": "花蜜里种满了月季。", "explanation": "这里应该用〈花坛〉。花蜜是液体，不能种植，种满植物的是花坛。"}, {"text": "花蜜要在春天播下。", "explanation": "这里应该用〈花种〉。花蜜是甜液，不能播种，播在地里的是花种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小蜜蜂在花里找到了一只花蜜。", "corrected_sentence": "小蜜蜂在花里找到了一滴花蜜。", "error_description": "错误：量词“只”不能修饰液体“花蜜”。正确说法是“一滴花蜜”，“滴”是液体的量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小蜜蜂喝了一本花蜜。", "corrected_sentence": "小蜜蜂喝了一点花蜜。", "error_description": "量词错误：“本”是书的量词，不能修饰液体“花蜜”。应说“一点花蜜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
