INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27036, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蜜蜂做的甜甜的东西，可以吃。", "primary_collocate": null, "pronunciation": "fēng mì", "ipa": "fɤŋ˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "蜂蜜很甜，小朋友都爱吃。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想在面包上涂一点蜂蜜。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈买了一瓶蜂蜜。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜂蜜是金黄色的，看起来很漂亮。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的茶里放了一勺蜂蜜。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种蜂蜜是蜜蜂做的，可以直接吃。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥不喜欢吃糖，但是喜欢蜂蜜。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里有很多不同的蜂蜜。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜂蜜太甜了，我只吃了一点。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带我们去农场看怎么取蜂蜜。", "target_word": "蜂蜜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一勺蜂蜜", "label": "量词"}, {"form": "蜂蜜水", "label": "复合"}], "register": "中性", "sense_fingerprint": "蜜蜂做的、可以吃的甜东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d653fec-04d6-4c8b-893f-33391eee6ee0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27036, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蜂蜜", "is_correct": true, "explanation": "正确答案：蜂蜜（fēng mì），蜜蜂做的、可以吃的甜东西。"}, {"text": "分泌", "is_correct": false, "explanation": "fēn 与 fēng 韵尾不同（n 与 ng），分泌（fēn mì）意思是生物体排出某种物质。"}, {"text": "锋利", "is_correct": false, "explanation": "mì 与 lì 声母不同（m 与 l），锋利（fēng lì）意思是刀刃等很薄很快。"}, {"text": "风气", "is_correct": false, "explanation": "mì 与 qì 声母不同（m 与 q），风气（fēng qì）意思是社会或集体的习惯和作风。"}, {"text": "风靡", "is_correct": false, "explanation": "mǐ（第三声）与 mì（第四声）声调不同，风靡（fēng mǐ）意思是广泛流行。"}], "explanations": {"蜂蜜": "正确答案：蜂蜜（fēng mì），蜜蜂做的、可以吃的甜东西。", "分泌": "fēn 与 fēng 韵尾不同（n 与 ng），分泌（fēn mì）意思是生物体排出某种物质。", "锋利": "mì 与 lì 声母不同（m 与 l），锋利（fēng lì）意思是刀刃等很薄很快。", "风气": "mì 与 qì 声母不同（m 与 q），风气（fēng qì）意思是社会或集体的习惯和作风。", "风靡": "mǐ（第三声）与 mì（第四声）声调不同，风靡（fēng mǐ）意思是广泛流行。"}, "sentence_index": null, "correct_answer": "蜂蜜"}, "level_3": {"options": [{"text": "蜂蜜", "is_correct": true, "explanation": "正确：句中“蜂蜜”是甜的食物，所以“很甜，小朋友都爱吃”。"}, {"text": "醋", "is_correct": false, "explanation": "语义：醋是酸的，不会很甜，与“很甜”矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：石头不能吃，“小朋友都爱吃”的对象应是食物。"}, {"text": "柠檬", "is_correct": false, "explanation": "语义：柠檬是酸的，说它很甜不合事实。"}], "explanations": {"蜂蜜": "正确：句中“蜂蜜”是甜的食物，所以“很甜，小朋友都爱吃”。", "醋": "语义：醋是酸的，不会很甜，与“很甜”矛盾。", "石头": "搭配：石头不能吃，“小朋友都爱吃”的对象应是食物。", "柠檬": "语义：柠檬是酸的，说它很甜不合事实。"}, "sentence_index": 0, "correct_answer": "蜂蜜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子里的蜂蜜在花丛中嗡嗡地飞。", "explanation": "这里应该用〈蜜蜂〉。“嗡嗡地飞”的是昆虫，蜂蜜是液体食物，不会飞。"}, {"text": "下雨了，我穿上蜂蜜出门。", "explanation": "这里应该用〈雨衣〉。蜂蜜是甜的食物，不能穿；下雨出门要穿雨衣。"}, {"text": "我每天早上用蜂蜜刷牙，牙齿很白。", "explanation": "这里应该用〈牙膏〉。蜂蜜是甜的食物，不能用来刷牙；刷牙要用牙膏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜂蜜", "is_correct": true, "explanation": "正确：句中“蜂蜜”是甜的食物，与“吃糖”形成对比，哥哥喜欢的是蜂蜜。"}, {"text": "肥皂", "is_correct": false, "explanation": "搭配：肥皂不能吃，与上句“吃糖”的语境不符。"}, {"text": "煤油", "is_correct": false, "explanation": "搭配：煤油不能吃，与上句“吃糖”的语境不符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以吃的东西，句子说的是喜欢吃的食物，这样说不合理。"}], "explanations": {"蜂蜜": "正确：句中“蜂蜜”是甜的食物，与“吃糖”形成对比，哥哥喜欢的是蜂蜜。", "肥皂": "搭配：肥皂不能吃，与上句“吃糖”的语境不符。", "煤油": "搭配：煤油不能吃，与上句“吃糖”的语境不符。", "空气": "语义：空气不是可以吃的东西，句子说的是喜欢吃的食物，这样说不合理。"}, "sentence_index": 6, "correct_answer": "蜂蜜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师说，蜂蜜是做蜡烛的好材料。", "explanation": "这里应该用〈蜂蜡〉。做蜡烛要用蜂蜡，蜂蜜是甜的食物，不能做蜡烛。"}, {"text": "妈妈用蜂蜜炸了一盘鸡块。", "explanation": "这里应该用〈油〉。炸东西要用油，蜂蜜受热容易焦，不能用来炸。"}, {"text": "他用蜂蜜给自行车打气，车胎很快就鼓了。", "explanation": "这里应该用〈打气筒〉。蜂蜜是食物，给车胎打气要用打气筒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我早上在热水里加了一只蜂蜜。", "corrected_sentence": "我早上在热水里加了一勺蜂蜜。", "error_description": "量词错误：蜂蜜是液体，应用“勺”“瓶”等计量；“只”不用于蜂蜜这类食物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶喜欢吃很稠蜂蜜。", "corrected_sentence": "奶奶喜欢吃很稠的蜂蜜。", "error_description": "结构错误：“很稠”修饰“蜂蜜”，中间要加“的”，不能直接说“很稠蜂蜜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
