INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27040, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27040, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西拿回来，比如去山上摘花或收果子。", "primary_collocate": null, "pronunciation": "cǎi jí", "ipa": "tsʰai˨˩˦ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "奶奶每年秋天上山采集野果。", "target_word": "采集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在山坡上采集野花。", "target_word": "采集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们去树林里采集松果吧。", "target_word": "采集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在山上采集了很多野草莓。", "target_word": "采集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天，妈妈带我去田野采集野菜。", "target_word": "采集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把采集来的花放进了瓶子里。", "target_word": "采集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时在森林里采集过蘑菇。", "target_word": "采集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一边走，一边采集着路边的野花。", "target_word": "采集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的人靠采集野果和蘑菇过日子。", "target_word": "采集", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人背着篮子，到山上采集山楂。", "target_word": "采集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "采集了", "label": "完成体"}, {"form": "采集过", "label": "经历体"}, {"form": "采集着", "label": "进行体"}], "register": "中性", "sense_fingerprint": "采集：到野外摘取花、果等带回来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T3: contains vocabulary far above tier T3: 楂 (Zipf 1.94)']::text[], '020655ba-9334-42e1-8d99-bb5d113bb481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做菜，与“上山”采摘野果的语境不符。"}, {"text": "采集", "is_correct": true, "explanation": "正确：“采集”指到野外采摘、收取野生果实，与“上山”“野果”相符。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”用于人工栽培，野果不能说种植。"}, {"text": "摆放", "is_correct": false, "explanation": "搭配：“摆放”指陈列、放置，不能用来表示从山上获取野果。"}], "explanations": {"烹饪": "语义：“烹饪”指做菜，与“上山”采摘野果的语境不符。", "采集": "正确：“采集”指到野外采摘、收取野生果实，与“上山”“野果”相符。", "种植": "搭配：“种植”用于人工栽培，野果不能说种植。", "摆放": "搭配：“摆放”指陈列、放置，不能用来表示从山上获取野果。"}, "sentence_index": 0, "correct_answer": "采集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我从小就喜欢采集邮票。", "explanation": "这里应该用〈收集〉。采集指到野外摘取动植物，邮票要用收集。"}, {"text": "妈妈去超市采集了很多蔬菜。", "explanation": "这里应该用〈采购〉。采集指到野外取材，去超市买东西要用采购。"}, {"text": "我把桌上的书采集起来了。", "explanation": "这里应该用〈收拾〉。采集指到野外取材，整理桌上的书要用收拾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆等，不能与“蘑菇”搭配。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对损坏的器物，蘑菇不能被修理。"}, {"text": "采集", "is_correct": true, "explanation": "正确：“采集”指在野外采来蘑菇，与“森林里”“蘑菇”及“过”的经历语境相符。"}, {"text": "吸收", "is_correct": false, "explanation": "语义：“吸收”指吸入或接受，与在森林里采来蘑菇的语境不符。"}], "explanations": {"驾驶": "搭配：“驾驶”的对象是车辆等，不能与“蘑菇”搭配。", "修理": "搭配：“修理”针对损坏的器物，蘑菇不能被修理。", "采集": "正确：“采集”指在野外采来蘑菇，与“森林里”“蘑菇”及“过”的经历语境相符。", "吸收": "语义：“吸收”指吸入或接受，与在森林里采来蘑菇的语境不符。"}, "sentence_index": 6, "correct_answer": "采集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在花园里采集了一排新的路灯。", "explanation": "这里应该用〈安装〉。采集指到野外取材，给花园装路灯要用安装。"}, {"text": "我在网上采集了一台电脑。", "explanation": "这里应该用〈购买〉。采集指到野外取材，在网上买东西要用购买。"}, {"text": "卡车把货物采集到仓库里。", "explanation": "这里应该用〈运送〉。采集指到野外取材，把货物送到仓库要用运送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈正在山坡上采集了野菜。", "corrected_sentence": "妈妈正在山坡上采集野菜。", "error_description": "错误：“正在”表示动作进行中，后面的“采集”不能再加“了”。正确说法是“正在采集野菜”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没采集过蘑菇过。", "corrected_sentence": "他从来没采集过蘑菇。", "error_description": "错误：“过”只能出现一次，且紧跟动词“采集”。句末多出的“过”是错误的，应去掉，即“他从来没采集过蘑菇”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
