INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27042, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27042, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "猜一猜大概的数量或样子，不用很准。", "primary_collocate": null, "pronunciation": "gū jì", "ipa": "ku˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "你估计一下这棵树有多高。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我估计他大概三十岁。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我估计这家店里有二十个客人。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了看桌子，估计有一米长。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈估计一下，要买多少斤肉才够我们八个人吃。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你估计一下，要买几瓶水。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我估计这条鱼有两公斤重。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上车多，我估计要走一个小时。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你估计这本书多少钱？", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她估计房间里有十几个人。", "target_word": "估计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "估计了", "label": "体标"}, {"form": "估计过", "label": "体标"}], "register": "中性", "sense_fingerprint": "估计：随便猜大概的数量或样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d5bd87a-e772-4fff-ab41-ecf10ff578c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27042, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "估计", "is_correct": true, "explanation": "估计（gū jì）是本题要听的词，意思是随便猜一个大概的数量或样子。"}, {"text": "古迹", "is_correct": false, "explanation": "gǔ（第三声）与 gū（第一声）声调不同，意思是古迹（历史遗留下来的地方）。"}, {"text": "古籍", "is_correct": false, "explanation": "gǔ 与 gū、jí 与 jì 的声调都不同，意思是古代的书籍。"}, {"text": "顾忌", "is_correct": false, "explanation": "gù（第四声）与 gū（第一声）声调不同，“顾忌”的意思是有所担心、不敢做。"}], "explanations": {"估计": "估计（gū jì）是本题要听的词，意思是随便猜一个大概的数量或样子。", "古迹": "gǔ（第三声）与 gū（第一声）声调不同，意思是古迹（历史遗留下来的地方）。", "古籍": "gǔ 与 gū、jí 与 jì 的声调都不同，意思是古代的书籍。", "顾忌": "gù（第四声）与 gū（第一声）声调不同，“顾忌”的意思是有所担心、不敢做。"}, "sentence_index": null, "correct_answer": "估计"}, "level_3": {"options": [{"text": "估计", "is_correct": true, "explanation": "估计：凭印象随便猜一个大概的数字，与“看一看树有多高”的语境相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是赞赏的意思，不能用来询问树的高度。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示谢意，与询问树的高度无关。"}, {"text": "吹牛", "is_correct": false, "explanation": "语域：“吹牛”是口语且带贬义，不适合请别人估测高度。"}], "explanations": {"估计": "估计：凭印象随便猜一个大概的数字，与“看一看树有多高”的语境相符。", "欣赏": "语义：“欣赏”是赞赏的意思，不能用来询问树的高度。", "感谢": "语义：“感谢”表示谢意，与询问树的高度无关。", "吹牛": "语域：“吹牛”是口语且带贬义，不适合请别人估测高度。"}, "sentence_index": 0, "correct_answer": "估计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子我量过了，我估计它正好是一米二。", "explanation": "这里应该用〈量出〉。桌子已经量过，尺寸是确定的；估计只是随便猜一个大概的数字，不能用来说已经测得的准确尺寸。"}, {"text": "这个零件的长度，他估计得精确到毫米。", "explanation": "这里应该用〈测得〉。估计只是随便猜个大概，不能要求精确到毫米。"}, {"text": "这笔账要一笔一笔地估计，不能出一点错。", "explanation": "这里应该用〈计算〉。估计只是大致判断，账目要一笔一笔计算，不能用估计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "估计", "is_correct": true, "explanation": "估计：凭印象猜测鱼的大概重量，与语境相符。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”需要值得庆贺的事，鱼的重量不构成庆祝的理由。"}, {"text": "鄙视", "is_correct": false, "explanation": "语义：“鄙视”表示看不起，与描述鱼的重量无关。"}, {"text": "叹息", "is_correct": false, "explanation": "语义：“叹息”是因感慨而叹气，不能带“这条鱼有两公斤重”这样的判断作宾语。"}], "explanations": {"估计": "估计：凭印象猜测鱼的大概重量，与语境相符。", "庆祝": "语义：“庆祝”需要值得庆贺的事，鱼的重量不构成庆祝的理由。", "鄙视": "语义：“鄙视”表示看不起，与描述鱼的重量无关。", "叹息": "语义：“叹息”是因感慨而叹气，不能带“这条鱼有两公斤重”这样的判断作宾语。"}, "sentence_index": 6, "correct_answer": "估计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师估计了我们的名字，全班都在。", "explanation": "这里应该用〈核实〉。名字是确定的，要一一确认，不能随便猜。"}, {"text": "我一眼就估计了墙上的钟，是八点。", "explanation": "这里应该用〈看见〉。估计是猜测大概的数量或样子，不能用来表示直接看到钟上的准确时间。"}, {"text": "我估计了敲门声，然后打开了门。", "explanation": "这里应该用〈听见〉。估计不能用来表示听到声音，听到要说“听见”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我估计得这个西瓜有三公斤重。", "corrected_sentence": "我估计这个西瓜有三公斤重。", "error_description": "错误：“估计”后接小句作宾语时不能加“得”（“估计得很准”的“得”引出补语，与此不同）；“我估计得这个西瓜有三公斤重”不成句，应说“我估计这个西瓜有三公斤重”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你很估计一下这个包多少钱？", "corrected_sentence": "你估计一下这个包多少钱？", "error_description": "错误在于“很”的位置：“很”是程度副词，不能放在动词“估计”前面，多余的“很”使句子不通；正确说法是“你估计一下这个包多少钱？”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
