INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27046, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蓝莓是一种小小的、蓝色的水果，可以吃。", "primary_collocate": null, "pronunciation": "lán méi", "ipa": "lan˧˥ mei˧˥", "syllable_count": 2, "sentences": [{"text": "桌子上有一碗蓝莓，是刚洗好的。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种蓝莓的皮是蓝色的。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最爱吃的水果是蓝莓。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把蓝莓放进杯子里做果汁。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的蓝莓比苹果小得多。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了两盒蓝莓带去朋友家。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蓝莓吃起来有点酸，也有点甜。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里还有一些冰凉的蓝莓。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想吃蓝莓还是吃葡萄？", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园旁边的小店卖新鲜蓝莓。", "target_word": "蓝莓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一颗蓝莓", "label": "量词"}, {"form": "一盒蓝莓", "label": "量词"}, {"form": "蓝莓汁", "label": "复合"}, {"form": "藍莓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "蓝莓：小小的蓝色水果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d5bd87a-e772-4fff-ab41-ecf10ff578c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27046, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蓝莓", "is_correct": true, "explanation": "正确：“桌子上有一碗蓝莓”，蓝莓是可以盛在碗里的水果。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“碗”通常盛食物或液体，不能说“一碗钥匙”。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不是可以盛在碗里的东西，句子不通。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套不是用碗盛放的东西，句子不通。"}], "explanations": {"蓝莓": "正确：“桌子上有一碗蓝莓”，蓝莓是可以盛在碗里的水果。", "钥匙": "搭配：“碗”通常盛食物或液体，不能说“一碗钥匙”。", "书": "语义：书不是可以盛在碗里的东西，句子不通。", "手套": "语义：手套不是用碗盛放的东西，句子不通。"}, "sentence_index": 0, "correct_answer": "蓝莓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在市场买了一头蓝莓。", "explanation": "这里应该用〈颗〉或〈盒〉。〈头〉用于大型牲畜，不能用来数蓝莓。"}, {"text": "她摘了一条蓝莓。", "explanation": "这里应该用〈颗〉。〈条〉用于细长的东西，蓝莓不能用〈条〉来数。"}, {"text": "厨房的桌上放着一座蓝莓。", "explanation": "这里应该用〈碗〉或〈盒〉。〈座〉用于山峰、建筑等大型物体，不能用来数蓝莓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27046, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蓝莓", "is_correct": true, "explanation": "正确：“蓝莓吃起来有点酸，也有点甜”，描述蓝莓的味道。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能吃，“吃起来有点酸甜”无法成立。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能吃，句子描述的味道无从谈起。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“吃”不能搭配“空气”，空气没有酸甜的味道。"}], "explanations": {"蓝莓": "正确：“蓝莓吃起来有点酸，也有点甜”，描述蓝莓的味道。", "石头": "语义：石头不能吃，“吃起来有点酸甜”无法成立。", "手机": "语义：手机不能吃，句子描述的味道无从谈起。", "空气": "搭配：“吃”不能搭配“空气”，空气没有酸甜的味道。"}, "sentence_index": 6, "correct_answer": "蓝莓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我吃了一张蓝莓。", "explanation": "这里应该用〈颗〉。〈张〉用于纸张、桌子等扁平物品，不能用来数蓝莓。"}, {"text": "她买了一根蓝莓带回家。", "explanation": "这里应该用〈盒〉或〈颗〉。〈根〉用于细长的东西，不能用来数蓝莓。"}, {"text": "篮子里放着一本蓝莓。", "explanation": "这里应该用〈颗〉。〈本〉用于书籍，不能用来数蓝莓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冰箱里还有一条蓝莓。", "corrected_sentence": "冰箱里还有一盒蓝莓。", "error_description": "错误在量词：蓝莓应配〈盒〉，“一条”用于细长的东西，不能用来数蓝莓。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈买了很多蓝莓们回家。", "corrected_sentence": "妈妈买了很多蓝莓回家。", "error_description": "错误在词尾：“们”不能加在“蓝莓”后，蓝莓是事物，应为“很多蓝莓”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27050, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下跌", "is_correct": true, "explanation": "下跌与上涨是反义词，指价格、水位等由高到低地变化。"}, {"text": "学习", "is_correct": false, "explanation": "学习指获得知识或技能，与上涨没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行指到外地去游览，与上涨没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "修理指把坏的东西弄好，与上涨没有反义关系。"}], "correct_answer": "下跌", "explanations": {"下跌": "下跌与上涨是反义词，指价格、水位等由高到低地变化。", "学习": "学习指获得知识或技能，与上涨没有反义关系。", "旅行": "旅行指到外地去游览，与上涨没有反义关系。", "修理": "修理指把坏的东西弄好，与上涨没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27050, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下跌", "is_correct": true, "explanation": "下跌与上涨是反义词，指价格、水位等由高到低地变化。"}, {"text": "批准", "is_correct": false, "explanation": "批准指同意或认可，与上涨没有反义关系。"}, {"text": "参观", "is_correct": false, "explanation": "参观指到某处去看，与上涨没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论指大家一起交换意见，与上涨没有反义关系。"}], "correct_answer": "下跌", "explanations": {"下跌": "下跌与上涨是反义词，指价格、水位等由高到低地变化。", "批准": "批准指同意或认可，与上涨没有反义关系。", "参观": "参观指到某处去看，与上涨没有反义关系。", "讨论": "讨论指大家一起交换意见，与上涨没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27050, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西的价格或水位变高了。", "primary_collocate": null, "pronunciation": "shàng zhǎng", "ipa": "ʂɑŋ˥˩ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "上个月，鸡蛋的价格上涨了。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河里的水上涨得很快。", "target_word": "上涨", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "暑假到了，机票价格开始上涨。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，湖水上涨了很多。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "米的价格每个月都在上涨。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水果的价格为什么上涨了？", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春节前，很多东西的价格都会上涨。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "最近天天下雨，河水上涨，路上有水。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油价上涨以后，开车的人少了。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，今年大米的价格不会上涨太多。", "target_word": "上涨", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "上涨了", "label": "完成体"}, {"form": "上涨过", "label": "经历体"}, {"form": "上漲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物价或水位变高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d5bd87a-e772-4fff-ab41-ecf10ff578c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27050, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上涨", "is_correct": true, "explanation": "上涨：鸡蛋的价格升高，与“上个月”的语境相符。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体的反应，不能用来描述鸡蛋的价格。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是在水中的动作，与价格无关。"}, {"text": "吹牛", "is_correct": false, "explanation": "语义：“吹牛”指人说大话，不能用来描述鸡蛋的价格。"}], "explanations": {"上涨": "上涨：鸡蛋的价格升高，与“上个月”的语境相符。", "咳嗽": "语义：“咳嗽”是身体的反应，不能用来描述鸡蛋的价格。", "游泳": "语义：“游泳”是在水中的动作，与价格无关。", "吹牛": "语义：“吹牛”指人说大话，不能用来描述鸡蛋的价格。"}, "sentence_index": 0, "correct_answer": "上涨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班里的学生上涨了很多，老师很高兴。", "explanation": "这里应该用〈增加〉。上涨用于价格、水位，学生人数变多要说“增加”。"}, {"text": "这个公园的面积上涨了很多，大家都很喜欢。", "explanation": "这里应该用〈扩大〉。上涨不能用于面积，面积变大要说“扩大”。"}, {"text": "他的技术上涨了很多，现在是公司里最好的。", "explanation": "这里应该用〈提高〉。上涨不能用于技术，技术进步要说“提高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27050, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上涨", "is_correct": true, "explanation": "上涨：春节前价格升高，与“很多东西的价格都会”的语境相符。"}, {"text": "放假", "is_correct": false, "explanation": "语义：“放假”指学校或单位停止工作，价格不能放假。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”针对人或动植物，价格不会生病。"}, {"text": "排队", "is_correct": false, "explanation": "搭配：“排队”的主语是人或车，不能用在“价格”上。"}], "explanations": {"上涨": "上涨：春节前价格升高，与“很多东西的价格都会”的语境相符。", "放假": "语义：“放假”指学校或单位停止工作，价格不能放假。", "生病": "语义：“生病”针对人或动植物，价格不会生病。", "排队": "搭配：“排队”的主语是人或车，不能用在“价格”上。"}, "sentence_index": 6, "correct_answer": "上涨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的错误上涨了很多，老师很失望。", "explanation": "这里应该用〈增多〉。上涨只用于价格或水位，错误变多要说“增多”，不能用“上涨”。"}, {"text": "这座桥上涨了一百米，方便了附近的居民。", "explanation": "这里应该用〈延长〉。桥的长度变长要说“延长”，不能用“上涨”。"}, {"text": "这根绳子上涨了两厘米，现在变长了。", "explanation": "这里应该用〈拉长〉。上涨只用于价格或水位，绳子变长要说“拉长”，不能用“上涨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年，房子的价格上涨了很快。", "corrected_sentence": "这几年，房子的价格上涨得很快。", "error_description": "错误：“上涨”后应用补语标记“得”引出“很快”，不能用“了”。正确说法是“这几年，房子的价格上涨得很快。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种菜的价格上涨了到十块钱。", "corrected_sentence": "这种菜的价格上涨到了十块钱。", "error_description": "错误：“到”是“上涨”的补语，应紧跟“上涨”，“了”放在“到”后面。正确说法是“这种菜的价格上涨到了十块钱。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
