INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27052, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "发现", "is_correct": false, "explanation": "无关：“发现”指察觉到，与“失去”不构成反义。"}, {"text": "获得", "is_correct": true, "explanation": "反义：与“失去”相对，表示得到原本没有的东西，符合“不要失去学习的兴趣”的语境。"}, {"text": "完成", "is_correct": false, "explanation": "无关：“完成”指做完，与“失去”不构成反义。"}, {"text": "思念", "is_correct": false, "explanation": "无关：“思念”指想念，与“失去”不构成反义。"}], "correct_answer": "获得", "explanations": {"发现": "无关：“发现”指察觉到，与“失去”不构成反义。", "获得": "反义：与“失去”相对，表示得到原本没有的东西，符合“不要失去学习的兴趣”的语境。", "完成": "无关：“完成”指做完，与“失去”不构成反义。", "思念": "无关：“思念”指想念，与“失去”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27052, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "失去就是原来有的东西不再拥有。", "primary_collocate": null, "pronunciation": "shī qù", "ipa": "ʂɨ˥ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "他失去了工作，心里很难过。", "target_word": "失去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人失去了自己的孩子。", "target_word": "失去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想失去这个好朋友。", "target_word": "失去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了事故后，他失去了一条腿。", "target_word": "失去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，球队失去了机会。", "target_word": "失去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能失去信心。", "target_word": "失去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他失去了很多钱，但没有放弃。", "target_word": "失去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机丢了，我失去了所有照片。", "target_word": "失去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病了很久，她失去了力气。", "target_word": "失去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要失去学习的兴趣。", "target_word": "失去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "失去了", "label": "体标"}, {"form": "失去过", "label": "体标"}], "register": "中性", "sense_fingerprint": "原来有的东西不再拥有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc1bb5e-b14c-41de-8ff0-76ccf8bb8da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27052, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赚", "is_correct": false, "explanation": "搭配：“赚”的宾语是钱，不能说“赚工作”。"}, {"text": "失去", "is_correct": true, "explanation": "失去：原有的工作不再拥有，与“心里很难过”相合。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，后面不能带“工作”作宾语。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”接的是房间、场地，不能说“打扫工作”。"}], "explanations": {"赚": "搭配：“赚”的宾语是钱，不能说“赚工作”。", "失去": "失去：原有的工作不再拥有，与“心里很难过”相合。", "睡": "配价：“睡”是不及物动词，后面不能带“工作”作宾语。", "打扫": "搭配：“打扫”接的是房间、场地，不能说“打扫工作”。"}, "sentence_index": 0, "correct_answer": "失去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他失去了一个笑话，大家都笑了。", "explanation": "这里应该用〈讲〉。失去指原本拥有的东西不再拥有，笑话是讲出来的，不能说“失去一个笑话”。"}, {"text": "他失去了一个问题。", "explanation": "这里应该用〈提出〉。失去指原有之物不再拥有，提出问题要说“提出”，不说“失去问题”。"}, {"text": "他失去了这场会议。", "explanation": "这里应该用〈出席〉。会议是去参加的，不能说“失去会议”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27052, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建立", "is_correct": false, "explanation": "搭配：“建立”接关系、制度，不能说“建立了很多钱”。"}, {"text": "失去", "is_correct": true, "explanation": "失去：原有的钱不再拥有，与“没有放弃”的语境相合。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”的对象是场所，钱不能被参观。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”接的是器物，不能说“修理了很多钱”。"}], "explanations": {"建立": "搭配：“建立”接关系、制度，不能说“建立了很多钱”。", "失去": "失去：原有的钱不再拥有，与“没有放弃”的语境相合。", "参观": "语义：“参观”的对象是场所，钱不能被参观。", "修理": "搭配：“修理”接的是器物，不能说“修理了很多钱”。"}, "sentence_index": 6, "correct_answer": "失去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他失去了一个错误。", "explanation": "这里应该用〈犯〉。错误是做出来的，不是拥有的，不能说“失去一个错误”。"}, {"text": "他失去了一声叹息。", "explanation": "这里应该用〈发出〉。叹息是发出的，不能说“失去一声叹息”。"}, {"text": "他失去了一个谎。", "explanation": "这里应该用〈撒〉。谎是说出的，不能说“失去一个谎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他失去着健康，每天都很疲倦。", "corrected_sentence": "他失去了健康，每天都很疲倦。", "error_description": "体标错误：“着”表示持续状态，此处是已经发生的变化，应用“了”，正确为“失去了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他失去掉了很多朋友，心里很难受。", "corrected_sentence": "他失去了很多朋友，心里很难受。", "error_description": "补语错误：“失去”后不能加“掉”，“失去掉”不成立，正确为“失去了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27054, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "清澈", "is_correct": false, "explanation": "不构成反义：“清澈”形容透明，与数量多少无关。"}, {"text": "众多", "is_correct": true, "explanation": "“众多”表示数量很多，与“稀少”在数量上相对。"}, {"text": "辽阔", "is_correct": false, "explanation": "不构成反义：“辽阔”形容地域广大，与数量多少无关。"}, {"text": "贫穷", "is_correct": false, "explanation": "不构成反义：“贫穷”形容经济状况，与数量多少无关。"}], "correct_answer": "众多", "explanations": {"清澈": "不构成反义：“清澈”形容透明，与数量多少无关。", "众多": "“众多”表示数量很多，与“稀少”在数量上相对。", "辽阔": "不构成反义：“辽阔”形容地域广大，与数量多少无关。", "贫穷": "不构成反义：“贫穷”形容经济状况，与数量多少无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27054, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坚硬", "is_correct": false, "explanation": "不构成反义：“坚硬”形容质地，与数量多少无关。"}, {"text": "高大", "is_correct": false, "explanation": "不构成反义：“高大”形容体形或规模，与数量多少无关。"}, {"text": "众多", "is_correct": true, "explanation": "“众多”表示数量很多，与“稀少”在数量上相对。"}, {"text": "明亮", "is_correct": false, "explanation": "不构成反义：“明亮”形容光线，与数量多少无关。"}], "correct_answer": "众多", "explanations": {"坚硬": "不构成反义：“坚硬”形容质地，与数量多少无关。", "高大": "不构成反义：“高大”形容体形或规模，与数量多少无关。", "众多": "“众多”表示数量很多，与“稀少”在数量上相对。", "明亮": "不构成反义：“明亮”形容光线，与数量多少无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27054, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很少，不多。", "primary_collocate": null, "pronunciation": "xī shǎo", "ipa": "ɕi˥ ʂɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这里的树很稀少。", "target_word": "稀少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夏天的时候，这里的游客很稀少。", "target_word": "稀少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草原上的水很稀少。", "target_word": "稀少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种鸟现在非常稀少。", "target_word": "稀少", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山上的房子很稀少，大多在山下。", "target_word": "稀少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "半夜的街上，行人特别稀少。", "target_word": "稀少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小镇的商店很稀少，买东西不太方便。", "target_word": "稀少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些老房子已经变得很稀少了。", "target_word": "稀少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨季以外，这里的雨水很稀少。", "target_word": "稀少", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路上的车辆十分稀少。", "target_word": "稀少", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量很少、不多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d5bd87a-e772-4fff-ab41-ecf10ff578c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27054, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”用于水、眼睛等透明的东西，不说树“很清澈”。"}, {"text": "贫穷", "is_correct": false, "explanation": "语义：“贫穷”说人或地区缺钱，与树的数量状态不相容。"}, {"text": "稀少", "is_correct": true, "explanation": "“稀少”表示这里的树数量少、不多，与语境相符。"}, {"text": "辽阔", "is_correct": false, "explanation": "搭配：“辽阔”形容地域或空间广大，不用来形容树。"}], "explanations": {"清澈": "搭配：“清澈”用于水、眼睛等透明的东西，不说树“很清澈”。", "贫穷": "语义：“贫穷”说人或地区缺钱，与树的数量状态不相容。", "稀少": "“稀少”表示这里的树数量少、不多，与语境相符。", "辽阔": "搭配：“辽阔”形容地域或空间广大，不用来形容树。"}, "sentence_index": 0, "correct_answer": "稀少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的眼睛非常稀少。", "explanation": "这里误用了〈稀少〉的“数量少”义项。眼睛说的是大小、明暗，应该用〈大〉或〈亮〉来描述。"}, {"text": "她的体重非常稀少。", "explanation": "这里误用了〈稀少〉的“数量少”义项。体重是可以称出的分量，应该用〈轻〉或〈沉〉来描述。"}, {"text": "他稀少地吃饭。", "explanation": "这里应该用〈很少〉。“稀少”描述事物的数量，不能直接修饰动作表示次数少，应说“很少吃饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27054, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "齐全", "is_correct": false, "explanation": "语义：“齐全”说种类或数量都够，与“买东西不太方便”矛盾。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容质地，不用来形容商店。"}, {"text": "稀少", "is_correct": true, "explanation": "“稀少”指商店数量少，与“买东西不太方便”相符。"}, {"text": "繁华", "is_correct": false, "explanation": "语义：“繁华”指热闹、商业兴盛，与“买东西不太方便”矛盾。"}], "explanations": {"齐全": "语义：“齐全”说种类或数量都够，与“买东西不太方便”矛盾。", "柔软": "搭配：“柔软”形容质地，不用来形容商店。", "稀少": "“稀少”指商店数量少，与“买东西不太方便”相符。", "繁华": "语义：“繁华”指热闹、商业兴盛，与“买东西不太方便”矛盾。"}, "sentence_index": 6, "correct_answer": "稀少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗粥十分稀少。", "explanation": "这里误用了〈稀少〉的“数量少”义项。粥里水多、不浓要说〈稀〉，如“这碗粥很稀”，不是数量少。"}, {"text": "他的勇气十分稀少。", "explanation": "这里误用了〈稀少〉的“数量少”义项。勇气说的是强弱，应该用〈强〉或〈弱〉来描述。"}, {"text": "这种食物的味道十分稀少。", "explanation": "这里误用了〈稀少〉的“数量少”义项。味道说的是浓淡，应该用〈浓〉或〈淡〉来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27054, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子的人很地稀少。", "corrected_sentence": "这个村子的人很稀少。", "error_description": "错误在于多加了“地”：“很”后面的性质形容词“稀少”不加“地”，应说“很稀少”，不能说“很地稀少”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27054, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个山村的人稀少得。", "corrected_sentence": "这个山村的人稀少得很。", "error_description": "错误在于程度补语：“稀少得”后面要接“很”等程度补语，只说“稀少得”语意不完整。应改为“稀少得很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fca93829-67fb-4877-966a-46fdd516aa95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
