INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27058, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "杏仁是果核里的种子，可以吃。", "primary_collocate": null, "pronunciation": "xìng rén", "ipa": "ɕiŋ˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "这碗粥里有几颗杏仁。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢吃杏仁，又香又脆。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杏仁在杏子的核里面。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶把杏仁放在盘子里，请客人吃。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友不要一次吃太多杏仁。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开杏子的核，里面就是杏仁。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里卖的杏仁很新鲜。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天下午都吃一小把杏仁。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块面包上有杏仁，吃起来很香。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杏仁的味道有点甜，我很爱吃。", "target_word": "杏仁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一颗杏仁", "label": "量词"}, {"form": "甜杏仁", "label": "复合"}], "register": "中性", "sense_fingerprint": "杏仁：杏子核里的种子，能吃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d653fec-04d6-4c8b-893f-33391eee6ee0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27058, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "杏仁", "is_correct": true, "explanation": "杏仁：杏子核里的种子，能吃。"}, {"text": "行人", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，行人指步行的人。"}, {"text": "杏林", "is_correct": false, "explanation": "lín 与 rén 读音不同（声母 l 与 r），杏林（xìng lín）指杏树林，也代指医学界。"}, {"text": "令人", "is_correct": false, "explanation": "l 与 x 声母不同（一个音位），令人（lìng rén）意思是使人感到……"}], "explanations": {"杏仁": "杏仁：杏子核里的种子，能吃。", "行人": "xíng（第二声）与 xìng（第四声）声调不同，行人指步行的人。", "杏林": "lín 与 rén 读音不同（声母 l 与 r），杏林（xìng lín）指杏树林，也代指医学界。", "令人": "l 与 x 声母不同（一个音位），令人（lìng rén）意思是使人感到……"}, "sentence_index": null, "correct_answer": "杏仁"}, "level_3": {"options": [{"text": "杏仁", "is_correct": true, "explanation": "正确：粥里的“颗”状配料，指杏子核里的种子，能吃。"}, {"text": "钉子", "is_correct": false, "explanation": "语义：钉子不能放进粥里，与“粥里有几颗”的语境相悖。"}, {"text": "螺丝", "is_correct": false, "explanation": "搭配：粥里的配料应是食材，螺丝与“粥”不搭配。"}, {"text": "车票", "is_correct": false, "explanation": "语义与量词：车票不会放进粥里，“颗”也不用于车票。"}], "explanations": {"杏仁": "正确：粥里的“颗”状配料，指杏子核里的种子，能吃。", "钉子": "语义：钉子不能放进粥里，与“粥里有几颗”的语境相悖。", "螺丝": "搭配：粥里的配料应是食材，螺丝与“粥”不搭配。", "车票": "语义与量词：车票不会放进粥里，“颗”也不用于车票。"}, "sentence_index": 0, "correct_answer": "杏仁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上用杏仁刷牙，牙齿很白。", "explanation": "这里应该用〈牙膏〉。杏仁是食物，不能用来刷牙；刷牙要用牙膏。"}, {"text": "院子里那棵杏仁每年春天都开很多花。", "explanation": "这里应该用〈杏树〉。杏仁是种子，不会开花。"}, {"text": "妹妹嫌杏仁又硬又大，吃完杏子就把它扔进了垃圾桶。", "explanation": "这里应该用〈杏核〉。杏核是包着杏仁的硬壳，又硬又大要说杏核；杏仁是核里的种子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杏仁", "is_correct": true, "explanation": "正确：商店里卖的食品，“很新鲜”可以形容它。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不是食品，不能用“新鲜”形容。"}, {"text": "纸巾", "is_correct": false, "explanation": "语义：纸巾不存在新鲜与否的问题，与句意不符。"}, {"text": "电池", "is_correct": false, "explanation": "搭配：“新鲜”形容食物，不能与电池搭配。"}], "explanations": {"杏仁": "正确：商店里卖的食品，“很新鲜”可以形容它。", "玻璃": "语义：玻璃不是食品，不能用“新鲜”形容。", "纸巾": "语义：纸巾不存在新鲜与否的问题，与句意不符。", "电池": "搭配：“新鲜”形容食物，不能与电池搭配。"}, "sentence_index": 6, "correct_answer": "杏仁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "杏仁正在树上开花，颜色很漂亮。", "explanation": "这里应该用〈杏花〉。杏仁是果核里的种子，不会开花；树上开出的是杏花。"}, {"text": "这颗杏仁又红又甜，刚从树上长出来。", "explanation": "这里应该用〈杏子〉。颜色、甜度和生长是果实的特点，杏仁指核里的种子。"}, {"text": "秋天到了，杏仁变黄了，可以收回家了。", "explanation": "这里应该用〈杏子〉。变黄和收获是果实的变化，杏仁不会这样变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了三只杏仁。", "corrected_sentence": "我买了三颗杏仁。", "error_description": "量词错误：“三只杏仁”；杏仁是小颗粒，应用“颗”，不说“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把杏仁炒很香。", "corrected_sentence": "这把杏仁炒得很香。", "error_description": "错误形式：“炒很香”；正确形式：“炒得很香”。表示程度的补语前应有助词“得”，不能直接说“炒很香”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '882a0bcb-908b-47d8-af67-d883598ad1ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
