INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27064, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "养蜂就是照顾蜜蜂，让它们采花蜜。", "primary_collocate": null, "pronunciation": "yǎng fēng", "ipa": "jɑŋ˨˩˦ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "养蜂时，要常常看看蜂箱里有多少蜂蜜。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢养蜂，每天都去看蜜蜂。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花多的地方，适合养蜂。", "target_word": "养蜂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "姐姐去山里学养蜂。", "target_word": "养蜂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "养蜂的人每天都要去看看蜂箱。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天天气热，养蜂要给蜜蜂准备水。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家后院不大，不能养蜂。", "target_word": "养蜂", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他养蜂十年了，不怕蜜蜂。", "target_word": "养蜂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "养蜂的时候，他戴着帽子和手套。", "target_word": "养蜂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问我：“什么是养蜂？”", "target_word": "养蜂", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "养过蜂", "label": "体标"}, {"form": "养蜂人", "label": "复合"}, {"form": "養蜂", "label": "繁体"}], "register": "口语", "sense_fingerprint": "照顾蜜蜂，让它们采花蜜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '618ae9a4-f14e-4a14-a72f-8b79178904af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "游泳", "is_correct": false, "explanation": "语义：后半句谈蜂箱和蜂蜜，“游泳时”与之无关，句意不通。"}, {"text": "开车", "is_correct": false, "explanation": "语义：“开车时要常常看看蜂箱里有多少蜂蜜”不合常理，与句中的蜂箱语境不符。"}, {"text": "买", "is_correct": false, "explanation": "配价：“买”需要带宾语（买什么），“买时”缺少宾语，句子不成立。"}, {"text": "养蜂", "is_correct": true, "explanation": "正确。“养蜂时要常常看看蜂箱里有多少蜂蜜”，前后语境一致，符合句意。"}], "explanations": {"游泳": "语义：后半句谈蜂箱和蜂蜜，“游泳时”与之无关，句意不通。", "开车": "语义：“开车时要常常看看蜂箱里有多少蜂蜜”不合常理，与句中的蜂箱语境不符。", "买": "配价：“买”需要带宾语（买什么），“买时”缺少宾语，句子不成立。", "养蜂": "正确。“养蜂时要常常看看蜂箱里有多少蜂蜜”，前后语境一致，符合句意。"}, "sentence_index": 0, "correct_answer": "养蜂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶年轻时在家养蜂，每天给蜜蜂挤牛奶。", "explanation": "这里应该用〈养牛〉。挤牛奶是养牛的做法，养蜂饲养的是蜜蜂，蜜蜂不能挤奶。"}, {"text": "小狗学养蜂，每天都去看蜜蜂。", "explanation": "这里误把〈养蜂〉的施事换成了狗：养蜂须由人来做，小狗不能学养蜂。"}, {"text": "这些花学养蜂，每年都开得很好。", "explanation": "这里误把〈养蜂〉的施事换成了花：养蜂须由人来做，花不能学养蜂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”说的是天气，与后院大小的限制无关，“后院不大，不能下雨”句意不通。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”与后院大小无关，“后院不大，不能考试”句意不通。"}, {"text": "喝茶", "is_correct": false, "explanation": "语义：「我家后院不大」与「喝茶」无关，「不能喝茶」句意不通。"}, {"text": "养蜂", "is_correct": true, "explanation": "正确。“后院不大，不能养蜂”说明场地限制，与句意相合。"}], "explanations": {"下雨": "语义：“下雨”说的是天气，与后院大小的限制无关，“后院不大，不能下雨”句意不通。", "考试": "语义：“考试”与后院大小无关，“后院不大，不能考试”句意不通。", "喝茶": "语义：「我家后院不大」与「喝茶」无关，「不能喝茶」句意不通。", "养蜂": "正确。“后院不大，不能养蜂”说明场地限制，与句意相合。"}, "sentence_index": 6, "correct_answer": "养蜂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在村里养蜂，每天给蜜蜂剪羊毛。", "explanation": "这里应该用〈养羊〉。剪羊毛是养羊的做法，养蜂饲养的是蜜蜂，蜜蜂没有羊毛可剪。"}, {"text": "他在池塘边养蜂，每天给蜜蜂喂鱼食。", "explanation": "这里应该用〈养鱼〉。喂鱼食是养鱼的做法，蜜蜂不吃鱼食。"}, {"text": "我妈妈喜欢养蜂，每天给蜜蜂浇水施肥。", "explanation": "这里应该用〈养花〉。浇水施肥是养花的做法，蜜蜂不需要施肥，养蜂不是浇水施肥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈说，她小时候养蜂得很开心。", "corrected_sentence": "妈妈说，她小时候养蜂养得很开心。", "error_description": "补语错误：动词“养蜂”后接程度补语“得很开心”时，动词要重复，应说“养蜂养得很开心”，不能说“养蜂得很开心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷养蜂着，院子里很热闹。", "corrected_sentence": "爷爷养着蜂，院子里很热闹。", "error_description": "体标位置错误：“着”应紧跟动词“养”，说“养着蜂”，不能放在“蜂”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cf1193-53d8-46f6-ba17-01097053aa32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27066, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有利于", "is_correct": true, "explanation": "反义：“有利于”与“不利于”对事物的影响方向相反，词典列为反义词。"}, {"text": "发表", "is_correct": false, "explanation": "无关：“发表”指公开表达意见或作品，与“不利于”没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "无关：“研究”指深入探索问题，与“不利于”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "无关：“旅行”指到外地游览，与“不利于”没有反义关系。"}], "correct_answer": "有利于", "explanations": {"有利于": "反义：“有利于”与“不利于”对事物的影响方向相反，词典列为反义词。", "发表": "无关：“发表”指公开表达意见或作品，与“不利于”没有反义关系。", "研究": "无关：“研究”指深入探索问题，与“不利于”没有反义关系。", "旅行": "无关：“旅行”指到外地游览，与“不利于”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27066, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有利于", "is_correct": true, "explanation": "反义：“有利于”与“不利于”对事物的影响方向相反，词典列为反义词。"}, {"text": "参加", "is_correct": false, "explanation": "无关：“参加”指加入某项活动，与“不利于”没有反义关系。"}, {"text": "清洁", "is_correct": false, "explanation": "无关：“清洁”指把东西弄干净，与“不利于”没有反义关系。"}, {"text": "整理", "is_correct": false, "explanation": "无关：“整理”指把东西理顺，与“不利于”没有反义关系。"}], "correct_answer": "有利于", "explanations": {"有利于": "反义：“有利于”与“不利于”对事物的影响方向相反，词典列为反义词。", "参加": "无关：“参加”指加入某项活动，与“不利于”没有反义关系。", "清洁": "无关：“清洁”指把东西弄干净，与“不利于”没有反义关系。", "整理": "无关：“整理”指把东西理顺，与“不利于”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27066, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对...不好", "primary_collocate": null, "pronunciation": "bú lì yú", "ipa": "pu˧˥ li˥˩ y˧˥", "syllable_count": 3, "sentences": [{"text": "吸烟不利于健康。", "target_word": "不利于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这么晚还喝咖啡，不利于睡觉。", "target_word": "不利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "光线太暗，不利于看书。", "target_word": "不利于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "总吃快餐不利于身体。", "target_word": "不利于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个办法不利于大家合作。", "target_word": "不利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下大雨不利于今天的比赛。", "target_word": "不利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话太直，不利于和同事相处。", "target_word": "不利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饭时看电视不利于消化。", "target_word": "不利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间太小，不利于孩子玩耍。", "target_word": "不利于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长期不运动，不利于保持身体健康。", "target_word": "不利于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "有利于", "label": "反义词"}, {"form": "不利", "label": "简略形式"}], "register": "中性偏书面", "sense_fingerprint": "对某人或某事不好、没有好处，后接名词或动词短语，如不利于休息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '911ce2b6-7d1d-4794-8ddb-56c9662d33c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不利于", "is_correct": true, "explanation": "正确：吸烟对健康产生负面作用，与句中“吸烟”的语境一致。"}, {"text": "有利于", "is_correct": false, "explanation": "语义：“有利于”表示好处，与“吸烟”的常识语境矛盾。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说数量，不能说“增加健康”。"}, {"text": "恢复", "is_correct": false, "explanation": "语义：“恢复”表示回到原来的状态，吸烟不能“恢复健康”，与语境矛盾。"}], "explanations": {"不利于": "正确：吸烟对健康产生负面作用，与句中“吸烟”的语境一致。", "有利于": "语义：“有利于”表示好处，与“吸烟”的常识语境矛盾。", "增加": "搭配：“增加”说数量，不能说“增加健康”。", "恢复": "语义：“恢复”表示回到原来的状态，吸烟不能“恢复健康”，与语境矛盾。"}, "sentence_index": 0, "correct_answer": "不利于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的手机不利于了，打不开。", "explanation": "这里应该用〈坏〉。东西出了故障要说“坏了”，“不利于”说对某事有不好的影响，后面要带对象。"}, {"text": "今天天气很好，不利于我们出去玩。", "explanation": "这里应该用〈有利于〉。天气好对出去玩是好事，“不利于”说的是坏影响，与句意相反。"}, {"text": "他的话不利于我的心。", "explanation": "这里应该用〈伤〉。“不利于”不能用于说话伤人心，那种情况要用“伤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不利于", "is_correct": true, "explanation": "正确：说话太直对和同事相处有负面影响，与“太直”的语境一致。"}, {"text": "讨好", "is_correct": false, "explanation": "语义：“讨好”表示迎合别人，与“说话太直”的语境矛盾。"}, {"text": "促使", "is_correct": false, "explanation": "语义：“促使”表示推动某种结果出现，说话太直不能“促使”相处，与语境矛盾。"}, {"text": "体现", "is_correct": false, "explanation": "搭配：“体现”后面接的是品质或特点，不能说“体现和同事相处”。"}], "explanations": {"不利于": "正确：说话太直对和同事相处有负面影响，与“太直”的语境一致。", "讨好": "语义：“讨好”表示迎合别人，与“说话太直”的语境矛盾。", "促使": "语义：“促使”表示推动某种结果出现，说话太直不能“促使”相处，与语境矛盾。", "体现": "搭配：“体现”后面接的是品质或特点，不能说“体现和同事相处”。"}, "sentence_index": 6, "correct_answer": "不利于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯咖啡太不利于了，我喝不下。", "explanation": "这里应该用〈难喝〉。说味道不好用“难喝”，“不利于”说对某事有坏影响，后面要带对象。"}, {"text": "他用手电不利于山路。", "explanation": "这里应该用〈照亮〉。“不利于”说的是状况的不良影响，不能用于手电照亮山路这种具体动作。"}, {"text": "他每次都帮我，不利于我。", "explanation": "这里应该用〈帮助〉。他每次帮我是好事，“不利于”说的是坏影响，与句意相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "晚上玩手机不利于了休息。", "corrected_sentence": "晚上玩手机不利于休息。", "error_description": "错误：“不利于”后面多加了“了”，写成“不利于了休息”不对。正确：“不利于”直接带宾语“休息”，中间不加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么热的天不利于着孩子午睡。", "corrected_sentence": "这么热的天不利于孩子午睡。", "error_description": "错误：“不利于”后面多加了表示持续的“着”。正确：“不利于”直接带对象“孩子午睡”，中间不加“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ba75fc5-0637-4944-9c4b-532ed38d3d17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
