INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27068, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27068, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在某个单位或从事某项工作的人。", "primary_collocate": null, "pronunciation": "rén yuán", "ipa": "ʐən˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "公司的人员都在三楼开会。", "target_word": "人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要重新安排人员。", "target_word": "人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目的人员都很年轻。", "target_word": "人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的人员都要先登记。", "target_word": "人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把人员名单交给我。", "target_word": "人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里人员进进出出，非常忙。", "target_word": "人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救援的人员都平安回来了。", "target_word": "人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里的人员今天都放假了。", "target_word": "人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的人员比去年多了一倍。", "target_word": "人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他负责管理这里的人员。", "target_word": "人员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "工作人员", "label": "复合"}, {"form": "相关人员", "label": "复合"}], "register": "书面", "sense_fingerprint": "某个单位或集体里的成员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76649259-ba21-4681-8829-56e282963d15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27068, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人员", "is_correct": true, "explanation": "正确：“人员”指公司里的人，与“开会”搭配，语义通顺。"}, {"text": "文件", "is_correct": false, "explanation": "语义：文件不能参加开会，“公司的文件”与“开会”说不通。"}, {"text": "设备", "is_correct": false, "explanation": "搭配：“开会”的主体要是人，不能说“设备开会”。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”指一地的总人数，不指公司里的人，也不能开会。"}], "explanations": {"人员": "正确：“人员”指公司里的人，与“开会”搭配，语义通顺。", "文件": "语义：文件不能参加开会，“公司的文件”与“开会”说不通。", "设备": "搭配：“开会”的主体要是人，不能说“设备开会”。", "人口": "语义：“人口”指一地的总人数，不指公司里的人，也不能开会。"}, "sentence_index": 0, "correct_answer": "人员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家有四个人员：爸爸、妈妈、哥哥和我。", "explanation": "这里应该用〈口人〉。“人员”指单位里工作的人，说家里有几个人要用“口人”。"}, {"text": "她在银行当人员。", "explanation": "这里应该用〈职员〉。“人员”是集合名词，不用来指个人的职业，指职位要用“职员”。"}, {"text": "这部小说里有三个主要人员。", "explanation": "这里应该用〈人物〉。“人员”指一起工作或生活的人，小说里的角色要用“人物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人员", "is_correct": true, "explanation": "正确：“人员”指参加救援的人，与“平安回来”搭配，语义通顺。"}, {"text": "任务", "is_correct": false, "explanation": "语义：“任务”不能平安回来，“平安回来”只能用于人或动物。"}, {"text": "名单", "is_correct": false, "explanation": "语义：名单是纸面材料，不能“平安回来”。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“回来”的主语要是人或物体，不能说“时间回来”。"}], "explanations": {"人员": "正确：“人员”指参加救援的人，与“平安回来”搭配，语义通顺。", "任务": "语义：“任务”不能平安回来，“平安回来”只能用于人或动物。", "名单": "语义：名单是纸面材料，不能“平安回来”。", "时间": "搭配：“回来”的主语要是人或物体，不能说“时间回来”。"}, "sentence_index": 6, "correct_answer": "人员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他负责管理这里的一只人员。", "explanation": "这里量词应为〈批〉。“只”用于单个动物，不能修饰人员。"}, {"text": "他负责管理这里的一座人员。", "explanation": "这里量词应为〈批〉。“座”用于山、楼房等大型物体，人员不用“座”。"}, {"text": "他负责管理这里的一条人员。", "explanation": "这里量词应为〈批〉。“条”用于细长的东西，人员不用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司有十只人员在三楼开会。", "corrected_sentence": "公司有十名人员在三楼开会。", "error_description": "错误：「十只人员」。正确：「十名人员」。「只」用于动物，计量人员要用「名」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的救援人员地都平安回来了。", "corrected_sentence": "我们的救援人员都平安回来了。", "error_description": "错误：「救援人员地」。正确：「救援人员」。「地」是状语标记，接在动词或形容词前面，不能接在名词「人员」后面；名词之间直接组合，不加「地」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0489c55-8039-48f8-b79a-4bbe2c466f24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27070, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27070, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27070, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "我们住的地方，有空气、水和食物，这就是生存环境。", "primary_collocate": null, "pronunciation": "shēng cún huán jìng", "ipa": "ʂɤŋ˥ tsʰwən˧˥ xwan˧˥ tɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "空气、水和食物是生存环境的一部分。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟的生存环境是树林。", "target_word": "生存环境", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "鱼的生存环境是河里和海里。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙漠的生存环境很差，水很少。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里有水有树，是动物很好的生存环境。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要爱护自己的生存环境。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北方冬天很冷，那里的生存环境不好。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们看了海边动物的生存环境。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "熊猫的生存环境在山上的竹林里。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有水和食物，就没有好的生存环境。", "target_word": "生存环境", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "生存環境", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生活的地方，有空气、水和食物（日常说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '020655ba-9334-42e1-8d99-bb5d113bb481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生存环境", "is_correct": true, "explanation": "正确：“生存环境”指我们住的地方，有空气、水和食物，符合句意。"}, {"text": "收入", "is_correct": false, "explanation": "语义：收入是钱的来源，空气、水和食物不是收入的一部分。"}, {"text": "身体", "is_correct": false, "explanation": "语义：身体指人或动物的躯体，空气、水和食物不是身体的一部分。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历是受教育的记录，不是空气和食物的一部分。"}], "explanations": {"生存环境": "正确：“生存环境”指我们住的地方，有空气、水和食物，符合句意。", "收入": "语义：收入是钱的来源，空气、水和食物不是收入的一部分。", "身体": "语义：身体指人或动物的躯体，空气、水和食物不是身体的一部分。", "学历": "语义：学历是受教育的记录，不是空气和食物的一部分。"}, "sentence_index": 0, "correct_answer": "生存环境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张沙发的生存环境很好，放在客厅里很舒服。", "explanation": "这里应该用〈摆放位置〉。生存环境指我们住的地方，有空气、水和食物，沙发是家具，谈它放在哪里要用〈摆放位置〉。"}, {"text": "这把吉他的生存环境很干燥，琴弦不容易生锈。", "explanation": "这里应该用〈保存环境〉。生存环境指我们住的地方，有空气、水和食物，吉他不是生物，谈存放条件要用〈保存环境〉。"}, {"text": "这台电脑的生存环境很稳定，运行速度很快。", "explanation": "〈生存环境〉指生物的生存条件，电脑不是生物，不能说它有生存环境，这里应该用〈运行环境〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生存环境", "is_correct": true, "explanation": "正确：“生存环境”指生物生存的外界条件，“那里的生存环境不好”成立。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：嗓音是人或动物发出的声音，不能用来评价一个地方的好坏。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指人或生物的高矮，不能说“那里的身高不好”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指人或事物存在的时长，不能用来评价地方的生存条件。"}], "explanations": {"生存环境": "正确：“生存环境”指生物生存的外界条件，“那里的生存环境不好”成立。", "嗓音": "语义：嗓音是人或动物发出的声音，不能用来评价一个地方的好坏。", "身高": "语义：身高指人或生物的高矮，不能说“那里的身高不好”。", "年龄": "语义：年龄指人或事物存在的时长，不能用来评价地方的生存条件。"}, "sentence_index": 6, "correct_answer": "生存环境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支钢笔的生存环境很好，写字很顺。", "explanation": "这里应该用〈使用环境〉。生存环境指我们住的地方，有空气、水和食物，钢笔不是生物，谈使用条件要用〈使用环境〉。"}, {"text": "这台收音机的生存环境很好，声音很清楚。", "explanation": "这里应该用〈工作环境〉。生存环境指我们住的地方，有空气、水和食物，收音机不是生物，谈设备的运行条件要用〈工作环境〉。"}, {"text": "这台复印机的生存环境很好，纸张不容易卡住。", "explanation": "这里应该用〈运行环境〉。生存环境指我们住的地方，有空气、水和食物，复印机不是生物，谈运行条件要用〈运行环境〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片草原的生存环境好很。", "corrected_sentence": "这片草原的生存环境很好。", "error_description": "错误：语序。程度副词“很”应放在形容词“好”之前，应说“很好”，不能说“好很”。错误形式“生存环境好很”，正确形式“生存环境很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里有一只很好的生存环境，适合很多鸟。", "corrected_sentence": "这里有一种很好的生存环境，适合很多鸟。", "error_description": "错误：量词。“生存环境”是抽象名词，应用量词“种”或“个”，“只”用于动物或成对的东西。错误形式“一只很好的生存环境”，正确形式“一种很好的生存环境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
