INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27072, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "超出所说的范围，实际的数量、程度或内容比所提到的多得多。", "primary_collocate": null, "pronunciation": "yuǎn bù zhǐ", "ipa": "ɥɛn˨˩˦ pu˥˩ ʈʂɨ˨˩˦", "syllable_count": 3, "sentences": [{"text": "她会的远不止唱歌，还会跳舞和画画。", "target_word": "远不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的员工远不止一百人。", "target_word": "远不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想说的远不止这几句话。", "target_word": "远不止", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "北京好玩的地方远不止长城。", "target_word": "远不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子需要的远不止是吃饱穿暖。", "target_word": "远不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他为这件事付出的远不止时间。", "target_word": "远不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本词典里的词远不止五千个。", "target_word": "远不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工作带给他的远不止钱，还有快乐。", "target_word": "远不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题的原因远不止一个。", "target_word": "远不止", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他懂的东西远不止这些，你别小看他。", "target_word": "远不止", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "遠不止", "label": "繁体"}], "register": "中性", "sense_fingerprint": "说明实际内容比所提到的多得多，还包括别的很多方面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b9e37f0-e74a-4b71-a88f-897ca2745a14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27072, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "只是", "is_correct": false, "explanation": "语义：“只是”限定为唱歌，与后半句“还会跳舞和画画”相矛盾。"}, {"text": "远不止", "is_correct": true, "explanation": "“远不止”表示超出唱歌的范围，与后半句“还会跳舞和画画”呼应。"}, {"text": "仅", "is_correct": false, "explanation": "语义：“仅”表示只有，与后文“还会”的补充相反。"}, {"text": "才", "is_correct": false, "explanation": "搭配：“才”多表示数量少或时间晚，不能限定“她会的”这样的范围。"}], "explanations": {"只是": "语义：“只是”限定为唱歌，与后半句“还会跳舞和画画”相矛盾。", "远不止": "“远不止”表示超出唱歌的范围，与后半句“还会跳舞和画画”呼应。", "仅": "语义：“仅”表示只有，与后文“还会”的补充相反。", "才": "搭配：“才”多表示数量少或时间晚，不能限定“她会的”这样的范围。"}, "sentence_index": 0, "correct_answer": "远不止"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班的学生远不止十个，只有七个人来上课。", "explanation": "这里应该用〈远不到〉。远不止表示超出所说的数量，人数没到十个应该用远不到；与“只有七个人来上课”也矛盾。"}, {"text": "这个计划远不止完美，还有好几处要修改。", "explanation": "这里应该用〈远非〉。“完美”已是最高状态，不能说远不止完美；说离完美还远要用远非。"}, {"text": "这件事的难度远不止一点，我很快就做完了。", "explanation": "这里应该用〈不太〉。远不止表示超出所说的程度，难度很低应该说不太难；与“很快就做完了”一致。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很", "is_correct": false, "explanation": "搭配：“很”是程度副词，不能直接限定“五千个”这样的数量短语。"}, {"text": "远不止", "is_correct": true, "explanation": "“远不止”表示超过五千个，与“这本词典里的词”的描述一致。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”是程度副词，不能直接修饰“五千个”这样的数量词。"}, {"text": "也", "is_correct": false, "explanation": "语义：“也”表示并列，与词典词数的超出描述无关。"}], "explanations": {"很": "搭配：“很”是程度副词，不能直接限定“五千个”这样的数量短语。", "远不止": "“远不止”表示超过五千个，与“这本词典里的词”的描述一致。", "十分": "搭配：“十分”是程度副词，不能直接修饰“五千个”这样的数量词。", "也": "语义：“也”表示并列，与词典词数的超出描述无关。"}, "sentence_index": 6, "correct_answer": "远不止"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家离超市远不止两百米，走几步就到了。", "explanation": "这里应该用〈不远〉。远不止表示超出所说的距离，距离很近应该说不远；与“走几步就到”也矛盾。"}, {"text": "这家店的营业额远不止一百万，只卖了十万。", "explanation": "这里应该用〈远不及〉。远不止表示超出所说的数额，营业额达不到一百万应该用远不及；与“只卖了十万”也矛盾。"}, {"text": "这次的题目远不止简单，大家都做得很快。", "explanation": "这里应该用〈很〉。“远不止简单”是说题目比简单复杂得多，与后句“大家都做得很快”矛盾；题目简单应直接说“很简单”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市的美食很远不止火锅，还有很多小吃。", "corrected_sentence": "这个城市的美食远不止火锅，还有很多小吃。", "error_description": "错误形式：“很远不止”。正确形式：“远不止”。“远不止”本身是副词，前面不能再加“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子的兴趣是远不止画画，还有音乐和运动。", "corrected_sentence": "孩子的兴趣远不止画画，还有音乐和运动。", "error_description": "错误形式：“兴趣是远不止画画”。正确形式：“兴趣远不止画画”。“远不止”是副词，前面不能加“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
