INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27074, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "花粉从一朵花跑到另一朵花上。", "primary_collocate": null, "pronunciation": "chuán fěn", "ipa": "tʂʰwan˧˥ fən˨˩˦", "syllable_count": 2, "sentences": [{"text": "蜜蜂帮花传粉。", "target_word": "传粉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "花开了，蜜蜂来传粉。", "target_word": "传粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风来了，花就开始传粉。", "target_word": "传粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有蜜蜂，苹果树很难传粉。", "target_word": "传粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些花靠小鸟传粉。", "target_word": "传粉", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天花多，蜜蜂每天忙着传粉。", "target_word": "传粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝴蝶飞过花园，也帮忙传粉。", "target_word": "传粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜜蜂传粉后，花才能结果。", "target_word": "传粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白天蜜蜂传粉，晚上有的花靠蛾子传粉。", "target_word": "传粉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花不能自己走，所以要靠动物或风来传粉。", "target_word": "传粉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传粉者", "label": "复合"}, {"form": "傳粉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "通俗说法：花粉从一朵花到另一朵花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b139446e-7524-4719-8232-ba3bfc86546e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传粉", "is_correct": true, "explanation": "正确：“蜜蜂帮花传粉”指蜜蜂帮助花把花粉转移到另一朵花上，“传粉”符合句意。"}, {"text": "采蜜", "is_correct": false, "explanation": "语义：蜜蜂采蜜是为自己取食，不是“帮花”做的事，“帮花采蜜”不合事理。"}, {"text": "冬眠", "is_correct": false, "explanation": "语义：“冬眠”指动物冬季休眠，蜜蜂不能帮花冬眠，句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”指人悠闲地行走，与蜜蜂帮花的动作无关。"}], "explanations": {"传粉": "正确：“蜜蜂帮花传粉”指蜜蜂帮助花把花粉转移到另一朵花上，“传粉”符合句意。", "采蜜": "语义：蜜蜂采蜜是为自己取食，不是“帮花”做的事，“帮花采蜜”不合事理。", "冬眠": "语义：“冬眠”指动物冬季休眠，蜜蜂不能帮花冬眠，句意不通。", "散步": "语义：“散步”指人悠闲地行走，与蜜蜂帮花的动作无关。"}, "sentence_index": 0, "correct_answer": "传粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种鱼一到春天就开始传粉。", "explanation": "这里应该用〈繁殖〉。传粉只指花粉的转移，鱼类产卵、生育后代要用繁殖。"}, {"text": "这门手艺一代代传粉下来。", "explanation": "这里应该用〈传承〉。传粉指花粉的转移，不用于技艺、文化的承继。"}, {"text": "这台机器把数据传粉到了服务器。", "explanation": "这里应该用〈传送〉。传粉只指植物花粉的转移，不用于数据、信号的发送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传粉", "is_correct": true, "explanation": "正确：蝴蝶飞过花园时帮忙把花粉转移到花上，“传粉”符合句意。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”需要发声和表演，与蝴蝶飞过花园的语境不符，“也帮忙唱歌”句意不通。"}, {"text": "下棋", "is_correct": false, "explanation": "配价：“下棋”的施事必须是人，蝴蝶不能下棋。"}, {"text": "作画", "is_correct": false, "explanation": "语义：“作画”指人的艺术创作，与蝴蝶帮忙的动作无关。"}], "explanations": {"传粉": "正确：蝴蝶飞过花园时帮忙把花粉转移到花上，“传粉”符合句意。", "唱歌": "语义：“唱歌”需要发声和表演，与蝴蝶飞过花园的语境不符，“也帮忙唱歌”句意不通。", "下棋": "配价：“下棋”的施事必须是人，蝴蝶不能下棋。", "作画": "语义：“作画”指人的艺术创作，与蝴蝶帮忙的动作无关。"}, "sentence_index": 6, "correct_answer": "传粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆汽车很快就在路上传粉了。", "explanation": "这里的“传粉”被误用为“行驶、移动”的意思。传粉指花粉从一朵花跑到另一朵花上，汽车在路上行驶不能用传粉。"}, {"text": "这块石头很快就在河底传粉了。", "explanation": "这里的“传粉”被误用为“滚动、移动”的意思。传粉只指花粉从一朵花传到另一朵花，石头在河底滚动不能用传粉。"}, {"text": "这支乐曲很快就在城市里传粉了。", "explanation": "这里应该用〈流传〉。传粉只指花粉从一朵花传到另一朵花，乐曲在城市里传开要用“流传”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一带的花大多靠蜜蜂了传粉。", "corrected_sentence": "这一带的花大多靠蜜蜂传粉。", "error_description": "“了”误加在动词“传粉”之前。“靠蜜蜂传粉”表示习惯性的方式，不需要“了”，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蝴蝶总在花丛间把花传粉。", "corrected_sentence": "蝴蝶总在花丛间给花传粉。", "error_description": "介词误用：“传粉”是不及物动词，不能用“把”带宾语，应改为“给花传粉”，用介词“给”引出受益的花。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7392bf12-981c-4536-b27f-a87304bb7884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
