INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27076, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西最外面的一层。", "primary_collocate": null, "pronunciation": "biǎo céng", "ipa": "pjɑʊ˨˩˦ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他用刀削掉了萝卜的表层。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛋糕的表层有一层巧克力。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这面墙的表层掉了一块。", "target_word": "表层", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大雪盖住了山坡的表层。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "铁锅的表层有点生锈了。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先把面包的表层烤脆，再放进盘子里。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地毯的表层很软，踩上去很舒服。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种油漆干得快，表层一小时就干了。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只擦了桌子的表层，里面还是很脏。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天，湖水的表层结了一层冰。", "target_word": "表层", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "表層", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西最外面的一层，是看得见、摸得到的外层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b9e37f0-e74a-4b71-a88f-897ca2745a14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27076, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表层", "is_correct": true, "explanation": "正确：“表层”指萝卜最外面的一层，可以被刀削掉。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以被削掉的部分，与“削掉”不搭配。"}, {"text": "汁水", "is_correct": false, "explanation": "语义：汁水是液体，不是可以被刀削掉的外层。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”不能被“削掉”，削掉的是有形的部分。"}], "explanations": {"表层": "正确：“表层”指萝卜最外面的一层，可以被刀削掉。", "颜色": "语义：颜色不是可以被削掉的部分，与“削掉”不搭配。", "汁水": "语义：汁水是液体，不是可以被刀削掉的外层。", "重量": "搭配：“重量”不能被“削掉”，削掉的是有形的部分。"}, "sentence_index": 0, "correct_answer": "表层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的表层很冷淡，不太爱说话。", "explanation": "这里应该用〈性格〉。表层指东西的外侧，形容人的态度要用性格，不说表层。"}, {"text": "这份报告的表层很长，足足有五十页。", "explanation": "这里应该用〈篇幅〉。表层指东西外侧的一层，说文章的长短要用篇幅，不说表层。"}, {"text": "这个小区的表层很安静，住户很少出门。", "explanation": "这里应该用〈外围〉。表层指物体的外侧，说小区的边缘地带要用外围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27076, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表层", "is_correct": true, "explanation": "正确：“表层”指地毯的外侧，“软”形容的正是这一层的质地。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“软”形容质地，不能说价格很软。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味没有软硬之分，与句中描述的触感不符。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不能用“软”来形容，地毯的软硬指的是触感。"}], "explanations": {"表层": "正确：“表层”指地毯的外侧，“软”形容的正是这一层的质地。", "价格": "搭配：“软”形容质地，不能说价格很软。", "气味": "语义：气味没有软硬之分，与句中描述的触感不符。", "温度": "语义：温度不能用“软”来形容，地毯的软硬指的是触感。"}, "sentence_index": 6, "correct_answer": "表层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的表层很懂事，从不让父母操心。", "explanation": "这里应该用〈表现〉。表层指东西最外面的一层，不能用来说人的行为，应该用表现。"}, {"text": "这个歌手的表层很火，粉丝越来越多。", "explanation": "这里应该用〈人气〉。表层指物体的外侧，不能用来说人的知名度。"}, {"text": "这幅画的表层很贵，一共卖了一百万。", "explanation": "这里应该用〈价格〉。表层指物体的外侧，说作品值多少钱要用价格，不说表层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨水先湿了山坡的很表层。", "corrected_sentence": "雨水先湿了山坡的表层。", "error_description": "错误：“表层”是名词，前面不能加程度副词“很”修饰，应去掉“很”，改为“山坡的表层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这层油漆的表层透干了。", "corrected_sentence": "这层油漆的表层干透了。", "error_description": "错误：结果补语“透”应放在动词“干”之后，构成“干透”，不能说“透干”。正确：“表层干透了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
