INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27078, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很多东西混在一起，很难弄清楚。", "primary_collocate": null, "pronunciation": "cuò zōng fù zá", "ipa": "tsʰwo˥˩ tsʊŋ˥ fu˥˩ tsa˧˥", "syllable_count": 4, "sentences": [{"text": "桌子后面的电线错综复杂，很难分清哪根是哪根。", "target_word": "错综复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的心情错综复杂，不知道该笑还是该哭。", "target_word": "错综复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的人物关系错综复杂，我画了一张图。", "target_word": "错综复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶上的管道错综复杂，工人找了半天。", "target_word": "错综复杂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看着错综复杂的地图，不知道往哪走。", "target_word": "错综复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题错综复杂，不是一句话能讲清的。", "target_word": "错综复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这团线错综复杂，怎么也理不清。", "target_word": "错综复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们之间的误会错综复杂，三言两语说不完。", "target_word": "错综复杂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些数据错综复杂，我们先整理一下。", "target_word": "错综复杂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司里的人事关系错综复杂，新来的人很难适应。", "target_word": "错综复杂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "錯綜複雜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "许多东西混杂纠缠在一起，让人难以理清", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b9e37f0-e74a-4b71-a88f-897ca2745a14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "笔直", "is_correct": false, "explanation": "语义：“笔直”说线条平直，与“很难分清哪根是哪根”所描述的缠绕状态相矛盾。"}, {"text": "错综复杂", "is_correct": true, "explanation": "“错综复杂”形容电线互相缠绕，正好与“很难分清哪根是哪根”相呼应。"}, {"text": "明亮", "is_correct": false, "explanation": "体貌：“明亮”形容光线和外观，不用来形容电线的排列。"}, {"text": "简陋", "is_correct": false, "explanation": "搭配：“简陋”多形容房屋和设施，不说电线。"}], "explanations": {"笔直": "语义：“笔直”说线条平直，与“很难分清哪根是哪根”所描述的缠绕状态相矛盾。", "错综复杂": "“错综复杂”形容电线互相缠绕，正好与“很难分清哪根是哪根”相呼应。", "明亮": "体貌：“明亮”形容光线和外观，不用来形容电线的排列。", "简陋": "搭配：“简陋”多形容房屋和设施，不说电线。"}, "sentence_index": 0, "correct_answer": "错综复杂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他错综复杂地解释了这件事，大家都听懂了。", "explanation": "这里应该用〈清楚〉。错综复杂指事物互相交织、很难理清；把事情讲明白、让人听懂应该用清楚。"}, {"text": "这条鱼的尾巴很错综复杂，游起来很快。", "explanation": "这里应该用〈灵活〉。错综复杂指事物互相交织、头绪繁多；鱼尾摆动自如应该用灵活。"}, {"text": "这把椅子很错综复杂，坐起来很稳。", "explanation": "这里应该用〈结实〉。错综复杂指事物互相交织、头绪繁多，不能用来形容椅子；椅子牢固应该用结实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "简单", "is_correct": false, "explanation": "语义：“简单”与后半句“怎么也理不清”相矛盾。"}, {"text": "错综复杂", "is_correct": true, "explanation": "“错综复杂”形容线团互相缠绕，正好解释“怎么也理不清”。"}, {"text": "整齐", "is_correct": false, "explanation": "语义：“整齐”指排列有序，与“怎么也理不清”相矛盾。"}, {"text": "松软", "is_correct": false, "explanation": "搭配：“松软”多形容食物、土壤、被子等，不用来形容线。"}], "explanations": {"简单": "语义：“简单”与后半句“怎么也理不清”相矛盾。", "错综复杂": "“错综复杂”形容线团互相缠绕，正好解释“怎么也理不清”。", "整齐": "语义：“整齐”指排列有序，与“怎么也理不清”相矛盾。", "松软": "搭配：“松软”多形容食物、土壤、被子等，不用来形容线。"}, "sentence_index": 6, "correct_answer": "错综复杂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脸错综复杂，朋友们一眼就能认出他。", "explanation": "这里应该用〈独特〉。错综复杂指事物互相交织、头绪繁多；相貌与众不同应该用独特。"}, {"text": "这个数字很错综复杂，只有一个“七”字。", "explanation": "这里应该用〈简单〉。错综复杂指头绪繁多、互相交织；只有一个字的数字应该用简单。"}, {"text": "今天的天空很错综复杂，万里无云。", "explanation": "这里应该用〈晴朗〉。错综复杂指事物互相交织、头绪繁多；天空无云、明亮开阔应该用晴朗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个错综复杂问题，需要慢慢想。", "corrected_sentence": "这是一个错综复杂的问题，需要慢慢想。", "error_description": "错误形式：“错综复杂问题”。正确形式：“错综复杂的问题”。四字形容词作定语修饰名词时通常要加“的”，此处漏掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这件事情错综复杂，大家都理不清楚。", "corrected_sentence": "他把这件事情弄得错综复杂，大家都理不清楚。", "error_description": "错误形式：“把这件事情错综复杂”。正确形式：“把这件事情弄得错综复杂”。“把”字句中，形容词作谓语要用“弄得”等引出结果补语，不能直接跟在“把”的宾语后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
