INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27082, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用一种方法种地，保护环境。", "primary_collocate": null, "pronunciation": "shēng tài nóng yè", "ipa": "ʂɤŋ˥ tʰaɪ˥˩ nʊŋ˧˥ jɛ˥˩", "syllable_count": 4, "sentences": [{"text": "生态农业不伤害环境。", "target_word": "生态农业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们用生态农业的方法种地。", "target_word": "生态农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生态农业要保护水和土。", "target_word": "生态农业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我叔叔在山里搞生态农业。", "target_word": "生态农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生态农业的菜很干净。", "target_word": "生态农业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个农场做的是生态农业。", "target_word": "生态农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想去看看生态农业是怎么种地的。", "target_word": "生态农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生态农业对环境很好。", "target_word": "生态农业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "农民们都喜欢生态农业，因为地越来越好。", "target_word": "生态农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校旁边有一块生态农业的地。", "target_word": "生态农业", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "生態農業", "label": "繁体"}, {"form": "生态农业园", "label": "复合"}], "register": "中性", "sense_fingerprint": "保护环境的种地方法（日常说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '020655ba-9334-42e1-8d99-bb5d113bb481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27082, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生态农业", "is_correct": true, "explanation": "正确：利用保护环境的种地方法，与“不伤害环境”的句意一致。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是副词，不能作句子的主语。"}, {"text": "已经", "is_correct": false, "explanation": "语法：“已经”是副词，不能作句子的主语。"}, {"text": "漂亮", "is_correct": false, "explanation": "语法：“漂亮”是形容词，这里需要一个名词作主语。"}], "explanations": {"生态农业": "正确：利用保护环境的种地方法，与“不伤害环境”的句意一致。", "非常": "语法：“非常”是副词，不能作句子的主语。", "已经": "语法：“已经”是副词，不能作句子的主语。", "漂亮": "语法：“漂亮”是形容词，这里需要一个名词作主语。"}, "sentence_index": 0, "correct_answer": "生态农业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "超市的货架上摆着很多生态农业。", "explanation": "这里应该用〈有机食品〉。生态农业是种地的方法，不是可以摆在货架上卖的东西。"}, {"text": "他开着生态农业去上班。", "explanation": "这里应该用〈汽车〉。生态农业指种地的方式，不是交通工具，不能开着去上班。"}, {"text": "农民用生态农业去锄地。", "explanation": "这里应该用〈锄头〉。生态农业指种地的方式，不是可以用来锄地的工具，锄地要用锄头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27082, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动物园", "is_correct": false, "explanation": "语义：动物园是供人参观动物的地方，不种地，不能说“动物园是怎么种地的”。"}, {"text": "生态农业", "is_correct": true, "explanation": "正确：是一种种地的方法，可以用“看看是怎么种地的”来描述。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，不种地，句意不成立。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“种地”的主体是人，对象是土地或作物，“小说”不能用于“是怎么种地的”这类描述。"}], "explanations": {"动物园": "语义：动物园是供人参观动物的地方，不种地，不能说“动物园是怎么种地的”。", "生态农业": "正确：是一种种地的方法，可以用“看看是怎么种地的”来描述。", "地铁": "语义：地铁是交通工具，不种地，句意不成立。", "小说": "搭配：“种地”的主体是人，对象是土地或作物，“小说”不能用于“是怎么种地的”这类描述。"}, "sentence_index": 6, "correct_answer": "生态农业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民给地里撒了很多生态农业。", "explanation": "这里应该用〈化肥〉。生态农业是一种种植方式，不是可以撒在地里的东西。"}, {"text": "我每天早上喝一杯生态农业。", "explanation": "这里应该用〈果汁〉。生态农业指种地的方式，不是饮料，不能用“喝”来说。"}, {"text": "他是一名生态农业。", "explanation": "这里应该用〈农民〉。生态农业指一种种地的方式，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民们在尝试一只生态农业。", "corrected_sentence": "农民们在尝试一种生态农业。", "error_description": "量词错误：“生态农业”是一种种地的方法，应该用量词“种”。“只”多用于动物或成对的东西，不能用来修饰“生态农业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学的是生态农业地技术。", "corrected_sentence": "我们学的是生态农业的技术。", "error_description": "结构助词错误：“生态农业”修饰“技术”时应该用“的”，写成“地”是错误的。“地”用来修饰动词，这里不能用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
