INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27084, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可可树结的种子（可可豆），磨成粉可以做成饮料和巧克力。", "primary_collocate": null, "pronunciation": "kě kě", "ipa": "kʰɤ˨˩˦ kʰɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "可可是做巧克力的主要原料。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一包可可，想做蛋糕。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每天用很多可可做巧克力。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爱喝加糖的可可。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "可可有点苦，要加一些糖。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种饮料是用可可和牛奶做的。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热带的农民把可可晒干后卖给工厂。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给你冲一杯可可，好吗？", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在蛋糕上撒了一点可可。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "可可来自一种热带树的种子。", "target_word": "可可", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可可粉", "label": "复合"}, {"form": "可可豆", "label": "复合"}, {"form": "热可可", "label": "复合"}], "register": "中性", "sense_fingerprint": "可可树种子磨成的粉，可做饮料和巧克力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b9e37f0-e74a-4b71-a88f-897ca2745a14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27084, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可可", "is_correct": true, "explanation": "可可：可以做巧克力的种子，是句中“做巧克力的主要原料”。"}, {"text": "木材", "is_correct": false, "explanation": "语义：木材不能做巧克力，与“主要原料”的说法不符。"}, {"text": "石油", "is_correct": false, "explanation": "搭配：“做巧克力的主要原料”后面接石油，搭配不当，石油不是食品原料。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥不是食品，无法做巧克力。"}], "explanations": {"可可": "可可：可以做巧克力的种子，是句中“做巧克力的主要原料”。", "木材": "语义：木材不能做巧克力，与“主要原料”的说法不符。", "石油": "搭配：“做巧克力的主要原料”后面接石油，搭配不当，石油不是食品原料。", "水泥": "语义：水泥不是食品，无法做巧克力。"}, "sentence_index": 0, "correct_answer": "可可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们爱喝一条加糖的可可。", "explanation": "这里应该用〈杯〉。可可饮料按杯计量，“条”用于细长的东西，不能用于饮料。"}, {"text": "我们在超市买了一张可可。", "explanation": "这里应该用〈包〉。可可粉按包计量，“张”用于纸张等平面的东西，不能用于可可。"}, {"text": "妈妈晚上给我端来一座可可。", "explanation": "这里应该用〈杯〉。可可饮料按杯计量，“座”用于山、房屋等大型的东西，不能用于饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可可", "is_correct": true, "explanation": "可可：可以做饮料的种子，热带农民会把它晒干后卖给工厂。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是成品，不是晒干后卖给工厂的原料。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是液体，无法晒干后卖给工厂。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能晒干后作为农产品出售给工厂。"}], "explanations": {"可可": "可可：可以做饮料的种子，热带农民会把它晒干后卖给工厂。", "饼干": "语义：饼干是成品，不是晒干后卖给工厂的原料。", "汽油": "语义：汽油是液体，无法晒干后卖给工厂。", "石头": "语义：石头不能晒干后作为农产品出售给工厂。"}, "sentence_index": 6, "correct_answer": "可可"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我端来一根可可。", "explanation": "这里应该用〈杯〉。可可饮料按杯计量，“根”用于细长的东西，不能用于可可。"}, {"text": "我的表妹买了一本可可。", "explanation": "这里应该用〈包〉。可可粉按包计量，“本”用于书册，不能用于可可。"}, {"text": "妈妈给我冲了一棵可可。", "explanation": "这里应该用〈杯〉。可可饮料按杯计量，“棵”用于树木，不能用于饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她给我冲了一条可可。", "corrected_sentence": "她给我冲了一杯可可。", "error_description": "“可可”作饮料时量词应用“杯”，“条”用于细长的东西，不能用于饮料，应说“冲了一杯可可”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈给我冲了一杯热了可可。", "corrected_sentence": "妈妈给我冲了一杯热可可。", "error_description": "错误：“了”位置错误。“热可可”是一个复合词，中间不能插入“了”，应说“冲了一杯热可可”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
