INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27086, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "花草就是花和草，它们长在地上，很漂亮。", "primary_collocate": null, "pronunciation": "huā cǎo", "ipa": "xwa˥ tsʰaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我家门前有很多花草。", "target_word": "花草", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "花草都长在地上。", "target_word": "花草", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些花草真漂亮。", "target_word": "花草", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟喜欢画花草。", "target_word": "花草", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我每天给花草浇水。", "target_word": "花草", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "花园里的花草很多，也很香。", "target_word": "花草", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗在花草中间跑来跑去。", "target_word": "花草", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后，花草上有很多小水珠。", "target_word": "花草", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在学校种了一些花草。", "target_word": "花草", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的花草，春天最漂亮。", "target_word": "花草", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "花花草草", "label": "重叠"}, {"form": "花草树木", "label": "复合"}], "register": "中性", "sense_fingerprint": "长在地上、很漂亮的花和草（日常说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '020655ba-9334-42e1-8d99-bb5d113bb481') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27086, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花草", "is_correct": true, "explanation": "正确：“花草”指长在地上、很漂亮的花和草，门前有很多花草，符合句意。"}, {"text": "户口", "is_correct": false, "explanation": "语义：户口是户籍登记，门前不会有很多户口。"}, {"text": "嗓音", "is_correct": false, "explanation": "语义：嗓音是声音，不能用“门前有很多”来说。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指人或生物的高矮，不能用来说门前有很多。"}], "explanations": {"花草": "正确：“花草”指长在地上、很漂亮的花和草，门前有很多花草，符合句意。", "户口": "语义：户口是户籍登记，门前不会有很多户口。", "嗓音": "语义：嗓音是声音，不能用“门前有很多”来说。", "身高": "语义：身高指人或生物的高矮，不能用来说门前有很多。"}, "sentence_index": 0, "correct_answer": "花草"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸每天都吃花草，吃得很香。", "explanation": "这里不这么用。〈花草〉指观赏用的花和草，不能当食物吃，应说〈蔬菜〉。"}, {"text": "妈妈用花草做了一把椅子，很结实。", "explanation": "这里应该用〈木头〉或〈竹子〉。〈花草〉指植物，不是做家具的材料，做椅子要用〈木头〉或〈竹子〉。"}, {"text": "工人在工地上搬运花草，准备修一条马路。", "explanation": "这里应该用〈沥青〉或〈石头〉。〈花草〉是植物，不能用来修路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花草", "is_correct": true, "explanation": "正确：“花草”指花和草，小狗在花草中间跑来跑去，符合句意。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是劳动报酬，不是小狗可以跑来跑去的地方。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历是受教育的记录，与小狗跑来跑去的场景无关。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指活了多少年，小狗不能在年龄中间跑来跑去。"}], "explanations": {"花草": "正确：“花草”指花和草，小狗在花草中间跑来跑去，符合句意。", "工资": "语义：工资是劳动报酬，不是小狗可以跑来跑去的地方。", "学历": "语义：学历是受教育的记录，与小狗跑来跑去的场景无关。", "年龄": "语义：年龄指活了多少年，小狗不能在年龄中间跑来跑去。"}, "sentence_index": 6, "correct_answer": "花草"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那只小狗是很可爱的花草。", "explanation": "这里应该用〈动物〉或〈宠物〉。〈花草〉是植物，不能指小狗。"}, {"text": "孩子们在操场上用花草踢足球。", "explanation": "这里不这么用。〈花草〉是植物，不能当作足球去踢。"}, {"text": "这块金属零件是用花草做的，所以很耐用。", "explanation": "这里应该用〈金属〉。〈花草〉是植物，不能用来做零件，做零件要用〈金属〉或〈塑料〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家阳台上摆着一只花草。", "corrected_sentence": "我家阳台上摆着一盆花草。", "error_description": "错误：量词。“花草”应用量词“盆”，“只”用于动物或成对的东西。错误形式“一只花草”，正确形式“一盆花草”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们花草中间捉迷藏。", "corrected_sentence": "孩子们在花草中间捉迷藏。", "error_description": "错误：介词缺失。表示处所要用“在”，应说“在花草中间”，漏掉“在”不对。错误形式“孩子们花草中间捉迷藏”，正确形式“孩子们在花草中间捉迷藏”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39b53513-05b2-4c98-aea5-e579448c7005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
