INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27088, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个人用力量或权力让自己得到某个地方或东西。", "primary_collocate": null, "pronunciation": "zhàn", "ipa": "ʈʂan˥˩", "syllable_count": 1, "sentences": [{"text": "大个子男孩占了整张长椅。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王占了邻国的土地。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他力气大，占着球场不让别人玩。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人占了我们的路，大家过不去。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那群人仗着人多，占了公园里最好的位子。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他仗着有权，占了广场边最好的摊位。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥总想占着电视，不让我看。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里有个坏人，占过农民的田。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵很快占了河边的小桥。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他仗着自己是老板，占着会议室不让别人用。", "target_word": "占", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "占了", "label": "体标"}, {"form": "占着", "label": "体标"}, {"form": "占过", "label": "体标"}, {"form": "占据", "label": "复合"}, {"form": "占领", "label": "复合"}, {"form": "佔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "凭力量或权力把某个地方或东西据为己有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 那群 (Zipf 3.47), 仗 (Zipf 3.81), 位子 (Zipf 3.7)']::text[], '7b9e37f0-e74a-4b71-a88f-897ca2745a14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27088, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "占", "is_correct": true, "explanation": "占（zhàn）：凭力量或权力把某个地方或东西据为己有。"}, {"text": "沾", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，意思是沾上、沾染。"}, {"text": "展", "is_correct": false, "explanation": "zhǎn（第三声）与 zhàn（第四声）声调不同，意思是展开。"}, {"text": "扇", "is_correct": false, "explanation": "shàn 与 zhàn 声母不同（sh 与 zh），意思是扇子。"}, {"text": "暂", "is_correct": false, "explanation": "zàn 与 zhàn 声母不同（z 与 zh），意思是暂时。"}, {"text": "账", "is_correct": false, "explanation": "zhàng 与 zhàn 韵母不同（ang 与 an），意思是账目。"}], "explanations": {"占": "占（zhàn）：凭力量或权力把某个地方或东西据为己有。", "沾": "zhān（第一声）与 zhàn（第四声）声调不同，意思是沾上、沾染。", "展": "zhǎn（第三声）与 zhàn（第四声）声调不同，意思是展开。", "扇": "shàn 与 zhàn 声母不同（sh 与 zh），意思是扇子。", "暂": "zàn 与 zhàn 声母不同（z 与 zh），意思是暂时。", "账": "zhàng 与 zhàn 韵母不同（ang 与 an），意思是账目。"}, "sentence_index": null, "correct_answer": "占"}, "level_3": {"options": [{"text": "占", "is_correct": true, "explanation": "占：“占了整张长椅”指凭力量据为己有。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语应为食物，不能带“长椅”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”要接歌曲，不能说“唱了整张长椅”。"}, {"text": "怕", "is_correct": false, "explanation": "语义：“怕”表示害怕的心理，与据为己有的动作无关。"}], "explanations": {"占": "占：“占了整张长椅”指凭力量据为己有。", "吃": "配价：“吃”的宾语应为食物，不能带“长椅”作宾语。", "唱": "搭配：“唱”要接歌曲，不能说“唱了整张长椅”。", "怕": "语义：“怕”表示害怕的心理，与据为己有的动作无关。"}, "sentence_index": 0, "correct_answer": "占"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她占了老师的表扬。", "explanation": "这里应该用〈获得〉。占指凭力量或权力把地方或东西据为己有，表扬是一种评价，不能被占，应该用获得。"}, {"text": "他在旅行中占了很多快乐。", "explanation": "这里应该用〈收获〉。占指凭力量或权力把地方或东西据为己有，快乐是人的感受，不能被占，应该用收获。"}, {"text": "他占了比赛。", "explanation": "这里应该用〈赢得〉。占是把地方或东西据为己有，比赛是竞争的结果，不能被占，应该用赢得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27088, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "占", "is_correct": true, "explanation": "占（zhàn）：凭力量或权力把某个地方或东西据为己有。"}, {"text": "粘", "is_correct": false, "explanation": "zhān（第一声）与 zhàn（第四声）声调不同，意思是粘贴。"}, {"text": "善", "is_correct": false, "explanation": "shàn 与 zhàn 声母不同（sh 与 zh），意思是善良、好。"}, {"text": "赞", "is_correct": false, "explanation": "zàn 与 zhàn 声母不同（z 与 zh），意思是赞美。"}, {"text": "胀", "is_correct": false, "explanation": "zhàng 与 zhàn 韵母不同（ang 与 an），意思是膨胀。"}], "explanations": {"占": "占（zhàn）：凭力量或权力把某个地方或东西据为己有。", "粘": "zhān（第一声）与 zhàn（第四声）声调不同，意思是粘贴。", "善": "shàn 与 zhàn 声母不同（sh 与 zh），意思是善良、好。", "赞": "zàn 与 zhàn 声母不同（z 与 zh），意思是赞美。", "胀": "zhàng 与 zhàn 韵母不同（ang 与 an），意思是膨胀。"}, "sentence_index": null, "correct_answer": "占"}, "level_3": {"options": [{"text": "占", "is_correct": true, "explanation": "占：“占着电视”指独自霸占，不让别人使用。"}, {"text": "讲", "is_correct": false, "explanation": "搭配：“讲”要接话语或故事，不能说“讲着电视”。"}, {"text": "咬", "is_correct": false, "explanation": "配价：“咬”的宾语应为可咬的东西，不能说“咬着电视”。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”的宾语应为饮料，不能说“喝着电视”。"}], "explanations": {"占": "占：“占着电视”指独自霸占，不让别人使用。", "讲": "搭配：“讲”要接话语或故事，不能说“讲着电视”。", "咬": "配价：“咬”的宾语应为可咬的东西，不能说“咬着电视”。", "喝": "配价：“喝”的宾语应为饮料，不能说“喝着电视”。"}, "sentence_index": 6, "correct_answer": "占"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她占了一次难忘的旅程。", "explanation": "这里应该用〈体验〉。占指凭力量或权力把地方或东西据为己有，旅程是经历的过程，不能被占，应该用体验。"}, {"text": "他占了很大的成功。", "explanation": "这里应该用〈取得〉。占用于据为己有的地方或东西，成功这类抽象结果不能被占，应该用取得。"}, {"text": "他占了很高的声望。", "explanation": "这里应该用〈享有〉。占是据为己有具体的地方或东西，声望是抽象评价，应该用享有。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他占了满整个沙发。", "corrected_sentence": "他占满了整个沙发。", "error_description": "“满”是“占”的结果补语，应紧跟在“占”后，“了”放在“满”的后面，应说“占满了整个沙发”，不能说“占了满”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他占了着沙发不让我坐。", "corrected_sentence": "他占着沙发不让我坐。", "error_description": "“了”与“着”不能同时用在“占”后，应去掉“了”，改为“他占着沙发不让我坐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c018d9f-8dba-4412-8287-232c7933641e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
