INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27094, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "饮食结构就是说一个人平时吃什么和喝什么的总和。", "primary_collocate": null, "pronunciation": "yǐn shí jié gòu", "ipa": "in˨˩˦ ʂʐ̩˧˥ tɕjɛ˧˥ kou˥˩", "syllable_count": 4, "sentences": [{"text": "你的饮食结构是什么样的？", "target_word": "饮食结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想改变自己的饮食结构。", "target_word": "饮食结构", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的饮食结构里肉太多，菜太少。", "target_word": "饮食结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饮食结构不好，人就容易生病。", "target_word": "饮食结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生问我平时的饮食结构怎么样。", "target_word": "饮食结构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了减肥，她把饮食结构调整了一下。", "target_word": "饮食结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生的饮食结构应该有菜、有肉，也要有水果。", "target_word": "饮食结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃素的人和爱吃肉的人，饮食结构很不一样。", "target_word": "饮食结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的饮食结构很简单，主要是米饭和蔬菜。", "target_word": "饮食结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生看了我的饮食结构，说我吃糖太多。", "target_word": "饮食结构", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "飲食結構", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个人平时吃喝的东西合在一起的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5fc0a8-d4f8-4387-9171-1f1a55380ca6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27094, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饮食结构", "is_correct": true, "explanation": "正确：「饮食结构」指一个人平时吃喝的东西的总和，与「你的……是什么样的」相符。"}, {"text": "地壳", "is_correct": false, "explanation": "语义：地壳是地球的构造，不是人的属性，问句不成立。"}, {"text": "电路", "is_correct": false, "explanation": "语义：电路是电器的组成部分，不能用来描述一个人的饮食。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「什么样的」一般问性质或状态，「体重」通常只说多少，不说「什么样的」。"}], "explanations": {"饮食结构": "正确：「饮食结构」指一个人平时吃喝的东西的总和，与「你的……是什么样的」相符。", "地壳": "语义：地壳是地球的构造，不是人的属性，问句不成立。", "电路": "语义：电路是电器的组成部分，不能用来描述一个人的饮食。", "体重": "搭配：「什么样的」一般问性质或状态，「体重」通常只说多少，不说「什么样的」。"}, "sentence_index": 0, "correct_answer": "饮食结构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的饮食结构坏了，要拿去店里修。", "explanation": "这里应该用〈电脑〉。饮食结构指平时吃喝的东西的总和，不是能坏、能修的物品。"}, {"text": "他已经吃完了今天的饮食结构。", "explanation": "这里应该用〈饭〉。「吃完」的对象是具体的饭菜，饮食结构是抽象的体系，不能吃完。"}, {"text": "这套房子的饮食结构很合理，客厅和卧室分开了。", "explanation": "这里应该用〈户型〉。「饮食结构」指一个人平时吃什么和喝什么，不能用来说房屋的布局；说房子的布局应用「户型」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饮食结构", "is_correct": true, "explanation": "正确：「饮食结构」指吃的食物的种类与比例，与「应该有菜、有肉，也要有水果」相符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是吃的东西，不能「有菜、有肉」。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包里不装菜和肉，句意荒谬。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：「成绩」不能与「有菜、有肉、有水果」搭配。"}], "explanations": {"饮食结构": "正确：「饮食结构」指吃的食物的种类与比例，与「应该有菜、有肉，也要有水果」相符。", "作业": "语义：作业不是吃的东西，不能「有菜、有肉」。", "书包": "语义：书包里不装菜和肉，句意荒谬。", "成绩": "搭配：「成绩」不能与「有菜、有肉、有水果」搭配。"}, "sentence_index": 6, "correct_answer": "饮食结构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月我的饮食结构增加了三公斤。", "explanation": "这里应该用〈体重〉。「增加了三公斤」说的是重量，饮食结构不能称重。"}, {"text": "今天的饮食结构很好，适合出门。", "explanation": "这里应该用〈天气〉。「适合出门」说的是天气，饮食结构不能这样用。"}, {"text": "饭店的饮食结构上写着很多菜名。", "explanation": "这里应该用〈菜单〉。「饮食结构」不是列出菜名的单子，应说「菜单」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷的一只饮食结构需要调整一下。", "corrected_sentence": "爷爷的饮食结构需要调整一下。", "error_description": "量词错误：「只」用于单个动物或成对的物件，「饮食结构」是抽象的体系，不能说「一只饮食结构」，应说「爷爷的饮食结构」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈希望爸爸改变一场饮食结构。", "corrected_sentence": "妈妈希望爸爸改变饮食结构。", "error_description": "量词错误：「场」用于雨、比赛等事件，不能修饰「饮食结构」；这里直接说「改变饮食结构」即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
