INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27096, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人的身体机能或能力，以及国力、经济、事业、地方等，由强变弱、由盛转衰。", "primary_collocate": null, "pronunciation": "shuāi tuì", "ipa": "ʂuai̯˥ tʰuei̯˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷年纪大了，记忆力衰退得很快。", "target_word": "衰退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几年，我的视力一直在衰退。", "target_word": "衰退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不运动的话，身体会慢慢衰退。", "target_word": "衰退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的经济这两年有点衰退。", "target_word": "衰退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他生病以后，体力衰退了不少。", "target_word": "衰退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的生意明显衰退了。", "target_word": "衰退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人老了，听力也会衰退。", "target_word": "衰退", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "村里年轻人都走了，村子慢慢衰退了。", "target_word": "衰退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的国力正在衰退。", "target_word": "衰退", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过了五十岁，人的免疫力会开始衰退。", "target_word": "衰退", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "衰退了", "label": "体标"}, {"form": "衰退过", "label": "体标"}, {"form": "衰退期", "label": "复合"}], "register": "中性", "sense_fingerprint": "衰退|动词|身体机能或国力、经济等由强变弱、由盛转衰", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fed2657-c642-412b-9bc3-e34e316666ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27096, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "衰退", "is_correct": true, "explanation": "正确。爷爷年纪大了，记忆力变差，衰退得很快。"}, {"text": "增强", "is_correct": false, "explanation": "语义：“增强”是变好，与“爷爷年纪大了”的语境相矛盾。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“记忆力”不说“生长”，与“得很快”搭配也不通。"}, {"text": "繁殖", "is_correct": false, "explanation": "语义：“繁殖”指生物增加后代，与记忆力无关。"}], "explanations": {"衰退": "正确。爷爷年纪大了，记忆力变差，衰退得很快。", "增强": "语义：“增强”是变好，与“爷爷年纪大了”的语境相矛盾。", "生长": "搭配：“记忆力”不说“生长”，与“得很快”搭配也不通。", "繁殖": "语义：“繁殖”指生物增加后代，与记忆力无关。"}, "sentence_index": 0, "correct_answer": "衰退"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车突然向后衰退了一米。", "explanation": "这里应该用〈后退〉。衰退表示水平或状态变差，不表示位置的移动。"}, {"text": "墙上的油漆慢慢衰退了。", "explanation": "这里应该用〈剥落〉。衰退指人或能力逐渐变差，油漆的脱落要说剥落。"}, {"text": "夜里，敌军悄悄衰退了。", "explanation": "这里应该用〈撤退〉。衰退不指军队离开阵地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衰退", "is_correct": true, "explanation": "正确。人老了，听力变差，与“也会”的语境相符。"}, {"text": "发育", "is_correct": false, "explanation": "语义：“发育”指随年龄增长而长大，与“人老了”的语境相矛盾。"}, {"text": "成长", "is_correct": false, "explanation": "语义：“成长”指向上发展，与“人老了”不符。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：“发芽”多用于植物，人的听力不说发芽。"}], "explanations": {"衰退": "正确。人老了，听力变差，与“也会”的语境相符。", "发育": "语义：“发育”指随年龄增长而长大，与“人老了”的语境相矛盾。", "成长": "语义：“成长”指向上发展，与“人老了”不符。", "发芽": "搭配：“发芽”多用于植物，人的听力不说发芽。"}, "sentence_index": 6, "correct_answer": "衰退"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "夜里气温明显衰退了。", "explanation": "这里应该用〈降低〉。气温的变化用降低或下降，衰退不用来形容气温。"}, {"text": "这个孩子的身高衰退得很快。", "explanation": "这里应该用〈发育〉。孩子身高增长，应说发育或长高，衰退是变差。"}, {"text": "这瓶牛奶放了三天，已经衰退了。", "explanation": "这里应该用〈变质〉。衰退指人或能力逐渐变差，食物变坏要说变质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两年他的听力衰退地很厉害。", "corrected_sentence": "这两年他的听力衰退得很厉害。", "error_description": "“衰退”后作程度补语，应用“得”，不能用“地”。“地”用于修饰动词，句中应改为“衰退得很厉害”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年，他的记忆力慢慢被衰退了。", "corrected_sentence": "这几年，他的记忆力慢慢衰退了。", "error_description": "“衰退”是不及物动词，不能用“被”字句。应去掉“被”，改为“记忆力慢慢衰退了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
