INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27102, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "研究动物、植物和它们生活环境的科学家。", "primary_collocate": null, "pronunciation": "shēng tài xué jiā", "ipa": "ʂɤŋ˥ tʰai̯˥˩ ɕɥe˧˥ tɕja˥", "syllable_count": 4, "sentences": [{"text": "生态学家在山上看小鸟怎么生活。", "target_word": "生态学家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我姐姐是一位生态学家，她很爱大自然。", "target_word": "生态学家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生态学家说，这片树林里有很多动物。", "target_word": "生态学家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位生态学家每天都去河边看水和鱼。", "target_word": "生态学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态学家想知道，花和蜜蜂是什么关系。", "target_word": "生态学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我长大想当生态学家，去研究森林。", "target_word": "生态学家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生态学家告诉我们，树对小动物很重要。", "target_word": "生态学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位生态学家带着我们参观湿地公园。", "target_word": "生态学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生态学家在池塘边住了一个月，看青蛙和水草。", "target_word": "生态学家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请来了一位生态学家，给我们讲鸟类。", "target_word": "生态学家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "生态学", "label": "复合"}, {"form": "生態學家", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生态学家|名词|研究动植物与生活环境的科学家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fed2657-c642-412b-9bc3-e34e316666ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27102, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生态学家", "is_correct": true, "explanation": "正确。研究动植物和生活环境的人，才会在山上观察小鸟的生活。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能观察，与“看小鸟怎么生活”的动作不符。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球是运动用品，无法进行观察。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能在山上观察鸟类。"}], "explanations": {"生态学家": "正确。研究动植物和生活环境的人，才会在山上观察小鸟的生活。", "冰箱": "语义：冰箱不能观察，与“看小鸟怎么生活”的动作不符。", "篮球": "语义：篮球是运动用品，无法进行观察。", "饼干": "语义：饼干是食品，不能在山上观察鸟类。"}, "sentence_index": 0, "correct_answer": "生态学家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位生态学家每天晚上都用望远镜看星星。", "explanation": "这里应该用〈天文学家〉。生态学家研究生物与环境的关系，星星属于天文学的研究对象。"}, {"text": "那位生态学家每天都去河边送信。", "explanation": "这里应该用〈邮递员〉。生态学家研究生物与环境的关系，送信的是邮递员。"}, {"text": "那位生态学家每天都在工厂里修机器。", "explanation": "这里应该用〈机械师〉。生态学家研究生物与环境的关系，修机器的是机械师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27102, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生态学家", "is_correct": true, "explanation": "正确。生态学家能够告诉我们树与动物的关系。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：水杯不能说话，无法告诉我们任何道理。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟只能报时，不能告诉我们树与小动物的关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日用品，不能发表关于生态的看法。"}], "explanations": {"生态学家": "正确。生态学家能够告诉我们树与动物的关系。", "水杯": "语义：水杯不能说话，无法告诉我们任何道理。", "闹钟": "语义：闹钟只能报时，不能告诉我们树与小动物的关系。", "雨伞": "语义：雨伞是日用品，不能发表关于生态的看法。"}, "sentence_index": 6, "correct_answer": "生态学家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校请来了一位生态学家，给我们讲细胞。", "explanation": "这里应该用〈生物学家〉。细胞结构属于生物学，生态学家研究的是生物与环境的关系。"}, {"text": "学校请来了一位生态学家，给我们讲数学。", "explanation": "这里应该用〈数学老师〉。生态学家研究生物与环境的关系，讲数学的应是数学老师。"}, {"text": "这位生态学家每天都在店里做衣服。", "explanation": "这里应该用〈裁缝〉。生态学家研究生物与环境的关系，做衣服的是裁缝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈以前是一名生态学家们。", "corrected_sentence": "我妈妈以前是一名生态学家。", "error_description": "“一名”是数量词结构，不能与“们”连用。“们”不能加在有数量词修饰的名词后面，应去掉“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师年轻时是一只生态学家。", "corrected_sentence": "这位老师年轻时是一位生态学家。", "error_description": "“生态学家”指人，量词应用“位”，“只”多用于动物，不能用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
