INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27104, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "东西看起来很清楚。", "primary_collocate": null, "pronunciation": "gāo fēn biàn lǜ", "ipa": "kau̯˥ fən˥ pjɛn˥˩ ly˥˩", "syllable_count": 4, "sentences": [{"text": "这个屏幕是高分辨率的，字很清楚。", "target_word": "高分辨率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用高分辨率的相机拍的照片，字和线条都很清楚。", "target_word": "高分辨率", "complexity_tier": "T3", "furigana": "gāo fēn biàn lǜ", "sentence_source": "generated"}, {"text": "高分辨率的照片，连小花都看得很清楚。", "target_word": "高分辨率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部手机的相机是高分辨率的，拍出来很清楚。", "target_word": "高分辨率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的电脑是高分辨率的，电影里的脸都很清楚。", "target_word": "高分辨率", "complexity_tier": "T3", "furigana": "gāo fēn biàn lǜ", "sentence_source": "generated"}, {"text": "要看清远处的鸟，需要高分辨率的相机。", "target_word": "高分辨率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张图片是高分辨率的，放大也不会模糊。", "target_word": "高分辨率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的投影仪是高分辨率的，地图上的小字很清楚。", "target_word": "高分辨率", "complexity_tier": "T3", "furigana": "gāo fēn biàn lǜ", "sentence_source": "generated"}, {"text": "我想换一个高分辨率的显示器，现在的太模糊了。", "target_word": "高分辨率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里都是高分辨率的图片，每一张都很清楚。", "target_word": "高分辨率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "超高分辨率", "label": "复合"}, {"form": "低分辨率", "label": "复合"}], "register": "中性", "sense_fingerprint": "高分辨率|名词|东西看起来很清楚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fed2657-c642-412b-9bc3-e34e316666ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27104, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模糊", "is_correct": false, "explanation": "语义：“模糊”与后半句“字很清楚”正相反，屏幕不可能既模糊又让字很清楚。"}, {"text": "高分辨率", "is_correct": true, "explanation": "正确：作谓语，说明屏幕上的东西看起来很清楚，与“字很清楚”一致。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”说的是声音，不用来形容屏幕。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”多用于声音或环境，不用来形容屏幕的显示效果。"}], "explanations": {"模糊": "语义：“模糊”与后半句“字很清楚”正相反，屏幕不可能既模糊又让字很清楚。", "高分辨率": "正确：作谓语，说明屏幕上的东西看起来很清楚，与“字很清楚”一致。", "嘈杂": "搭配：“嘈杂”说的是声音，不用来形容屏幕。", "安静": "搭配：“安静”多用于声音或环境，不用来形容屏幕的显示效果。"}, "sentence_index": 0, "correct_answer": "高分辨率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的厨艺是高分辨率的。", "explanation": "这里应该用〈高超〉。高超用于技艺，高分辨率只说东西看起来清楚。"}, {"text": "这件木雕是高分辨率的。", "explanation": "这里应该用〈精细〉。精细用于工艺品的做工，高分辨率只用于说东西看起来清楚。"}, {"text": "他的性格是高分辨率的。", "explanation": "这里是把〈高分辨率〉用来说人的性格清楚、直率，它只说东西看起来清楚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无声", "is_correct": false, "explanation": "搭配：“无声”说的是声音，图片没有声音，不能这样形容图片。"}, {"text": "模糊", "is_correct": false, "explanation": "语义：“模糊”与后半句“放大也不会模糊”直接矛盾。"}, {"text": "高分辨率", "is_correct": true, "explanation": "正确：作谓语，说明图片清楚，放大后也不模糊。"}, {"text": "小", "is_correct": false, "explanation": "语义：图片小，放大后就会模糊，与后半句“放大也不会模糊”矛盾。"}], "explanations": {"无声": "搭配：“无声”说的是声音，图片没有声音，不能这样形容图片。", "模糊": "语义：“模糊”与后半句“放大也不会模糊”直接矛盾。", "高分辨率": "正确：作谓语，说明图片清楚，放大后也不模糊。", "小": "语义：图片小，放大后就会模糊，与后半句“放大也不会模糊”矛盾。"}, "sentence_index": 6, "correct_answer": "高分辨率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇论文是高分辨率的。", "explanation": "这里应该用〈严谨〉。严谨用于论文、研究，高分辨率只说东西看起来清楚。"}, {"text": "这位医生的医术是高分辨率的。", "explanation": "这里应该用〈高明〉。高明用于医术、见识，高分辨率只说东西看起来清楚。"}, {"text": "这个方法是高分辨率的。", "explanation": "这里应该用〈高效〉。高效用于方法、工作，高分辨率只说东西看起来清楚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台投影仪是高分辨率。", "corrected_sentence": "这台投影仪是高分辨率的。", "error_description": "错误在缺少“的”：“高分辨率”在“是”后面说明投影仪的性质时，要说成“是高分辨率的”，句末的“的”不能省。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这款相机的一把高分辨率能让照片拍得很清楚。", "corrected_sentence": "这款相机的高分辨率能让照片拍得很清楚。", "error_description": "错误在量词：“高分辨率”是抽象的性质，不能用“一把”（“把”用于有柄的东西）。应去掉“一把”，改为“相机的高分辨率”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
