INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27108, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个东西影响到别的东西，比如水波碰到岸。", "primary_collocate": null, "pronunciation": "bō jí", "ipa": "pwɔ˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "湖里的水波一直波及到岸边。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头掉进水里，水波波及了远处的小船。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水波慢慢波及到对面的岸。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大浪波及了海边的沙滩。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扔石头产生的波纹波及了荷叶。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖面的涟漪慢慢波及了岸边的芦苇。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔船驶过后，水波波及了两岸的芦苇。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快艇开过去，水波波及了岸边的小船。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "涨潮的海水波及了岸上的小路。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水波波及的范围越来越大。", "target_word": "波及", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "波及了", "label": "体标"}, {"form": "波及过", "label": "体标"}, {"form": "波及到", "label": "补语"}], "register": "书面语", "sense_fingerprint": "一物影响到另一物，如水波及岸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18462fa8-6019-40c1-b9b3-2f552a608b56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "波及", "is_correct": true, "explanation": "正确：“波及到”表示水波扩散到岸边，符合水波影响的场景。"}, {"text": "修建", "is_correct": false, "explanation": "语义：“修建”指人工建造，水波不能修建岸边。"}, {"text": "捕捞", "is_correct": false, "explanation": "语义：“捕捞”指捞取水产，水波不能捕捞到岸边。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”的对象是庄稼，不能说收割到岸边。"}], "explanations": {"波及": "正确：“波及到”表示水波扩散到岸边，符合水波影响的场景。", "修建": "语义：“修建”指人工建造，水波不能修建岸边。", "捕捞": "语义：“捕捞”指捞取水产，水波不能捕捞到岸边。", "收割": "搭配：“收割”的对象是庄稼，不能说收割到岸边。"}, "sentence_index": 0, "correct_answer": "波及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "河水波及了大海。", "explanation": "这里应该用〈流入〉。流入指水流进入某处，波及指影响扩散到某个对象，河水流入大海不能说波及。"}, {"text": "他的手波及到了琴键。", "explanation": "这里应该用〈触碰〉。触碰指身体直接接触，波及指影响扩散，不能表示手与琴键的直接接触。"}, {"text": "小船波及了岸边。", "explanation": "这里应该用〈靠近〉。靠近指位置相近，小船接近岸边要用靠近，波及不能描述船的移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "波及", "is_correct": true, "explanation": "正确：“波及了”表示水波扩散到两岸的芦苇，与船过后的水波相合。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：“修剪”指整理植物的枝叶，水波不会修剪芦苇。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”要求人作施事、车船作宾语，水波与芦苇都不合。"}, {"text": "采摘", "is_correct": false, "explanation": "语义：“采摘”指人摘取果实或叶子，水波不能采摘芦苇。"}], "explanations": {"波及": "正确：“波及了”表示水波扩散到两岸的芦苇，与船过后的水波相合。", "修剪": "语义：“修剪”指整理植物的枝叶，水波不会修剪芦苇。", "驾驶": "配价：“驾驶”要求人作施事、车船作宾语，水波与芦苇都不合。", "采摘": "语义：“采摘”指人摘取果实或叶子，水波不能采摘芦苇。"}, "sentence_index": 6, "correct_answer": "波及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这列火车波及了终点站。", "explanation": "这里应该用〈到达〉。到达指抵达某处，火车驶抵终点站要用到达；波及指一个东西影响到别的东西，不能表示移动抵达。"}, {"text": "妈妈波及孩子的头。", "explanation": "这里应该用〈抚摸〉。抚摸指用手轻轻接触，波及指影响扩散，不能表示用手轻触。"}, {"text": "口香糖波及了鞋底。", "explanation": "这里应该用〈粘住〉。粘住指物体附着在另一物上，口香糖附着在鞋底要用粘住，波及不表示附着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上涨的河水波及了过河边的草地。", "corrected_sentence": "上涨的河水波及过河边的草地。", "error_description": "错误：“波及了过”。“了”与“过”不能同用；表示曾经影响到某处应只用“波及过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "远处的礁石把船身的波纹波及了。", "corrected_sentence": "远处的礁石被船身的波纹波及了。", "error_description": "错误：「把」误用于被动句。「波及」的受事“远处的礁石”要用「被」引出施事“船身的波纹”，应改为「被」，写作「远处的礁石被船身的波纹波及了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
