INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27112, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用机器和科学方法种地，生产很多粮食。", "primary_collocate": null, "pronunciation": "xiàn dài nóng yè", "ipa": "ɕjɛn˥˩ taɪ˥˩ nʊŋ˧˥ jɛ˥˩", "syllable_count": 4, "sentences": [{"text": "现代农业用机器种地。", "target_word": "现代农业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "现代农业能生产很多粮食。", "target_word": "现代农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在现代农业里，农民开着拖拉机种地。", "target_word": "现代农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代农业不只靠力气，也靠科学方法。", "target_word": "现代农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我叔叔做现代农业，田里有很多机器。", "target_word": "现代农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现代农业让每亩地多产了不少粮食。", "target_word": "现代农业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带我们了解现代农业，田里到处是机器。", "target_word": "现代农业", "complexity_tier": "T3", "furigana": "xiàndài nóngyè", "sentence_source": "generated"}, {"text": "爷爷种地靠经验，现代农业却靠机器和科学。", "target_word": "现代农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代农业用的机器很贵，但是种得又快又好。", "target_word": "现代农业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子搞现代农业以后，粮食多了很多。", "target_word": "现代农业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "現代農業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用机器和科学方法种地、产粮多的农业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea5fc0a8-d4f8-4387-9171-1f1a55380ca6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27112, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现代农业", "is_correct": true, "explanation": "正确：“现代农业”指用机器和科学方法种地的农业，与“用机器种地”一致。"}, {"text": "原始农业", "is_correct": false, "explanation": "语义：原始农业依靠人力和畜力，不会用机器种地。"}, {"text": "畜牧业", "is_correct": false, "explanation": "语义：畜牧业以饲养为主，不负责种地。"}, {"text": "手工作坊", "is_correct": false, "explanation": "搭配：“作坊”是加工小件物品的场所，不能作“种地”的主语。"}], "explanations": {"现代农业": "正确：“现代农业”指用机器和科学方法种地的农业，与“用机器种地”一致。", "原始农业": "语义：原始农业依靠人力和畜力，不会用机器种地。", "畜牧业": "语义：畜牧业以饲养为主，不负责种地。", "手工作坊": "搭配：“作坊”是加工小件物品的场所，不能作“种地”的主语。"}, "sentence_index": 0, "correct_answer": "现代农业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个村子引进了一头现代农业。", "explanation": "量词错误。这里应该用〈种〉：〈头〉用于牲畜，现代农业是生产方式，应说“一种现代农业”。"}, {"text": "农民用现代农业每小时收割十亩地。", "explanation": "这里应该用〈收割机〉。收割要靠具体的机械，现代农业是生产方式，不能当机器用。"}, {"text": "他出生在现代农业，从小就用手机。", "explanation": "这里应该用〈现代社会〉。“出生在”要接地点或时代，“现代农业”指生产方式，不能作时代或地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现代农业", "is_correct": true, "explanation": "正确：“现代农业”靠机器和科学方法种地，与“田里到处是机器”一致。"}, {"text": "传统农业", "is_correct": false, "explanation": "语义：传统农业以人力为主，与“到处是机器”不符。"}, {"text": "手工作坊", "is_correct": false, "explanation": "语义：手工作坊靠手工加工东西，与“田里”和“到处是机器”都不符。"}, {"text": "渔业", "is_correct": false, "explanation": "语义：渔业是捕鱼、养鱼，与“田里到处是机器”不符。"}], "explanations": {"现代农业": "正确：“现代农业”靠机器和科学方法种地，与“田里到处是机器”一致。", "传统农业": "语义：传统农业以人力为主，与“到处是机器”不符。", "手工作坊": "语义：手工作坊靠手工加工东西，与“田里”和“到处是机器”都不符。", "渔业": "语义：渔业是捕鱼、养鱼，与“田里到处是机器”不符。"}, "sentence_index": 6, "correct_answer": "现代农业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个村子喷了很多现代农业。", "explanation": "这里应该用〈农药〉。喷洒的是具体的物质，现代农业是生产方式，不能被喷。"}, {"text": "这块地施了很多现代农业。", "explanation": "这里应该用〈化肥〉。施加的是具体的物质，现代农业不能被施加。"}, {"text": "这所学校已经实现了现代农业。", "explanation": "这里应该用〈现代化〉。“现代农业”专指农业生产方式，不能用于学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆现代农业能让粮食增产。", "corrected_sentence": "这种现代农业能让粮食增产。", "error_description": "量词错误：「辆」用于车辆，「现代农业」是抽象的生产方式，应说「这种现代农业」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家现代农业以后，粮食多了很多。", "corrected_sentence": "我家改用现代农业以后，粮食多了很多。", "error_description": "漏词错误：“现代农业”前缺少动词“改用”，“现代农业以后”没有谓语。应为“改用现代农业以后”，其中“现代农业”作“改用”的宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '23c349f0-88a0-4b80-b2a7-c87fc75f0484') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
