INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27114, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27114, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "父母把自己身上的东西传给孩子。", "primary_collocate": null, "pronunciation": "yí chuán", "ipa": "i˧˥ ʈʂʰwan˧˥", "syllable_count": 2, "sentences": [{"text": "我的大眼睛遗传自妈妈。", "target_word": "遗传", "complexity_tier": "T3", "furigana": "wǒ de dà yǎnjing yíchuán zì māma", "sentence_source": "generated"}, {"text": "他的高个子遗传自爸爸。", "target_word": "遗传", "complexity_tier": "T3", "furigana": "tā de gāo gèzi yíchuán zì bàba", "sentence_source": "generated"}, {"text": "这种病会遗传给孩子。", "target_word": "遗传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹的好嗓子遗传自奶奶。", "target_word": "遗传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的近视遗传自爸爸。", "target_word": "遗传", "complexity_tier": "T3", "furigana": "wǒ de jìnshì yíchuán zì bàba", "sentence_source": "generated"}, {"text": "孩子的笑容遗传自母亲。", "target_word": "遗传", "complexity_tier": "T3", "furigana": "háizi de xiàoróng yíchuán zì mǔqīn", "sentence_source": "generated"}, {"text": "黑头发会遗传给下一代。", "target_word": "遗传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的酒窝遗传自爸爸。", "target_word": "遗传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的白毛遗传自狗妈妈。", "target_word": "遗传", "complexity_tier": "T3", "furigana": "xiǎo gǒu de bái máo yíchuán zì gǒu māma", "sentence_source": "generated"}, {"text": "哥哥跟爸爸一样爱笑，这是爸爸遗传给他的。", "target_word": "遗传", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "遗传了", "label": "体标"}, {"form": "遗传病", "label": "复合"}], "register": "中性", "sense_fingerprint": "父母把特点传给孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fed2657-c642-412b-9bc3-e34e316666ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27114, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传染", "is_correct": false, "explanation": "语义：“传染”指疾病由人传到人，不能用于眼睛的形状。"}, {"text": "借", "is_correct": false, "explanation": "配价：“借”要求借入与借出的事物，“大眼睛”不能被借出。"}, {"text": "遗传", "is_correct": true, "explanation": "正确。“遗传自”表示特征从父母一方传来，与句意一致。"}, {"text": "模仿", "is_correct": false, "explanation": "配价：“模仿”的对象是他人的行为，不能以身体特征为对象。"}], "explanations": {"传染": "语义：“传染”指疾病由人传到人，不能用于眼睛的形状。", "借": "配价：“借”要求借入与借出的事物，“大眼睛”不能被借出。", "遗传": "正确。“遗传自”表示特征从父母一方传来，与句意一致。", "模仿": "配价：“模仿”的对象是他人的行为，不能以身体特征为对象。"}, "sentence_index": 0, "correct_answer": "遗传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座老房子是爷爷遗传下来的。", "explanation": "这里应该用〈继承〉。房产、财物的承接用继承；遗传只用于父母把身体特征传给子女。"}, {"text": "这种病是妹妹遗传给奶奶的。", "explanation": "这里应该用〈传染〉。病从一个人传到另一个人用传染；遗传只用于父母传给子女。"}, {"text": "我把钥匙遗传给了朋友。", "explanation": "这里应该用〈转交〉。钥匙这类物品的交付用转交或送；遗传只用于父母把身体特征传给子女。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "送", "is_correct": false, "explanation": "语义：“送”指把东西交给别人，黑头发不能被送给后代。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔给”的对象是可以抛掷的东西，不能与“黑头发”这类特征搭配。"}, {"text": "抛", "is_correct": false, "explanation": "语义：“抛”指把东西抛出去，与特征的传递无关。"}, {"text": "遗传", "is_correct": true, "explanation": "正确。“遗传给”指特征传给后代，与句意一致。"}], "explanations": {"送": "语义：“送”指把东西交给别人，黑头发不能被送给后代。", "扔": "搭配：“扔给”的对象是可以抛掷的东西，不能与“黑头发”这类特征搭配。", "抛": "语义：“抛”指把东西抛出去，与特征的传递无关。", "遗传": "正确。“遗传给”指特征传给后代，与句意一致。"}, "sentence_index": 6, "correct_answer": "遗传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师把知识遗传给学生。", "explanation": "这里应该用〈传授〉。知识、技艺的教授用传授；遗传只用于生物性状的代代传递。"}, {"text": "他把公司遗传给了朋友。", "explanation": "这里应该用〈转让〉。公司、产权的让渡用转让；遗传只用于父母传给子女的身体特征。"}, {"text": "我把这份工作遗传给了弟弟。", "explanation": "这里应该用〈交接〉。工作、职务的移交用交接；遗传只用于父母把身体特征传给子女。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的圆脸遗传外婆。", "corrected_sentence": "我的圆脸遗传自外婆。", "error_description": "错误：用“遗传”说明特征从谁那里来时，要说“遗传自”，这里漏掉了“自”，应为“遗传自外婆”。（“遗传给”后面接的是接受的人。）", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种毛色会遗传给了后代。", "corrected_sentence": "这种毛色会遗传给后代。", "error_description": "错误：“会”表示将来或可能，不能与“了”同用；应去掉“了”，写成“会遗传给后代”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14229369-8d88-474c-876a-3e73a53b642a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
