INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27116, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "农业区就是用来种很多粮食和蔬菜的地方。", "primary_collocate": null, "pronunciation": "nóng yè qū", "ipa": "nʊŋ˧˥ jɛ˥˩ tɕʰy˥˥", "syllable_count": 3, "sentences": [{"text": "这个农业区种了很多粮食和蔬菜。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农业区的人每天很早就下地干活。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家在农业区，旁边都是菜地。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个农业区的大米，卖到了全国各地。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农业区离城市不远，菜很新鲜。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天，农业区的农民开始种玉米。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天，我们去农业区看了一大片麦田。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个农业区的土地好，种什么都长得好。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每年秋天，农业区都有很多新粮食。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农业区的蔬菜每天用车送到城里。", "target_word": "农业区", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "片", "label": "量词"}, {"form": "農業區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "种植大量粮食和蔬菜的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f50129e-3400-4b77-b079-c3bc4a5b6d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "农业区", "is_correct": true, "explanation": "“农业区”是种植粮食和蔬菜的地方，与“种了很多粮食和蔬菜”一致。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是卖东西的地方，不能种粮食和蔬菜。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不能种植作物，与句中“种了粮食”冲突。"}, {"text": "书店", "is_correct": false, "explanation": "语义：书店是卖书的地方，不能用来大面积种粮食和蔬菜。"}], "explanations": {"农业区": "“农业区”是种植粮食和蔬菜的地方，与“种了很多粮食和蔬菜”一致。", "超市": "语义：超市是卖东西的地方，不能种粮食和蔬菜。", "医院": "语义：医院不能种植作物，与句中“种了粮食”冲突。", "书店": "语义：书店是卖书的地方，不能用来大面积种粮食和蔬菜。"}, "sentence_index": 0, "correct_answer": "农业区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把农业区放在桌子上了。", "explanation": "这里应该用〈书〉。“农业区”是一大片地区，不能放在桌子上。"}, {"text": "我每天把农业区装进书包，去学校上课。", "explanation": "这里应该用〈课本〉。“农业区”是地区，不能装进书包；要装进书包的是〈课本〉。"}, {"text": "妈妈每天用农业区做饭、洗衣服。", "explanation": "“农业区”是地区，不能当作做饭、洗衣服的工具；这里应该说“厨房”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "农业区", "is_correct": true, "explanation": "“去农业区看了一大片麦田”地点与麦田一致，语境通顺。"}, {"text": "地铁站", "is_correct": false, "explanation": "语义：地铁站里没有大片麦田，与“看了一大片麦田”冲突。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆里看不到大片麦田，与语境不符。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“去……看”要求一个地点，“面包”不能作为去看麦田的场所。"}], "explanations": {"农业区": "“去农业区看了一大片麦田”地点与麦田一致，语境通顺。", "地铁站": "语义：地铁站里没有大片麦田，与“看了一大片麦田”冲突。", "图书馆": "语义：图书馆里看不到大片麦田，与语境不符。", "面包": "搭配：“去……看”要求一个地点，“面包”不能作为去看麦田的场所。"}, "sentence_index": 6, "correct_answer": "农业区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台农业区的蔬菜每天用车送到城里。", "explanation": "“台”用于机器，不用于地区；农业区应该用“个”或“片”。"}, {"text": "这个农业区生产的手机，每天用车送到城里。", "explanation": "“农业区”以种植为主，不生产手机；这里应该说“工厂”。"}, {"text": "我每天用农业区送蔬菜到城里。", "explanation": "“农业区”是地区，不能当作运输的工具；这里应该说“车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只农业区今年种了很多玉米。", "corrected_sentence": "这个农业区今年种了很多玉米。", "error_description": "“农业区”的量词应用“个”或“片”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去农业区的参观，看了一大片麦田。", "corrected_sentence": "我们去农业区参观，看了一大片麦田。", "error_description": "错误在“农业区”后多加了“的”。“去农业区参观”是“去＋地点＋动词”结构，地点后不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
