INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27120, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "结实率是指植物结出果实的数量占花朵数量的比例。", "primary_collocate": null, "pronunciation": "jiē shí lǜ", "ipa": "tɕjɛ˥ ʂʐ̩˧˥ lɥy˥˩", "syllable_count": 3, "sentences": [{"text": "一百朵花结了六十个果，结实率是百分之六十。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵樱桃树开了很多花，可是结实率不高。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用果实数除以花朵数，算出结实率。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结实率越高，农民收的果子就越多。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片果园的结实率每年都不一样。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他数了花和果，算了一下结实率。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温室里的番茄结实率比外面高。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "授粉不好，结实率就会低。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们比较了两种梨树的结实率。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的结实率是百分之八十，农民很高兴。", "target_word": "结实率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "結實率", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "果实数量占花朵数量的比例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18462fa8-6019-40c1-b9b3-2f552a608b56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结实率", "is_correct": true, "explanation": "结实率指结出的果实数占花朵数的比例，与“百分之六十”搭配，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用百分比表示。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：体重用公斤计量，不说“百分之六十”。"}, {"text": "块头", "is_correct": false, "explanation": "语义：“块头”指个体的大小，不能用百分比表示，与果花数量的比例无关。"}], "explanations": {"结实率": "结实率指结出的果实数占花朵数的比例，与“百分之六十”搭配，符合句意。", "颜色": "语义：颜色不能用百分比表示。", "体重": "搭配：体重用公斤计量，不说“百分之六十”。", "块头": "语义：“块头”指个体的大小，不能用百分比表示，与果花数量的比例无关。"}, "sentence_index": 0, "correct_answer": "结实率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位射手的结实率很高。", "explanation": "这里应该用〈命中率〉。结实率只指植物结果的比例，不用于射击。"}, {"text": "这场演出的结实率很高。", "explanation": "这里应该用〈上座率〉。结实率只用于植物，不用于演出的座位。"}, {"text": "这家店的结实率很高。", "explanation": "这里应该用〈回头率〉。回头率指顾客再次光顾的比例，结实率只指植物结果的比例，不用于商店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结实率", "is_correct": true, "explanation": "结实率指番茄结果的比例，与“比外面高”搭配，符合句意。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“寿命”说长短，不说“比外面高”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能用“比外面高”来比较番茄。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：番茄没有脾气，句子说的是结果情况。"}], "explanations": {"结实率": "结实率指番茄结果的比例，与“比外面高”搭配，符合句意。", "寿命": "搭配：“寿命”说长短，不说“比外面高”。", "颜色": "语义：“颜色”指色彩，不能用“比外面高”来比较番茄。", "脾气": "语义：番茄没有脾气，句子说的是结果情况。"}, "sentence_index": 6, "correct_answer": "结实率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的结实率是百分之八十。", "explanation": "这里应该用〈通过率〉。结实率只指植物结果的比例，不用于考试。"}, {"text": "这台手术的结实率很高。", "explanation": "这里应该用〈成功率〉。结实率不用于手术，应说手术的成功率。"}, {"text": "这家工厂的结实率很高。", "explanation": "这里应该用〈合格率〉。合格率指产品达到标准的比例，结实率只指植物结果的比例，不用于工厂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这棵苹果树今年的一颗结实率很高。", "corrected_sentence": "这棵苹果树今年的结实率很高。", "error_description": "量词用错：“结实率”是抽象名词，不能用“颗”（“颗”用于颗粒状或圆形的东西）。应去掉“一颗”，写作“这棵苹果树今年的结实率很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片果园今年的结实率了远高于去年。", "corrected_sentence": "这片果园今年的结实率远高于去年。", "error_description": "“了”用错：“结实率”是名词，不能直接带“了”。应去掉“了”，写作“这片果园今年的结实率远高于去年”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27122, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "锐增", "is_correct": true, "explanation": "锐增：数量在短时间内急剧增加，与“锐减”互为反义词。"}, {"text": "保持", "is_correct": false, "explanation": "保持：维持原状，不表示数量的增减，与“锐减”没有反义关系。"}, {"text": "出现", "is_correct": false, "explanation": "出现：指显露或产生，与数量的急剧下降没有反义关系。"}, {"text": "居住", "is_correct": false, "explanation": "居住：指在某处生活，与数量的急剧下降没有反义关系。"}], "correct_answer": "锐增", "explanations": {"锐增": "锐增：数量在短时间内急剧增加，与“锐减”互为反义词。", "保持": "保持：维持原状，不表示数量的增减，与“锐减”没有反义关系。", "出现": "出现：指显露或产生，与数量的急剧下降没有反义关系。", "居住": "居住：指在某处生活，与数量的急剧下降没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27122, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "锐增", "is_correct": true, "explanation": "锐增：数量在短时间内急剧增加，与“锐减”互为反义词。"}, {"text": "搬迁", "is_correct": false, "explanation": "搬迁：指迁移住址或单位，与数量的急剧下降没有反义关系。"}, {"text": "建造", "is_correct": false, "explanation": "建造：指修建房屋或设施，与数量的下降没有反义关系。"}, {"text": "结婚", "is_correct": false, "explanation": "结婚：指男女成为夫妻，与数量的减少无关。"}], "correct_answer": "锐增", "explanations": {"锐增": "锐增：数量在短时间内急剧增加，与“锐减”互为反义词。", "搬迁": "搬迁：指迁移住址或单位，与数量的急剧下降没有反义关系。", "建造": "建造：指修建房屋或设施，与数量的下降没有反义关系。", "结婚": "结婚：指男女成为夫妻，与数量的减少无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27122, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "数量一下子变得很少。", "primary_collocate": null, "pronunciation": "ruì jiǎn", "ipa": "ɻweɪ˥˩ tɕjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "下大雪后，路上的车锐减了。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年夏天太热，来玩的人锐减。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的钱从一万元锐减到一百元。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子价格下降，买房的人锐减了。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水变脏以后，河里的鱼锐减。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个城市的游客曾经锐减过。", "target_word": "锐减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太忙，我睡觉的时间锐减了。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城里下雨少，水库里的水锐减。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校搬走后，小店的客人锐减了。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天一到，街上卖花的人锐减。", "target_word": "锐减", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "锐减了", "label": "体标"}, {"form": "锐减过", "label": "体标"}, {"form": "銳減", "label": "繁体"}], "register": "书面", "sense_fingerprint": "数量一下子大幅变少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f50129e-3400-4b77-b079-c3bc4a5b6d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27122, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "锐减", "is_correct": true, "explanation": "锐减：表示车辆数量在短时间内急剧减少，与“下大雪后”的情况相合。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”用于生物，车辆不能生长。"}, {"text": "出版", "is_correct": false, "explanation": "语义：“出版”指印刷发行书刊，与路上的车无关。"}, {"text": "消化", "is_correct": false, "explanation": "语义：“消化”指食物在体内分解吸收，与路上的车无关。"}], "explanations": {"锐减": "锐减：表示车辆数量在短时间内急剧减少，与“下大雪后”的情况相合。", "生长": "搭配：“生长”用于生物，车辆不能生长。", "出版": "语义：“出版”指印刷发行书刊，与路上的车无关。", "消化": "语义：“消化”指食物在体内分解吸收，与路上的车无关。"}, "sentence_index": 0, "correct_answer": "锐减"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几年，城里的人口慢慢锐减了。", "explanation": "这里应该用〈减少〉。锐减强调在短时间内急剧下降，不能与“慢慢”这种渐进的变化搭配。"}, {"text": "这把剪刀用了很多年，刀口锐减了。", "explanation": "这里应该用〈变钝〉。锐减只用于数量、程度的急剧下降，不指锋利程度的变化。"}, {"text": "今年的降雨只比去年少了一点，雨量锐减了。", "explanation": "这里应该用〈减少〉。锐减指大幅、急剧下降，只少了一点不能用锐减。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "锐减", "is_correct": true, "explanation": "锐减：表示睡觉时间急剧减少，与“工作太忙”的因果相合。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指把一种语言转换成另一种语言，与“睡觉的时间”不搭。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”指装饰房屋，不能说“时间装修”。"}, {"text": "邀请", "is_correct": false, "explanation": "语义：“邀请”指请人来做客或参加，与句中的时间无关。"}], "explanations": {"锐减": "锐减：表示睡觉时间急剧减少，与“工作太忙”的因果相合。", "翻译": "语义：“翻译”指把一种语言转换成另一种语言，与“睡觉的时间”不搭。", "装修": "搭配：“装修”指装饰房屋，不能说“时间装修”。", "邀请": "语义：“邀请”指请人来做客或参加，与句中的时间无关。"}, "sentence_index": 6, "correct_answer": "锐减"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只猫冬天一到就锐减。", "explanation": "这里应该用〈消失〉。锐减指一群或总量的数量大幅下降，单只猫不能锐减。"}, {"text": "电梯开始锐减，准备到一楼。", "explanation": "这里应该用〈下降〉。锐减只用于数量、程度的减少，不指电梯的位置变化。"}, {"text": "这块布洗了很多次，颜色锐减了。", "explanation": "这里应该用〈褪色〉。锐减指数量、程度的急剧下降，布的颜色变淡应说褪色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂搬走以后，这个镇的人口被锐减了。", "corrected_sentence": "工厂搬走以后，这个镇的人口锐减了。", "error_description": "错误在“锐减”前加了“被”。锐减多用来描述数量自行急剧下降，通常不与“被”构成被动；正确说法是“人口锐减了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬天一到，街上卖花的人就锐减着。", "corrected_sentence": "冬天一到，街上卖花的人就锐减了。", "error_description": "错误在“锐减”后的“着”。锐减是一次完成的急剧下降，应用“了”表示完成；“着”表示持续状态，与“锐减”不搭。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
