INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27128, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "让人。", "primary_collocate": null, "pronunciation": "lìng rén", "ipa": "liŋ˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "这种味道令人想吃。", "target_word": "令人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说的话令人生气。", "target_word": "令人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "太热的天气令人没有胃口。", "target_word": "令人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌令人想起小时候。", "target_word": "令人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动令人心情变好。", "target_word": "令人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这么晚还不回家，真令人着急。", "target_word": "令人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的批评令人难过，但他还是努力改正了。", "target_word": "令人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题令人头疼。", "target_word": "令人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的笑话令人发笑。", "target_word": "令人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个孩子懂事得令人心疼。", "target_word": "令人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "让人（产生某种感受或状态）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18462fa8-6019-40c1-b9b3-2f552a608b56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "令人", "is_correct": true, "explanation": "正确。「令人想吃」表示使人产生某种感受，符合句意。"}, {"text": "愿意", "is_correct": false, "explanation": "配价：「愿意」要求有意愿的施事，「这种味道」不能「愿意想吃」。"}, {"text": "打算", "is_correct": false, "explanation": "语义：「打算」表示有意图的计划，味道没有意图，「打算想吃」讲不通。"}, {"text": "懂得", "is_correct": false, "explanation": "配价：「懂得」需要有认知能力的主语，「这种味道懂得想吃」不成立。"}], "explanations": {"令人": "正确。「令人想吃」表示使人产生某种感受，符合句意。", "愿意": "配价：「愿意」要求有意愿的施事，「这种味道」不能「愿意想吃」。", "打算": "语义：「打算」表示有意图的计划，味道没有意图，「打算想吃」讲不通。", "懂得": "配价：「懂得」需要有认知能力的主语，「这种味道懂得想吃」不成立。"}, "sentence_index": 0, "correct_answer": "令人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师令人交作业。", "explanation": "这里应该用〈要求〉。令人表示使人产生感受或状态，不用来指派学生交作业这类具体事务。"}, {"text": "妈妈令人去买菜。", "explanation": "这里应该用〈派〉。令人表示使人产生感受或状态，不用来指派他人去买菜这类具体事务。"}, {"text": "经理令人把文件送过去。", "explanation": "这里应该用〈叫〉。令人表示使人产生感受或状态，不用来吩咐别人送文件这类具体事务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "令人", "is_correct": true, "explanation": "正确。「令人难过」表示使人产生难过的感受，符合句意。"}, {"text": "喜欢", "is_correct": false, "explanation": "配价：「喜欢」需要有喜好的施事，「老师的批评」不能「喜欢难过」。"}, {"text": "讨厌", "is_correct": false, "explanation": "配价：「讨厌」需要有感情的施事，句中的批评不能「讨厌难过」。"}, {"text": "开始", "is_correct": false, "explanation": "语义：「开始难过」说的是人的情绪转变，「老师的批评开始难过」与语境不合。"}], "explanations": {"令人": "正确。「令人难过」表示使人产生难过的感受，符合句意。", "喜欢": "配价：「喜欢」需要有喜好的施事，「老师的批评」不能「喜欢难过」。", "讨厌": "配价：「讨厌」需要有感情的施事，句中的批评不能「讨厌难过」。", "开始": "语义：「开始难过」说的是人的情绪转变，「老师的批评开始难过」与语境不合。"}, "sentence_index": 6, "correct_answer": "令人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师令人背课文。", "explanation": "这里应该用〈要求〉。令人表示使人产生感受或状态，不用来指派学生背课文这类具体事务。"}, {"text": "妈妈令人洗碗。", "explanation": "这里应该用〈叫〉。令人强调使人产生感受或状态，不用来指派他人洗碗这类日常事务。"}, {"text": "校长令人打扫教室。", "explanation": "这里应该用〈派〉。令人表示使人产生感受或状态，不用来指派别人打扫教室这类具体任务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事令人了很放心。", "corrected_sentence": "这件事令人很放心。", "error_description": "错误：「了」放错位置。「令人」是一个整体，中间不能插入「了」，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ef5f69c-3831-4753-a13e-0e4d59efd68f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
