INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27130, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "果树是能结出好吃的水果的树。", "primary_collocate": null, "pronunciation": "guǒ shù", "ipa": "kwɔ˨˩˦ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "苹果树和桃树都是果树。", "target_word": "果树", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家后面有一棵果树。", "target_word": "果树", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "果树上的水果红了，可以吃了。", "target_word": "果树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在果树下面玩。", "target_word": "果树", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "秋天，果树上挂着很多苹果。", "target_word": "果树", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵果树今年结了很多橘子。", "target_word": "果树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟飞到果树上吃果子。", "target_word": "果树", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸在院子里种了两棵果树。", "target_word": "果树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些果树不高，小孩也能摘到果子。", "target_word": "果树", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天果树开花，夏天果树结果。", "target_word": "果树", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "棵", "label": "量词"}, {"form": "果树园", "label": "复合"}, {"form": "果樹", "label": "繁体"}], "register": "中性", "sense_fingerprint": "能结出好吃水果的树", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f50129e-3400-4b77-b079-c3bc4a5b6d48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27130, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "果树", "is_correct": true, "explanation": "guǒ shù：能结出好吃水果的树，即本词。"}, {"text": "果蔬", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，“果蔬”指水果和蔬菜，不是树。"}, {"text": "过熟", "is_correct": false, "explanation": "guò（第四声）与 guǒ（第三声）、shú（第二声）与 shù（第四声）声调不同，“过熟”指果实成熟过度，不是树。"}, {"text": "国术", "is_correct": false, "explanation": "guó（第二声）与 guǒ（第三声）声调不同，“国术”指中国传统武术，不是树。"}], "explanations": {"果树": "guǒ shù：能结出好吃水果的树，即本词。", "果蔬": "shū（第一声）与 shù（第四声）声调不同，“果蔬”指水果和蔬菜，不是树。", "过熟": "guò（第四声）与 guǒ（第三声）、shú（第二声）与 shù（第四声）声调不同，“过熟”指果实成熟过度，不是树。", "国术": "guó（第二声）与 guǒ（第三声）声调不同，“国术”指中国传统武术，不是树。"}, "sentence_index": null, "correct_answer": "果树"}, "level_3": {"options": [{"text": "果树", "is_correct": true, "explanation": "果树：能结出好吃水果的树，苹果树和桃树都属于这一类。"}, {"text": "水果", "is_correct": false, "explanation": "语义：苹果树和桃树是树，不是水果，句子说的是它们属于同一类。"}, {"text": "花草", "is_correct": false, "explanation": "语义：苹果树和桃树是树木，不属于花草。"}, {"text": "果林", "is_correct": false, "explanation": "搭配：“果林”指成片的果树，单棵树不叫果林。"}], "explanations": {"果树": "果树：能结出好吃水果的树，苹果树和桃树都属于这一类。", "水果": "语义：苹果树和桃树是树，不是水果，句子说的是它们属于同一类。", "花草": "语义：苹果树和桃树是树木，不属于花草。", "果林": "搭配：“果林”指成片的果树，单棵树不叫果林。"}, "sentence_index": 0, "correct_answer": "果树"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们把果树摘下来玩。", "explanation": "这里应该用〈果子〉。果树是树，不能整棵摘下来，摘的应该是〈果子〉。"}, {"text": "孩子们在树下吃果树。", "explanation": "这里应该用〈果子〉。果树是植物，不能吃，吃的应该是〈果子〉。"}, {"text": "夏天果树结出了很多果树。", "explanation": "这里应该用〈果实〉。果树结出的是果实，不能说结出果树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "果树", "is_correct": true, "explanation": "果树：能结果子的树，小鸟飞到树上吃果子，与句意相合。"}, {"text": "果汁", "is_correct": false, "explanation": "搭配：“飞到……上”要求能落脚的地方，果汁是液体，不能搭配。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音没有实体，小鸟不能飞到声音上。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是天气现象，小鸟不能飞到雨上吃果子。"}], "explanations": {"果树": "果树：能结果子的树，小鸟飞到树上吃果子，与句意相合。", "果汁": "搭配：“飞到……上”要求能落脚的地方，果汁是液体，不能搭配。", "声音": "语义：声音没有实体，小鸟不能飞到声音上。", "雨": "语义：雨是天气现象，小鸟不能飞到雨上吃果子。"}, "sentence_index": 6, "correct_answer": "果树"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这棵果树其实是松树，叶子是针形的。", "explanation": "这里应该用〈树木〉。松树不结水果，不能称为果树，只能泛称为〈树木〉。"}, {"text": "这棵果树很甜，颜色也很鲜艳。", "explanation": "果树是树木，不会有甜味，甜的应该是果实，不是树。"}, {"text": "这种果树味的饮料很好喝。", "explanation": "这里应该用〈果味〉。“果树味”不是常用说法，表示水果的味道应用〈果味〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "果树里结满了红红的苹果。", "corrected_sentence": "果树上结满了红红的苹果。", "error_description": "错误在方位词：苹果结在树上，应用〈上〉，不能用〈里〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家后院有一只果树，每年都结很多橘子。", "corrected_sentence": "我家后院有一棵果树，每年都结很多橘子。", "error_description": "错误在量词：果树是植物，应用〈棵〉，〈只〉多用于动物，不能修饰果树。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8e55e79e-b446-4340-b8e9-1c05af53956a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
