INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27134, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "像织布的梭子一样频繁地来回往返。", "primary_collocate": null, "pronunciation": "chuān suō", "ipa": "tʂʰwan˥ swo˥", "syllable_count": 2, "sentences": [{"text": "孩子们像小鸟一样在院子里穿梭。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友在花园里穿梭，笑声不断。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几个小女孩在树下穿梭着捉迷藏。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动场上，孩子们快乐地穿梭。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小男孩在客人中穿梭，一会儿这儿一会儿那儿。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，孩子们在亲戚之间穿梭，要红包。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小学生在操场上穿梭，像一群小鸟。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿园的孩子在草地上穿梭玩耍。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小姑娘在厨房和客厅之间穿梭，帮妈妈拿东西。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在花丛里穿梭，跟着蝴蝶跑。", "target_word": "穿梭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "穿梭了", "label": "体标（了）"}, {"form": "穿梭着", "label": "体标（着）"}, {"form": "穿梭过", "label": "体标（过）"}, {"form": "穿梭机", "label": "复合词"}, {"form": "穿梭巴士", "label": "复合词"}], "register": "通用", "sense_fingerprint": "在某处或两地之间频繁来回往返、穿行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c117361b-798a-4a43-83e2-632764919ae4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27134, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穿梭", "is_correct": true, "explanation": "正确：穿梭指像小鸟一样轻快地来回跑动，与孩子在院子里玩耍的画面相合。"}, {"text": "静坐", "is_correct": false, "explanation": "语义：静坐指安静地坐着不动，与“像小鸟一样”的轻快跑动相反。"}, {"text": "下降", "is_correct": false, "explanation": "搭配：下降多用于价格、水平或飞行器，不说孩子在院子里下降。"}, {"text": "沉睡", "is_correct": false, "explanation": "语义：沉睡指熟睡不醒，与孩子在院子里活动的画面不合。"}], "explanations": {"穿梭": "正确：穿梭指像小鸟一样轻快地来回跑动，与孩子在院子里玩耍的画面相合。", "静坐": "语义：静坐指安静地坐着不动，与“像小鸟一样”的轻快跑动相反。", "下降": "搭配：下降多用于价格、水平或飞行器，不说孩子在院子里下降。", "沉睡": "语义：沉睡指熟睡不醒，与孩子在院子里活动的画面不合。"}, "sentence_index": 0, "correct_answer": "穿梭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们静静地在教室里穿梭，认真听讲。", "explanation": "这里应该用〈静坐〉。穿梭指像小鸟一样轻快地跑动，听讲时孩子应当静坐。"}, {"text": "孩子们在门口穿梭，排队等候进场。", "explanation": "这里应该用〈站立〉。穿梭是轻快地来回跑动，排队时要站定不动，应说站立。"}, {"text": "他在草地上穿梭，一直朝一个方向走，没有回头。", "explanation": "这里应该用〈穿行〉。穿梭是来回往复地跑动，一直朝一个方向走、不回头应说穿行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27134, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿梭", "is_correct": true, "explanation": "正确：穿梭指像小鸟一样来回跑动，与“像一群小鸟”的形象相合。"}, {"text": "静立", "is_correct": false, "explanation": "语义：静立指站着不动，与“像一群小鸟”的活跃形象不合。"}, {"text": "漂浮", "is_correct": false, "explanation": "搭配：漂浮用于水面或空中，不说小学生在操场上漂浮。"}, {"text": "下沉", "is_correct": false, "explanation": "语义：下沉指向下落或沉没，与在操场上来回跑动的意思不合。"}], "explanations": {"穿梭": "正确：穿梭指像小鸟一样来回跑动，与“像一群小鸟”的形象相合。", "静立": "语义：静立指站着不动，与“像一群小鸟”的活跃形象不合。", "漂浮": "搭配：漂浮用于水面或空中，不说小学生在操场上漂浮。", "下沉": "语义：下沉指向下落或沉没，与在操场上来回跑动的意思不合。"}, "sentence_index": 6, "correct_answer": "穿梭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "木箱在院子角落穿梭，堆得整整齐齐。", "explanation": "这里应该用〈摆放〉。穿梭只说能自行来回跑动的人或动物，堆放的木箱不能用穿梭。"}, {"text": "花草在院子里穿梭，长得很高。", "explanation": "这里应该用〈生长〉。穿梭指轻快地来回跑动，植物长高应该用生长。"}, {"text": "老爷爷在树下穿梭，拄着拐杖一动不动。", "explanation": "这里应该用〈静立〉。穿梭指来回跑动，“一动不动”与之矛盾，应说静立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "放学后，孩子们在操场上很穿梭，玩得很开心。", "corrected_sentence": "放学后，孩子们在操场上穿梭，玩得很开心。", "error_description": "错误在“穿梭”前加了程度副词“很”。“穿梭”是动词，不能受“很”修饰，应去掉“很”，改为“在操场上穿梭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下课后，孩子们在走廊里被穿梭，互相追逐。", "corrected_sentence": "下课后，孩子们在走廊里穿梭，互相追逐。", "error_description": "错误形式：“被穿梭”，给不及物动词穿梭加上被字。正确形式：“在走廊里穿梭”。穿梭没有被动用法，句中不需要被。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '754b4d02-52a0-4a9b-a662-6693fb895906') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
