INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27144, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "家庭或个人因为要花很多钱而承受的压力。", "primary_collocate": null, "pronunciation": "jīng jì fù dān", "ipa": "tɕiŋ˥ tɕi˥˩ fu˥˩ tan˥", "syllable_count": 4, "sentences": [{"text": "家里有三个孩子，经济负担很大。", "target_word": "经济负担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸生病了，我们家的经济负担很重。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想早点工作，减轻家里的经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买车对我们来说是一个经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房租太贵，成了我的经济负担。", "target_word": "经济负担", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈不想给孩子增加经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学费这么高，对农村家庭是经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有了工作，家里的经济负担小多了。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个月还房贷，给我们带来经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶住院的钱，是全家的经济负担。", "target_word": "经济负担", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "家里要花的钱太多，压力很大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae9372e-bc80-456a-944e-e264df1930d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27144, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经济负担", "is_correct": true, "explanation": "指家里花钱太多带来的压力，与“很大”搭配，符合句意。"}, {"text": "口音", "is_correct": false, "explanation": "语义：“口音”与“家里有三个孩子”无关，句意不通。"}, {"text": "学习成绩", "is_correct": false, "explanation": "搭配：成绩说“好”或“高”，不说“很大”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：形容身高用“高”，不用“大”，句子不通。"}], "explanations": {"经济负担": "指家里花钱太多带来的压力，与“很大”搭配，符合句意。", "口音": "语义：“口音”与“家里有三个孩子”无关，句意不通。", "学习成绩": "搭配：成绩说“好”或“高”，不说“很大”。", "身高": "体貌：形容身高用“高”，不用“大”，句子不通。"}, "sentence_index": 0, "correct_answer": "经济负担"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "社区为困难家庭提供了很大的经济负担。", "explanation": "这里应该用〈经济帮助〉。经济负担指家庭要承担的金钱压力，不能“提供”给别人；给予金钱帮助要说经济帮助。"}, {"text": "公司给优秀员工发放了很多经济负担。", "explanation": "这里应该用〈经济奖励〉。“发放”的是奖金、奖励，经济负担是压力，不能发放。"}, {"text": "这次创作让他获得了不少经济负担。", "explanation": "这里应该用〈经济收入〉。“获得”搭配收入，经济负担是需要承担的压力，不能获得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39bff450-c9af-46a3-9425-4644eeb5ede1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
